        if (!visible || !hasConnectors || !image?.complete || !image.naturalWidth || !image.naturalHeight) {
            svg.innerHTML = '';
            svg.classList.toggle('hidden', !visible || !hasConnectors);
            return;
        }
        const width = Math.max(1, image.naturalWidth);
        const height = Math.max(1, image.naturalHeight);
        const renderedWidth = Math.max(1, image.offsetWidth || stage?.offsetWidth || image.clientWidth || width);
        const screenScale = renderedWidth / width;
        svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
        svg.setAttribute('preserveAspectRatio', 'none');
        svg.setAttribute('shape-rendering', 'geometricPrecision');
        svg.dataset.vectorConnectorLayer = 'true';
        svg.innerHTML = buildDiagramConnectorSvgMarkup(safeLabels, width, height, screenScale, options);
