    async function setQuizStudioSection(sectionName = 'home', options = {}) {
        const nextSection = ['home', 'folders', 'manage', 'backup', 'import', 'editor', 'diagram-creator', 'review-mode'].includes(sectionName)
            ? sectionName
            : 'home';

        if (!options.force && nextSection !== state.auth.currentStudioSection && state.auth.currentStudioSection === 'editor') {
            if (state.auth.studioExplicitSavePromise || state.auth.studioAutosaveInFlight) {
                setCreatorStatus('Finish saving before switching menus.', 'error');
                return false;
            }
            if (!state.auth.editingQuizId && (state.auth.studioHasUnsavedChanges || hasStudioQuestionDrafts())) {
                // A new quiz must ONLY be created by the user's Create Quiz click.
                if (!window.confirm('This quiz has not been created. Discard this draft and switch menus?')) return false;
                clearCreatorInputs();
            } else if (state.auth.studioHasUnsavedChanges || hasStudioQuestionDrafts()) {
                const saved = await autosaveStudioChanges({ reason: `switch to the ${nextSection} section`, allowCreate: true });
                if (!saved) return false;
            }
        }

        state.auth.currentStudioSection = nextSection;
        closeAppPageMenu();

        elements.quizStudioSections.forEach(section => {
            const isActive = section.dataset.studioSection === nextSection;
            section.classList.toggle('hidden', !isActive);
            section.classList.toggle('is-active', isActive);
        });

        elements.quizStudioSectionButtons.forEach(button => {
            const isActive = button.dataset.studioSectionTarget === nextSection;
            button.classList.toggle('active', isActive);
            button.setAttribute('aria-selected', isActive ? 'true' : 'false');
        });
        if (nextSection === 'review-mode') {
            await syncStudioSavedImagesFromSupabase({ force: true, reason: 'open-review-mode' });
            renderReviewModeLibrary();
        } else if (nextSection === 'diagram-creator') {
            await syncStudioSavedImagesFromSupabase({ force: true, reason: 'open-diagram-creator' });
            setDiagramCreatorLibraryView(getDiagramCreatorLibraryState().view);
            if (getReviewModeState().overlayOpen) closeReviewModeImage();
        } else if (getReviewModeState().overlayOpen) {
            closeReviewModeImage();
        }
        return true;
    }

