    async function importGoogleSheetsQuestionsToSupabaseQuiz(quizId, questions, options = {}) {
        const total = questions.length;
        const startSortOrder = Number.isFinite(Number(options.startSortOrder)) ? Number(options.startSortOrder) : 0;
        const onProgress = typeof options.onProgress === 'function' ? options.onProgress : null;
        if (onProgress) onProgress({ phase: 'questions-start', current: 0, total });
        for (let index = 0; index < total; index += 1) {
            const question = questions[index];
            const sortOrder = startSortOrder + index;
            const questionType = getQuestionTypeForImport(question);
            if (onProgress) onProgress({ phase: 'question', current: index + 1, total, questionType });
            if (questionType === 'flashcard') {
                await importFlashcardQuestionToSupabase(quizId, question, sortOrder);
            } else if (questionType === 'hierarchy') {
                await importHierarchyQuestionToSupabase(quizId, question, sortOrder);
            } else if (questionType === 'classify') {
                await importClassifyQuestionToSupabase(quizId, question, sortOrder);
            } else if (questionType === 'typed_answer') {
                await importTypedAnswerQuestionToSupabase(quizId, question, sortOrder);
            } else {
                await importMultipleChoiceQuestionToSupabase(quizId, question, sortOrder);
            }
            if (onProgress) onProgress({ phase: 'question-complete', current: index + 1, total, questionType });
        }
    }

    function setImportProgressFromEvent(operationLabel, progress = {}) {
        const current = Number(progress.current || 0);
        const total = Number(progress.total || 0);
        if (progress.phase === 'reading') {
            setCreatorProgressStatus(operationLabel, 'reading source questions');
        } else if (progress.phase === 'creating-quiz') {
            setCreatorProgressStatus(operationLabel, 'creating quiz');
        } else if (progress.phase === 'appending-quiz') {
            setCreatorProgressStatus(operationLabel, 'checking existing quiz');
        } else if ((progress.phase === 'question' || progress.phase === 'question-complete') && total) {
            setCreatorProgressStatus(operationLabel, `adding question ${current} of ${total}`);
        } else if (progress.phase === 'refreshing') {
            setCreatorProgressStatus(operationLabel, 'refreshing Quiz Studio');
        }
    }

    async function importGoogleSheetsQuizDescriptorToSupabase(quizDescriptor, targetFolderId = '', options = {}) {
        const descriptor = isQuizDescriptor(quizDescriptor) ? quizDescriptor : getQuizBySelectorValue(quizDescriptor);
        if (!descriptor || descriptor.source !== DATA_SOURCES.GOOGLE_SHEETS) {
            throw new Error('Choose a valid Google Sheets quiz to import.');
        }

        const onProgress = typeof options.onProgress === 'function' ? options.onProgress : null;
        if (onProgress) onProgress({ phase: 'reading', quizName: descriptor.name });
        const sourceQuestions = await loadQuestionsFromGoogleSheets(descriptor.sheet);
        const quizType = validateGoogleSheetImportQuestions(sourceQuestions, 'The selected Google Sheets quiz');

        const appendToQuizId = normalizeSupabaseQuizId(options.appendToQuizId);
        if (appendToQuizId) {
            const appendContext = await getImportAppendTargetContext(appendToQuizId);
            validateImportAppendTarget(appendContext, quizType);
            if (onProgress) onProgress({ phase: 'appending-quiz', quizName: appendContext.quizName, total: sourceQuestions.length });
            await importGoogleSheetsQuestionsToSupabaseQuiz(appendContext.quizId, sourceQuestions, {
                startSortOrder: appendContext.maxSortOrder + 1,
                onProgress: progress => onProgress?.({ ...progress, quizName: appendContext.quizName })
            });
            return {
                quizId: appendContext.quizId,
                quizName: appendContext.quizName,
                sourceQuizName: descriptor.name,
                questionCount: sourceQuestions.length,
                totalQuestionCount: appendContext.questionCount + sourceQuestions.length,
                quizType,
                folderId: appendContext.folderId,
                appended: true
            };
        }

        if (onProgress) onProgress({ phase: 'creating-quiz', quizName: descriptor.name, total: sourceQuestions.length });
        const folderId = await ensureImportTargetFolderId(targetFolderId, descriptor.folder);
        const nextSortOrder = state.auth.managedQuizzes
            .filter(quiz => (quiz.folderId || '') === (folderId || ''))
            .reduce((maxValue, quiz) => Math.max(maxValue, Number(quiz.sortOrder ?? 0)), -1) + 1;

        const { data: quizRow, error: quizError } = await state.auth.client
            .from('quizzes')
            .insert({
                user_id: state.auth.user.id,
                folder_id: folderId || null,
                name: descriptor.name,
                description: '',
                sort_order: nextSortOrder,
                is_archived: false
            })
            .select('id')
            .single();
        if (quizError) throw quizError;

        await importGoogleSheetsQuestionsToSupabaseQuiz(quizRow.id, sourceQuestions, {
            onProgress: progress => onProgress?.({ ...progress, quizName: descriptor.name })
        });
        return { quizId: quizRow.id, quizName: descriptor.name, questionCount: sourceQuestions.length, quizType, folderId };
    }


    function normalizeJsonQuizQuestionType(value = '') {
        const key = normalizeSheetText(value).toLowerCase().replace(/[\s-]+/g, '_');
        const aliases = {
            mc: 'multiple_choice',
            mcq: 'multiple_choice',
            multiplechoice: 'multiple_choice',
            multiple_choice: 'multiple_choice',
            typed: 'typed_answer',
            typedanswer: 'typed_answer',
            typed_answer: 'typed_answer',
            hierarchy: 'hierarchy',
            classify: 'classify',
            classification: 'classify',
            flashcard: 'flashcard',
            flashcards: 'flashcard',
            diagram: 'diagrams',
            diagrams: 'diagrams'
        };
        return aliases[key] || aliases[key.replace(/_/g, '')] || '';
    }

    function normalizeJsonQuizMode(value = '') {
        const key = normalizeSheetText(value).toLowerCase().replace(/[\s-]+/g, '_');
        if (key === 'exam') return 'exam';
        return normalizeJsonQuizQuestionType(key);
    }

    function normalizeJsonClassifications(raw = []) {
        if (Array.isArray(raw)) {
            return raw.map((entry, index) => {
                if (typeof entry === 'string') return { id: `class_${index + 1}`, label: normalizeSheetText(entry), imageUrl: '' };
                return {
                    id: normalizeSheetText(entry?.id || entry?.value || `class_${index + 1}`),
                    label: normalizeSheetText(entry?.label || entry?.name || entry?.text),
                    imageUrl: normalizeSheetText(entry?.imageUrl || entry?.image_url)
                };
            });
        }
        if (raw && typeof raw === 'object') {
            return Object.keys(raw).map((key, index) => ({ id: normalizeSheetText(key || `class_${index + 1}`), label: normalizeSheetText(key), imageUrl: '' }));
        }
        return [];
    }

    function normalizeJsonClassifyItems(rawQuestion = {}, classifications = []) {
        const rawItems = rawQuestion.items || rawQuestion.classifyItems || rawQuestion.classify_items;
        if (Array.isArray(rawItems)) {
            return rawItems.map((item, index) => ({
                kind: normalizeSheetText(item?.kind || (item?.imageUrl || item?.image_url ? 'image' : 'text')) || 'text',
                raw: normalizeSheetText(item?.raw || item?.text || item?.label || `item_${index + 1}`),
                text: normalizeSheetText(item?.text || item?.raw || item?.label),
                imageUrl: normalizeSheetText(item?.imageUrl || item?.image_url),
                dragLabel: normalizeSheetText(item?.dragLabel || item?.drag_label || item?.text || item?.raw || item?.label),
                ariaLabel: normalizeSheetText(item?.ariaLabel || item?.aria_label),
                correctClassificationId: normalizeSheetText(item?.correctClassificationId || item?.classificationId || item?.categoryId || item?.correct_classification_id)
            }));
        }
        const categoriesObject = rawQuestion.categories;
        if (categoriesObject && typeof categoriesObject === 'object' && !Array.isArray(categoriesObject)) {
            const items = [];
            Object.entries(categoriesObject).forEach(([categoryLabel, values], categoryIndex) => {
                const matched = classifications.find(item => item.label === categoryLabel || item.id === categoryLabel);
                const categoryId = matched?.id || `class_${categoryIndex + 1}`;
                (Array.isArray(values) ? values : []).forEach((value, itemIndex) => {
                    const text = typeof value === 'string' ? value : (value?.text || value?.raw || value?.label || '');
                    items.push({ kind: 'text', raw: normalizeSheetText(text || `item_${itemIndex + 1}`), text: normalizeSheetText(text), imageUrl: '', dragLabel: normalizeSheetText(text), ariaLabel: '', correctClassificationId: categoryId });
                });
            });
            return items;
        }
        return [];
    }

    function normalizeJsonQuizQuestion(rawQuestion = {}, index = 0, overallMode = '') {
        const issues = [];
        let questionType = normalizeJsonQuizQuestionType(rawQuestion.questionType || rawQuestion.question_type || rawQuestion.type);
        if (!questionType) {
            questionType = overallMode === 'exam' ? 'multiple_choice' : (overallMode || 'multiple_choice');
            issues.push('Question Type is missing or unsupported; defaulted to Multiple Choice.');
        }
        if (overallMode === 'exam' && !EXAM_QUESTION_TYPES.includes(questionType)) {
            issues.push(`${getImportQuizTypeLabel(questionType)} is not supported inside Exam; defaulted to Multiple Choice.`);
            questionType = 'multiple_choice';
        }

        const prompt = normalizeSheetText(rawQuestion.question || rawQuestion.prompt || rawQuestion.promptText || rawQuestion.prompt_plain);
        const learningResources = normalizeSheetText(rawQuestion.learningResources || rawQuestion.learning_resources || rawQuestion.explanationResources);
        const image = normalizeSheetText(rawQuestion.image || rawQuestion.imageUrl || rawQuestion.image_url);
        const learningResourcesImage = normalizeSheetText(rawQuestion.learningResourcesImage || rawQuestion.learning_resources_image || rawQuestion.learning_resources_image_url);
        const base = { type: questionType.replace(/_/g, ' '), questionType, question: prompt, learningResources, image, learningResourcesImage, importIssues: issues };

        if (questionType === 'flashcard') {
            base.type = 'flashcard';
            base.termText = normalizeSheetText(rawQuestion.termText || rawQuestion.term || rawQuestion.front);
            base.definitionText = normalizeSheetText(rawQuestion.definitionText || rawQuestion.definition || rawQuestion.back);
            base.termImage = normalizeSheetText(rawQuestion.termImage || rawQuestion.frontImage);
            base.definitionImage = normalizeSheetText(rawQuestion.definitionImage || rawQuestion.backImage);
            base.buildUp = normalizeBuildUpValue(rawQuestion.buildUp || rawQuestion.build_up);
            if (!base.termText && !base.termImage) issues.push('Flashcard term/front is empty.');
            if (!base.definitionText && !base.definitionImage) issues.push('Flashcard definition/back is empty.');
            return base;
        }

        if (!prompt) issues.push('Question prompt is empty.');

        if (questionType === 'typed_answer') {
            base.type = 'typed_answer';
            base.acceptedAnswers = normalizeTypedAnswerVariants(rawQuestion.acceptedAnswers || rawQuestion.accepted_answers || rawQuestion.variants || [rawQuestion.correctAnswer || rawQuestion.correct]);
            base.correct = base.acceptedAnswers[0] || '';
            base.correctExplanation = normalizeSheetText(rawQuestion.correctExplanation || rawQuestion.correct_explanation || rawQuestion.explanation);
            base.diagramLabels = normalizeDiagramLabels(rawQuestion.diagramLabels || rawQuestion.diagram_labels || []);
            if (!base.acceptedAnswers.length) issues.push('Typed Answer has no accepted answer.');
            return base;
        }

        if (questionType === 'hierarchy') {
            base.type = 'hierarchy';
            const rawItems = Array.isArray(rawQuestion.items) ? rawQuestion.items : (Array.isArray(rawQuestion.options) ? rawQuestion.options : []);
            base.options = rawItems.map(item => normalizeSheetText(typeof item === 'string' ? item : (item?.text || item?.label || item?.value))).filter(Boolean);
            const suppliedOrder = Array.isArray(rawQuestion.correctOrder || rawQuestion.correct_order) ? (rawQuestion.correctOrder || rawQuestion.correct_order) : [];
            base.correctOrder = suppliedOrder.length ? suppliedOrder.map(Number) : base.options.map((_, itemIndex) => itemIndex + 1);
            if (base.options.length < 2) issues.push('Hierarchy needs at least 2 items.');
            if (base.correctOrder.length !== base.options.length) issues.push('Hierarchy correct order must contain one position for every item.');
            const validPositions = base.correctOrder.every(value => Number.isInteger(value) && value >= 1 && value <= base.options.length);
            if (!validPositions || new Set(base.correctOrder).size !== base.correctOrder.length) issues.push('Hierarchy correct-order positions must be unique whole numbers within the item range.');
            return base;
        }

        if (questionType === 'classify') {
            base.type = 'classify';
            let classifications = normalizeJsonClassifications(rawQuestion.classifications || rawQuestion.classes || rawQuestion.categories || []);
            if (!classifications.length && rawQuestion.categories && typeof rawQuestion.categories === 'object' && !Array.isArray(rawQuestion.categories)) {
                classifications = Object.keys(rawQuestion.categories).map((label, classIndex) => ({ id: `class_${classIndex + 1}`, label: normalizeSheetText(label), imageUrl: '' }));
            }
            base.classifications = classifications;
            base.items = normalizeJsonClassifyItems(rawQuestion, classifications);
            const classIds = new Set(classifications.map(item => normalizeSheetText(item.id)).filter(Boolean));
            if (!classifications.length) issues.push('Classify has no classifications/categories.');
            if (!base.items.length) issues.push('Classify has no items.');
            if (classifications.some(item => !normalizeSheetText(item.id) || (!normalizeSheetText(item.label) && !normalizeSheetText(item.imageUrl)))) issues.push('Every classification needs an ID and a label or image.');
            const invalidItems = base.items.filter(item => !classIds.has(normalizeSheetText(item.correctClassificationId)));
            if (invalidItems.length) issues.push(`${invalidItems.length} classify ${invalidItems.length === 1 ? 'item has' : 'items have'} a missing or invalid classification.`);
            return base;
        }

        base.type = questionType === 'diagrams' ? 'diagrams' : 'multiple choice';
        base.diagramLabels = normalizeDiagramLabels(rawQuestion.diagramLabels || rawQuestion.diagram_labels || []);
        const rawOptions = Array.isArray(rawQuestion.options) ? rawQuestion.options : [];
        base.options = rawOptions.map(option => normalizeSheetText(typeof option === 'string' ? option : (option?.text || option?.label || option?.value))).filter(Boolean);
        base.explanations = rawOptions.map(option => typeof option === 'object' ? normalizeSheetText(option?.explanation || option?.feedback) : '');
        let correctAnswers = rawQuestion.correctAnswers || rawQuestion.correct_answers;
        if (!Array.isArray(correctAnswers)) correctAnswers = [rawQuestion.correctAnswer ?? rawQuestion.correct ?? rawQuestion.answer].filter(value => value !== undefined && value !== null);
        correctAnswers = correctAnswers.map(value => {
            if (Number.isInteger(Number(value)) && String(value).trim() !== '') {
                const oneBased = Number(value);
                if (oneBased >= 1 && oneBased <= base.options.length) return base.options[oneBased - 1];
            }
            return normalizeSheetText(value);
        }).filter(Boolean);
        base.correctAnswers = Array.from(new Set(correctAnswers));
        base.correct = base.correctAnswers[0] || '';
        base.allowMultipleAnswers = !!(rawQuestion.allowMultipleAnswers ?? rawQuestion.allow_multiple_answers) || base.correctAnswers.length > 1;
        base.buildUp = normalizeBuildUpValue(rawQuestion.buildUp || rawQuestion.build_up);
        if (base.options.length < 2) issues.push('Multiple Choice needs at least 2 filled options.');
        if (!base.correctAnswers.length) issues.push('Multiple Choice has no correct answer.');
        const missingCorrect = base.correctAnswers.filter(answer => !base.options.includes(answer));
        if (missingCorrect.length) issues.push('One or more correct answers do not exactly match an option.');
        if (new Set(base.options.map(value => value.toLocaleLowerCase())).size !== base.options.length) issues.push('Multiple Choice contains duplicate options.');
        return base;
    }

    function analyzeJsonQuizPayload(payload = {}) {
        const rawQuestions = Array.isArray(payload) ? payload : (Array.isArray(payload?.questions) ? payload.questions : []);
        if (!rawQuestions.length) throw new Error('This JSON file does not contain a non-empty questions array.');
        let requestedMode = Array.isArray(payload) ? '' : normalizeJsonQuizMode(payload.quizType || payload.quiz_type || payload.type || payload.mode);
        let provisionalMode = requestedMode || 'multiple_choice';
        let questions = rawQuestions.map((question, index) => normalizeJsonQuizQuestion(question || {}, index, provisionalMode));
        const uniqueTypes = Array.from(new Set(questions.map(question => question.questionType)));
        let quizType = requestedMode;
        if (!quizType) quizType = uniqueTypes.length > 1 ? 'exam' : (uniqueTypes[0] || 'multiple_choice');
        if (quizType !== 'exam' && uniqueTypes.some(type => type !== quizType)) {
            quizType = 'exam';
            questions = rawQuestions.map((question, index) => normalizeJsonQuizQuestion(question || {}, index, 'exam'));
        }
        if (quizType === 'exam') {
            questions = rawQuestions.map((question, index) => normalizeJsonQuizQuestion(question || {}, index, 'exam'));
        }
        const counts = questions.reduce((map, question) => {
            map[question.questionType] = (map[question.questionType] || 0) + 1;
            return map;
        }, {});
        const problemQuestions = questions.map((question, index) => ({ number: index + 1, type: question.questionType, issues: question.importIssues || [] })).filter(item => item.issues.length);
        return {
            format: Array.isArray(payload) ? '' : normalizeSheetText(payload.format),
            version: Array.isArray(payload) ? 1 : Number(payload.version || 1),
            title: Array.isArray(payload) ? '' : normalizeSheetText(payload.title || payload.name),
            quizType,
            questions,
            counts,
            problemQuestions
        };
    }

    function renderJsonQuizImportPreview() {
        if (!elements.importJsonPreview) return;
        const analysis = state.auth.jsonQuizImportAnalysis;
        if (!analysis) {
            elements.importJsonPreview.innerHTML = '<span>Choose a Study Bunny quiz JSON file to preview it locally before importing.</span>';
            elements.importJsonPreview.classList.remove('is-error', 'is-success');
            return;
        }
        const typeSummary = Object.entries(analysis.counts).map(([type, count]) => `${count} ${getImportQuizTypeLabel(type)}`).join(' · ');
        const issueCount = analysis.problemQuestions.length;
        const issuesHtml = issueCount
            ? `<details class="json-import-issues" open><summary>${issueCount} ${issueCount === 1 ? 'question needs' : 'questions need'} attention</summary><div class="json-import-issue-list">${analysis.problemQuestions.map(item => `<div><strong>Q${item.number} · ${escapeHtml(getImportQuizTypeLabel(item.type))}</strong><ul>${item.issues.map(issue => `<li>${escapeHtml(issue)}</li>`).join('')}</ul></div>`).join('')}</div></details>`
            : '<div class="json-import-valid">No question issues detected.</div>';
        elements.importJsonPreview.innerHTML = `<div><strong>${escapeHtml(getImportQuizTypeLabel(analysis.quizType))}</strong> · ${analysis.questions.length} ${analysis.questions.length === 1 ? 'question' : 'questions'}${typeSummary ? ` · ${escapeHtml(typeSummary)}` : ''}</div>${issuesHtml}`;
        elements.importJsonPreview.classList.toggle('is-success', !issueCount);
        elements.importJsonPreview.classList.remove('is-error');
    }

    async function readAndPreviewJsonQuizFile() {
        const file = elements.importJsonQuizFile?.files?.[0];
        state.auth.jsonQuizImportPayload = null;
        state.auth.jsonQuizImportAnalysis = null;
        state.auth.jsonQuizImportFileName = file?.name || '';
        if (!file) {
            renderJsonQuizImportPreview();
            renderGoogleSheetsImportControls();
            return null;
        }
        let payload;
        try {
            payload = JSON.parse(await file.text());
        } catch (error) {
            if (elements.importJsonPreview) {
                elements.importJsonPreview.textContent = `JSON syntax error: ${error.message}`;
                elements.importJsonPreview.classList.add('is-error');
                elements.importJsonPreview.classList.remove('is-success');
            }
            renderGoogleSheetsImportControls();
            throw new Error(`Could not parse this JSON file. ${error.message}`);
        }
        const analysis = analyzeJsonQuizPayload(payload);
        state.auth.jsonQuizImportPayload = payload;
        state.auth.jsonQuizImportAnalysis = analysis;
        if (elements.importJsonQuizNameInput && !normalizeSheetText(elements.importJsonQuizNameInput.value)) {
            elements.importJsonQuizNameInput.value = analysis.title || file.name.replace(/\.json$/i, '');
        }
        renderJsonQuizImportPreview();
        renderGoogleSheetsImportControls();
        return analysis;
    }

    function updateLocalManagementCacheAfterJsonImport(result = {}) {
        const quizId = normalizeSheetText(result.quizId);
        if (!quizId) return;
        const folder = state.auth.supabaseFolders.find(item => item.id === result.folderId) || null;
        const typeLabel = getImportQuizTypeLabel(result.quizType);
        const existingIndex = state.auth.managedQuizzes.findIndex(quiz => quiz.id === quizId);
        if (existingIndex >= 0) {
            state.auth.managedQuizzes[existingIndex] = {
                ...state.auth.managedQuizzes[existingIndex],
                quizType: result.quizType || state.auth.managedQuizzes[existingIndex].quizType,
                typeLabel,
                questionCount: Number(result.totalQuestionCount ?? result.questionCount ?? state.auth.managedQuizzes[existingIndex].questionCount)
            };
        } else {
            state.auth.managedQuizzes.push({
                id: quizId,
                name: result.quizName,
                folderId: result.folderId || '',
                folderName: folder ? normalizeFolderName(folder.name) : '',
                classId: normalizeSheetText(folder?.classId),
                className: '',
                questionCount: Number(result.questionCount || 0),
                isArchived: false,
                questionIds: [],
                quizType: result.quizType || 'multiple_choice',
                typeLabel,
                hasBuildUpStrings: false,
                sortOrder: Number(result.sortOrder || 0),
                updatedAt: new Date().toISOString(),
                firstQuestionId: ''
            });
        }
        const managedCache = getSupabaseManagementCacheEntry('managedQuizzes') || {};
        setSupabaseManagementCacheEntry('managedQuizzes', {
            ...managedCache,
            managedQuizzes: state.auth.managedQuizzes,
            quizChallengeAchievements: cloneQuizChallengeAchievementMap(state.auth.quizChallengeAchievements),
            quizSpacedReviews: [...state.auth.quizSpacedReviews],
            quizSpacedContentRevisions: [...state.auth.quizSpacedContentRevisions],
            quizSpacedMigrationMissing: state.auth.quizSpacedMigrationMissing,
            quizChallengeUnavailable: !!state.auth.quizChallengeUnavailable,
            studioActivity: cloneStudioActivityCache(state.auth.studioActivity)
        });
        setSupabaseManagementCacheEntry('quizList', { quizList: buildSupabaseQuizDescriptorsFromManagedQuizzes() });
        renderQuizManagementList();
        renderStudioHomeDashboard();
        renderGoogleSheetsImportControls();
    }

    async function importJsonQuizToSupabase() {
        if (!state.auth.client || !state.auth.user?.id) throw new Error('Sign in before importing JSON quizzes.');
        const analysis = state.auth.jsonQuizImportAnalysis;
        if (!analysis?.questions?.length) throw new Error('Choose and preview a valid JSON quiz file first.');
        const appendMode = isImportAppendMode(elements.importJsonDestinationModeSelect);
        let quizId = '';
        let quizName = '';
        let folderId = '';
        let startSortOrder = 0;
        let totalQuestionCount = analysis.questions.length;
        let resultQuizType = analysis.quizType;
        let sortOrder = 0;

        if (appendMode) {
            const appendContext = await getImportAppendTargetContext(elements.importJsonAppendQuizSelect?.value);
            validateImportAppendTarget(appendContext, analysis.quizType);
            quizId = appendContext.quizId;
            quizName = appendContext.quizName;
            folderId = appendContext.folderId;
            startSortOrder = appendContext.maxSortOrder + 1;
            totalQuestionCount = appendContext.questionCount + analysis.questions.length;
            resultQuizType = appendContext.quizType === 'exam' ? 'exam' : analysis.quizType;
        } else {
            quizName = normalizeSheetText(elements.importJsonQuizNameInput?.value) || analysis.title || state.auth.jsonQuizImportFileName.replace(/\.json$/i, '') || 'Imported Quiz';
            folderId = normalizeSheetText(elements.importJsonTargetFolderSelect?.value);
            sortOrder = state.auth.managedQuizzes.filter(quiz => (quiz.folderId || '') === (folderId || '')).reduce((maxValue, quiz) => Math.max(maxValue, Number(quiz.sortOrder ?? 0)), -1) + 1;
            const description = setQuizModeInDescription('', analysis.quizType);
            const { data: quizRow, error: quizError } = await state.auth.client.from('quizzes').insert({
                user_id: state.auth.user.id,
                folder_id: folderId || null,
                name: quizName,
                description,
                sort_order: sortOrder,
                is_archived: false
            }).select('id').single();
            if (quizError) throw quizError;
            quizId = quizRow.id;
        }

        const operationLabel = appendMode ? `Adding JSON questions to ${quizName}` : `Importing ${quizName}`;
        await importGoogleSheetsQuestionsToSupabaseQuiz(quizId, analysis.questions, {
            startSortOrder,
            onProgress: progress => setImportProgressFromEvent(operationLabel, progress)
        });
        const result = {
            quizId,
            quizName,
            folderId,
            quizType: resultQuizType,
            questionCount: analysis.questions.length,
            totalQuestionCount,
            appended: appendMode,
            sortOrder
        };
        updateLocalManagementCacheAfterJsonImport(result);
        await refreshQuizCatalog({ selectQuizId: `sb:${quizId}` });
        renderJsonQuizImportPreview();
        const issueCount = analysis.problemQuestions.length;
        setCreatorStatus(`${appendMode ? 'JSON questions added' : 'JSON quiz imported'}: ${analysis.questions.length} questions${issueCount ? `; ${issueCount} ${issueCount === 1 ? 'question needs' : 'questions need'} attention and will show ! in the question list` : '; no issues detected'}.`, issueCount ? 'neutral' : 'success');
        return result;
    }



    function normalizeImportSectionValue(value) {
        return normalizeSheetText(value).replace(/^'+/, '').replace(/\s+/g, ' ');
    }

    function normalizeBuildUpValue(value) {
        return normalizeSheetText(value).replace(/^'+/, '').replace(/\s+/g, ' ');
    }

    function getBuildUpValueFromOptionsJson(optionsJson) {
        if (!optionsJson || typeof optionsJson !== 'object') return '';
        if (!Array.isArray(optionsJson)) {
            return normalizeBuildUpValue(
                optionsJson.buildUp
                || optionsJson.build_up
                || optionsJson.buildUpGroup
                || optionsJson.build_up_group
            );
        }
        const optionWithBuildUp = optionsJson.find(item => normalizeBuildUpValue(item?.buildUp || item?.build_up || item?.buildUpGroup || item?.build_up_group));
        return normalizeBuildUpValue(
            optionWithBuildUp?.buildUp
            || optionWithBuildUp?.build_up
            || optionWithBuildUp?.buildUpGroup
            || optionWithBuildUp?.build_up_group
        );
    }

    function parseAllowMultipleAnswersValue(value) {
        const normalized = normalizeSheetText(value).toLowerCase();
        return ['true', 'yes', 'y', '1', 'multi', 'multiple', 'allow'].includes(normalized);
    }

    function splitCorrectAnswerList(value = '') {
        const normalized = normalizeSheetText(value);
        if (!normalized) return [];
        return normalized.split('|').map(item => normalizeSheetText(item)).filter(Boolean);
    }

    function isMultipleAnswerOptionsJson(optionsJson) {
        if (!optionsJson || typeof optionsJson !== 'object' || Array.isArray(optionsJson)) return false;
        return optionsJson.allowMultipleAnswers === true
            || optionsJson.allow_multiple_answers === true
            || parseAllowMultipleAnswersValue(optionsJson.allowMultipleAnswers)
            || parseAllowMultipleAnswersValue(optionsJson.allow_multiple_answers)
            || (Array.isArray(optionsJson.correctAnswers) && optionsJson.correctAnswers.length > 1)
            || (Array.isArray(optionsJson.correct_answers) && optionsJson.correct_answers.length > 1);
    }

    function getCorrectAnswersFromOptionsJson(optionsJson) {
        if (!optionsJson || typeof optionsJson !== 'object' || Array.isArray(optionsJson)) return [];
        const raw = Array.isArray(optionsJson.correctAnswers)
            ? optionsJson.correctAnswers
            : (Array.isArray(optionsJson.correct_answers) ? optionsJson.correct_answers : []);
        return raw.map(value => normalizeSheetText(value)).filter(Boolean);
    }

    function getMultipleChoiceCorrectAnswersFromDetailRow(detailRow = {}) {
        const fromJson = getCorrectAnswersFromOptionsJson(detailRow?.options_json);
        if (fromJson.length) return fromJson;
        const fallback = normalizeSheetText(detailRow?.correct_answer);
        return fallback ? [fallback] : [];
    }

    function getAllowMultipleAnswersFromDetailRow(detailRow = {}) {
        const correctAnswers = getMultipleChoiceCorrectAnswersFromDetailRow(detailRow);
        return isMultipleAnswerOptionsJson(detailRow?.options_json) || correctAnswers.length > 1;
    }

    function getCorrectOptionNumbersForEditor(detailRow = {}, optionDrafts = []) {
        const answers = getMultipleChoiceCorrectAnswersFromDetailRow(detailRow);
        if (!answers.length) return ['1'];
        const values = optionDrafts.map(getOptionAnswerValue);
        const numbers = answers
            .map(answer => values.findIndex(value => value === answer))
            .filter(index => index >= 0)
            .map(index => String(index + 1));
        return numbers.length ? numbers : ['1'];
    }

    function buildMultipleChoiceOptionsJsonPayload(optionPayload = [], buildUpValue = '', answerOptions = {}) {
        const normalizedBuildUp = normalizeBuildUpValue(buildUpValue);
        const allowMultipleAnswers = !!answerOptions.allowMultipleAnswers;
        const correctAnswers = Array.isArray(answerOptions.correctAnswers)
            ? answerOptions.correctAnswers.map(value => normalizeSheetText(value)).filter(Boolean)
            : [];
        const questionImageLabels = normalizeDiagramLabels(answerOptions.questionImageLabels || []);
        if (normalizedBuildUp || allowMultipleAnswers || correctAnswers.length > 1 || questionImageLabels.length) {
            return {
                options: optionPayload,
                ...(normalizedBuildUp ? { buildUp: normalizedBuildUp } : {}),
                ...(allowMultipleAnswers ? { allowMultipleAnswers: true } : {}),
                ...(correctAnswers.length ? { correctAnswers } : {}),
                ...(questionImageLabels.length ? { questionImageLabels } : {})
            };
        }
        return optionPayload;
    }

    async function getMultipleChoiceBuildUpByQuestionId(questionId = '') {
        const normalizedQuestionId = normalizeSheetText(questionId);
        if (!normalizedQuestionId) return '';
        try {
            const detail = await loadMultipleChoiceDetailByQuestionId(normalizedQuestionId);
            return getBuildUpValueFromOptionsJson(detail?.options_json);
        } catch (error) {
            console.warn('Could not load existing Build Up string metadata:', error);
            return '';
        }
    }

    function getSectionedImportGroups(sourceQuestions = []) {
        const groups = [];
        const groupMap = new Map();
        sourceQuestions.forEach(question => {
            const section = normalizeImportSectionValue(question?.section);
            const key = section || '__unsectioned__';
            if (!groupMap.has(key)) {
                const group = { section, questions: [] };
                groupMap.set(key, group);
                groups.push(group);
            }
            groupMap.get(key).questions.push(question);
        });
        return groups;
    }

    function buildSectionedImportQuizName(baseQuizName, fallbackQuizName, section = '') {
        const resolvedBase = normalizeSheetText(baseQuizName) || normalizeSheetText(fallbackQuizName) || 'Imported quiz';
        const resolvedSection = normalizeImportSectionValue(section);
        return resolvedSection ? `${resolvedBase} - ${resolvedSection}` : resolvedBase;
    }

    async function importGoogleSheetTemplateToSupabase(sheetInput, sheetTabName, quizName, targetFolderId = '', options = {}) {
        const sheetId = extractGoogleSheetId(sheetInput);
        if (!sheetId) {
            throw new Error('Paste a valid Google Sheets URL or sheet ID.');
        }

        const resolvedTabName = normalizeSheetText(sheetTabName);
        if (!resolvedTabName) {
            throw new Error('Enter the Google Sheets tab name from your template.');
        }

        const onProgress = typeof options.onProgress === 'function' ? options.onProgress : null;
        if (onProgress) onProgress({ phase: 'reading', quizName: resolvedTabName });
        const sourceQuestions = await loadQuestionsFromGoogleSheetDocument(sheetId, resolvedTabName);
        const quizType = validateGoogleSheetImportQuestions(sourceQuestions, 'That Google Sheet tab');

        const appendToQuizId = normalizeSupabaseQuizId(options.appendToQuizId);
        if (appendToQuizId) {
            const appendContext = await getImportAppendTargetContext(appendToQuizId);
            validateImportAppendTarget(appendContext, quizType);
            if (onProgress) onProgress({ phase: 'appending-quiz', quizName: appendContext.quizName, total: sourceQuestions.length });
            await importGoogleSheetsQuestionsToSupabaseQuiz(appendContext.quizId, sourceQuestions, {
                startSortOrder: appendContext.maxSortOrder + 1,
                onProgress: progress => onProgress?.({ ...progress, quizName: appendContext.quizName })
            });
            return {
                quizId: appendContext.quizId,
                quizName: appendContext.quizName,
                sourceQuizName: resolvedTabName,
                questionCount: sourceQuestions.length,
                totalQuestionCount: appendContext.questionCount + sourceQuestions.length,
                quizType,
                folderId: appendContext.folderId,
                appended: true
            };
        }

        const folderId = normalizeSheetText(targetFolderId);
        const nextSortOrder = state.auth.managedQuizzes
            .filter(quiz => (quiz.folderId || '') === (folderId || ''))
            .reduce((maxValue, quiz) => Math.max(maxValue, Number(quiz.sortOrder ?? 0)), -1) + 1;
        const sectionGroups = getSectionedImportGroups(sourceQuestions);
        const createdQuizzes = [];

        for (let groupIndex = 0; groupIndex < sectionGroups.length; groupIndex += 1) {
            const group = sectionGroups[groupIndex];
            const finalQuizName = buildSectionedImportQuizName(quizName, resolvedTabName, group.section);
            if (onProgress) {
                onProgress({
                    phase: 'creating-quiz',
                    quizName: finalQuizName,
                    total: group.questions.length,
                    groupCurrent: groupIndex + 1,
                    groupTotal: sectionGroups.length
                });
            }

            const { data: quizRow, error: quizError } = await state.auth.client
                .from('quizzes')
                .insert({
                    user_id: state.auth.user.id,
                    folder_id: folderId || null,
                    name: finalQuizName,
                    description: '',
                    sort_order: nextSortOrder + groupIndex,
                    is_archived: false
                })
                .select('id')
                .single();
            if (quizError) throw quizError;

            await importGoogleSheetsQuestionsToSupabaseQuiz(quizRow.id, group.questions, {
                onProgress: progress => onProgress?.({
                    ...progress,
                    quizName: finalQuizName,
                    groupCurrent: groupIndex + 1,
                    groupTotal: sectionGroups.length
                })
            });
            createdQuizzes.push({
                quizId: quizRow.id,
                quizName: finalQuizName,
                section: group.section,
                questionCount: group.questions.length
            });
        }

        const firstCreatedQuiz = createdQuizzes[0] || null;
        return {
            quizId: firstCreatedQuiz?.quizId || '',
            quizName: firstCreatedQuiz?.quizName || '',
            questionCount: sourceQuestions.length,
            quizType,
            folderId,
            quizzes: createdQuizzes,
            createdQuizCount: createdQuizzes.length,
            sectioned: createdQuizzes.some(item => normalizeImportSectionValue(item.section))
        };
    }

    async function handleImportGoogleSheetsQuiz() {
        if (!state.auth.client || !state.auth.user?.id) {
            setCreatorStatus('Sign in before importing Google Sheets quizzes.', 'error');
            return;
        }

        const quizDescriptor = getGoogleSheetsQuizDescriptorById(elements.importSourceQuizSelect?.value || '');
        if (!quizDescriptor || quizDescriptor.source !== DATA_SOURCES.GOOGLE_SHEETS) {
            setCreatorStatus('Choose a Google Sheets quiz to import.', 'error');
            return;
        }

        try {
            const appendToQuizId = isImportAppendMode(elements.importSourceDestinationModeSelect)
                ? normalizeSheetText(elements.importSourceAppendQuizSelect?.value)
                : '';
            const targetFolderId = normalizeSheetText(elements.importTargetFolderSelect?.value);
            const result = await importGoogleSheetsQuizDescriptorToSupabase(quizDescriptor, targetFolderId, {
                appendToQuizId,
                onProgress: progress => setImportProgressFromEvent(appendToQuizId ? 'Adding questions' : 'Importing quiz', progress)
            });
            setCreatorProgressStatus(appendToQuizId ? 'Adding questions' : 'Importing quiz', 'refreshing Quiz Studio');
            await refreshStudioManagementData({ force: true });
            await refreshQuizCatalog({ selectQuizId: `sb:${result.quizId}` });
            renderGoogleSheetsImportControls();
            await setQuizStudioSection('manage');
            if (result.appended) {
                setCreatorStatus(`Added ${result.questionCount} ${result.questionCount === 1 ? 'question' : 'questions'} to "${result.quizName}".`, 'success');
            } else {
                setCreatorStatus(`Imported "${result.quizName}" into Supabase.`, 'success');
            }
        } catch (error) {
            console.error(error);
            setCreatorStatus(error.message || 'Could not import the Google Sheets quiz.', 'error');
        }
    }

    async function handleImportGoogleSheetsFolder() {
        if (!state.auth.client || !state.auth.user?.id) {
            setCreatorStatus('Sign in before importing Google Sheets folders.', 'error');
            return;
        }

        const sourceFolderName = normalizeSheetText(elements.importEntireFolderSourceSelect?.value);
        if (!sourceFolderName) {
            setCreatorStatus('Choose a Google Sheets folder to import.', 'error');
            return;
        }

        const sourceQuizzes = getGoogleSheetsQuizzesForFolder(sourceFolderName);
        if (!sourceQuizzes.length) {
            setCreatorStatus('That Google Sheets folder does not contain importable quizzes.', 'error');
            return;
        }

        try {
            const targetFolderId = await ensureImportTargetFolderId(normalizeSheetText(elements.importEntireFolderTargetSelect?.value), sourceFolderName);
            let importedCount = 0;
            for (let index = 0; index < sourceQuizzes.length; index += 1) {
                const descriptor = sourceQuizzes[index];
                const quizPosition = `${index + 1} of ${sourceQuizzes.length}`;
                setCreatorProgressStatus('Importing folder', `quiz ${quizPosition}: ${normalizeSheetText(descriptor.name) || 'Untitled quiz'}`);
                await importGoogleSheetsQuizDescriptorToSupabase(descriptor, targetFolderId, {
                    onProgress: progress => {
                        if ((progress.phase === 'question' || progress.phase === 'question-complete') && progress.total) {
                            setCreatorProgressStatus('Importing folder', `quiz ${quizPosition}, question ${progress.current} of ${progress.total}`);
                        } else if (progress.phase === 'reading') {
                            setCreatorProgressStatus('Importing folder', `quiz ${quizPosition}: reading source questions`);
                        } else if (progress.phase === 'creating-quiz') {
                            setCreatorProgressStatus('Importing folder', `quiz ${quizPosition}: creating quiz`);
                        }
                    }
                });
                importedCount += 1;
            }
            setCreatorProgressStatus('Importing folder', 'refreshing Quiz Studio');
            await refreshStudioManagementData({ force: true });
            await refreshQuizCatalog();
            renderGoogleSheetsImportControls();
            await setQuizStudioSection('manage');
            setCreatorStatus(`Imported ${importedCount} Google Sheets ${importedCount === 1 ? 'quiz' : 'quizzes'} into Supabase.`, 'success');
        } catch (error) {
            console.error(error);
            setCreatorStatus(error.message || 'Could not import that Google Sheets folder.', 'error');
        }
    }


    async function handleImportGoogleSheetTemplate() {
        if (!state.auth.client || !state.auth.user?.id) {
            setCreatorStatus('Sign in before importing a Google Sheet template.', 'error');
            return;
        }

        try {
            const appendToQuizId = isImportAppendMode(elements.importTemplateDestinationModeSelect)
                ? normalizeSheetText(elements.importTemplateAppendQuizSelect?.value)
                : '';
            const result = await importGoogleSheetTemplateToSupabase(
                elements.importTemplateSheetInput?.value,
                elements.importTemplateTabInput?.value,
                elements.importTemplateQuizNameInput?.value,
                normalizeSheetText(elements.importTemplateTargetFolderSelect?.value),
                {
                    appendToQuizId,
                    onProgress: progress => setImportProgressFromEvent(appendToQuizId ? 'Adding questions' : 'Importing template', progress)
                }
            );
            setCreatorProgressStatus(appendToQuizId ? 'Adding questions' : 'Importing template', 'refreshing Quiz Studio');
            await refreshStudioManagementData({ force: true });
            await refreshQuizCatalog(result.quizId ? { selectQuizId: `sb:${result.quizId}` } : {});
            renderGoogleSheetsImportControls();
            await setQuizStudioSection('manage');
            if (result.appended) {
                setCreatorStatus(`Added ${result.questionCount} ${result.questionCount === 1 ? 'question' : 'questions'} to "${result.quizName}".`, 'success');
            } else if (result.sectioned && result.createdQuizCount > 1) {
                const sectionSummary = result.quizzes.map(item => `${item.section || 'base'} (${item.questionCount})`).join(', ');
                setCreatorStatus(`Imported ${result.createdQuizCount} section quizzes from the Google Sheet template: ${sectionSummary}.`, 'success');
            } else {
                setCreatorStatus(`Imported "${result.quizName}" from the Google Sheet template.`, 'success');
            }
        } catch (error) {
            console.error(error);
            setCreatorStatus(error.message || 'Could not import that Google Sheet template.', 'error');
        }
    }
function parseGoogleSheetResponse(text) {
    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    if (start === -1 || end === -1) {
        throw new Error('Could not parse Google Sheets response');
    }
    return JSON.parse(text.substring(start, end + 1));
}

function extractGoogleSheetId(value) {
    const raw = normalizeSheetText(value);
    if (!raw) return '';

    const urlMatch = raw.match(/\/spreadsheets\/d\/([a-zA-Z0-9-_]+)/i) || raw.match(/\/d\/([a-zA-Z0-9-_]+)/i);
    if (urlMatch?.[1]) {
        return urlMatch[1];
    }

    if (/^[a-zA-Z0-9-_]{20,}$/.test(raw)) {
        return raw;
    }

    return '';
}

async function fetchGoogleSheetRows(sheetId, sheetName) {
    const resolvedSheetId = normalizeSheetText(sheetId);
    const resolvedSheetName = normalizeSheetText(sheetName);
    if (!resolvedSheetId || !resolvedSheetName) {
        throw new Error('Enter a valid Google Sheet ID/URL and sheet tab name.');
    }

    const response = await fetch(`https://docs.google.com/spreadsheets/d/${resolvedSheetId}/gviz/tq?sheet=${encodeURIComponent(resolvedSheetName)}`);
    const text = await response.text();
    return parseGoogleSheetResponse(text).table.rows || [];
}

// ================= SHEETS CELL HELPERS =================
function normalizeSheetText(value) {
    return String(value ?? '')
        .replace(/\r\n/g, '\n')
        .replace(/\r/g, '\n')
        .replace(/\u00A0/g, ' ')
        .trim();
}

function getCellValue(cell) {
    if (!cell) return '';

    if (cell.v !== null && cell.v !== undefined) {
        return normalizeSheetText(cell.v);
    }

    if (cell.f !== null && cell.f !== undefined) {
        return normalizeSheetText(cell.f);
    }

    return '';
}

function getSectionCellValue(cell) {
    if (!cell) return '';

    if (cell.f !== null && cell.f !== undefined) {
        return normalizeSheetText(cell.f);
    }

    if (cell.v !== null && cell.v !== undefined) {
        return normalizeSheetText(cell.v);
    }

    return '';
}

function normalizeClassificationId(value) {
    return normalizeSheetText(value);
}

function readFileAsDataUrl(file, options = {}) {
    return new Promise((resolve, reject) => {
        if (!file) {
            resolve('');
            return;
        }
        const maxBytes = options.canvasSetupImport === true ? STUDY_BUNNY_CANVAS_SOURCE_MAX_BYTES : STUDY_BUNNY_IMAGE_MAX_BYTES;
        if (/^image\//i.test(file.type || '') && Number(file.size) > maxBytes) {
            reject(new Error(options.canvasSetupImport === true
                ? 'Canvas Setup source files must be 20 MB or smaller; final flattened images must be 3 MB or smaller.'
                : 'Images must be 3 MB or smaller.'));
            return;
        }

        const reader = new FileReader();
        reader.onload = () => resolve(typeof reader.result === 'string' ? reader.result : '');
        reader.onerror = () => reject(reader.error || new Error('Could not read file.'));
        reader.readAsDataURL(file);
    });
}

function readFileAsText(file) {
    return new Promise((resolve, reject) => {
        if (!file) {
            resolve('');
            return;
        }

        const reader = new FileReader();
        reader.onload = () => resolve(typeof reader.result === 'string' ? reader.result : '');
        reader.onerror = () => reject(reader.error || new Error('Could not read file.'));
        reader.readAsText(file);
    });
}

function parseClassifyItemValue(value) {
    const raw = normalizeSheetText(value);
    if (!raw) return null;

    if (raw.toLowerCase().startsWith('img:')) {
        const imageUrl = normalizeSheetText(raw.slice(4));
        if (!imageUrl) return null;
        return {
            kind: 'image',
            raw,
            imageUrl,
            text: '',
            dragLabel: 'Image item',
            ariaLabel: 'Classify image item'
        };
    }

    return {
        kind: 'text',
        raw,
        imageUrl: '',
        text: raw,
        dragLabel: raw,
        ariaLabel: `Classify item ${raw}`
    };
}

// ================= MODE HELPERS =================
function isRetentionMode() {
    return document.getElementById('retentionMode').checked;
}

function isRetryMode() {
    return document.getElementById('masteryMode').checked;
}

function isMasteryCheckMode() {
    return document.getElementById('masteryCheckMode').checked;
}

function getMasteryCheckThreshold() {
    // Keep official Mastery Check challenges on the original 10-question standard.
    if (isActiveQuizChallenge()) return 10;
    const selected = Number(document.querySelector('input[name="masteryCheckThreshold"]:checked')?.value || 10);
    return [3, 5, 10].includes(selected) ? selected : 10;
}

function syncMasteryCheckThresholdControls() {
    const options = document.getElementById('masteryCheckThresholdOptions');
    const inputs = Array.from(document.querySelectorAll('input[name="masteryCheckThreshold"]'));
    const active = isMasteryCheckMode();
    const challengeLocked = isActiveQuizChallenge();

    if (challengeLocked) {
        const defaultInput = inputs.find(input => input.value === '10');
        if (defaultInput) defaultInput.checked = true;
    }

    if (options) {
        options.classList.toggle('hidden', !active);
        options.classList.toggle('is-locked', challengeLocked);
    }

    inputs.forEach(input => {
        input.disabled = !active || challengeLocked;
    });
}

function isProgressMode() {
    return document.getElementById('progressMode')?.checked || false;
}

function isSpeedMode() {
    return document.getElementById('rapidMode').checked;
}

function isLearningResourcesMode() {
    return document.getElementById('learningResourcesMode').checked;
}

function isAnswerFeedbackHidden() {
    return !!state.answerFeedback.hidden;
}

function isExcludeStarredEnabled() {
    return !!elements.excludeStarredQuestions?.checked;
}

function isOnlyStarredEnabled() {
    return !!elements.onlyStarredQuestions?.checked;
}

function isTetherBuildUpSupportedModeActive() {
    return isRetentionMode() || isRetryMode() || isMasteryCheckMode() || isProgressMode();
}

// ================= OPTION DELAY HELPERS =================
function sanitizeOptionDelaySeconds(value, fallback = 10) {
    const parsed = Math.floor(Number(value));
    if (!Number.isFinite(parsed) || parsed <= 0) return fallback;
    return Math.min(parsed, 300);
}

function isOptionDelaySupportedQuestion(question = {}) {
    return question?.type === 'multiple choice' || question?.type === 'diagrams';
}

function isOptionDelayEnabledForQuestion(question = state.questionQueue[state.currentIndex]) {
    return !!state.optionDelay.enabled && isOptionDelaySupportedQuestion(question);
}

function getOptionDelayDurationSeconds() {
    if (!state.optionDelay.enabled) return 0;
    if (state.optionDelay.preset === 'custom') {
        return sanitizeOptionDelaySeconds(state.optionDelay.customSeconds, 10);
    }
    return sanitizeOptionDelaySeconds(state.optionDelay.preset, 10);
}

function ensureOptionDelayNotice() {
    let notice = document.getElementById('optionDelayNotice');
    if (!notice) {
        notice = document.createElement('div');
        notice.id = 'optionDelayNotice';
        notice.className = 'option-delay-notice hidden';
        notice.setAttribute('aria-live', 'polite');
    }
    if (notice.parentElement !== elements.optionsContainer) {
        elements.optionsContainer.insertBefore(notice, elements.optionsContainer.firstChild);
    }
    return notice;
}

function setOptionDelayNoticeText() {
    const notice = ensureOptionDelayNotice();
    const remainingSeconds = Math.max(1, Math.ceil((state.optionDelay.endsAt - Date.now()) / 1000));
    notice.innerText = `Options appear in ${remainingSeconds}s`;
}

function clearOptionDelay({ hideNotice = true } = {}) {
    if (state.optionDelay.timeoutId) {
        clearTimeout(state.optionDelay.timeoutId);
        state.optionDelay.timeoutId = null;
    }
    if (state.optionDelay.intervalId) {
        clearInterval(state.optionDelay.intervalId);
        state.optionDelay.intervalId = null;
    }
    state.optionDelay.active = false;
    state.optionDelay.endsAt = 0;
    state.optionDelay.releaseToken += 1;
    elements.optionsContainer.classList.remove('option-delay-active');
    const notice = document.getElementById('optionDelayNotice');
    if (notice && hideNotice) {
        notice.classList.add('hidden');
        notice.innerText = '';
    }
}

function pauseStudyTimerForOptionDelay() {
    if (!state.studyTimer.enabled) return;
    state.optionDelay.studyTimerWasPaused = false;
    if (state.studyTimer.intervalId) {
        state.studyTimer.remainingMs = Math.max(0, state.studyTimer.deadlineMs - Date.now());
        clearInterval(state.studyTimer.intervalId);
        state.studyTimer.intervalId = null;
        state.optionDelay.studyTimerWasPaused = !!state.studyTimer.activeKey;
        updateProgress();
        return;
    }
    if (state.studyTimer.activeKey && state.studyTimer.remainingMs > 0) {
        state.optionDelay.studyTimerWasPaused = true;
    }
}

function resumeStudyTimerAfterOptionDelay() {
    if (!state.studyTimer.enabled || isQuizFinished()) return;
    const scope = state.studyTimer.scope === 'folder' || state.studyTimer.scope === 'quiz' ? state.studyTimer.scope : 'question';

    if (scope !== 'question' && state.optionDelay.studyTimerWasPaused && state.studyTimer.activeKey && state.studyTimer.remainingMs > 0) {
        state.studyTimer.deadlineMs = Date.now() + state.studyTimer.remainingMs;
        state.studyTimer.expired = false;
        if (state.studyTimer.intervalId) clearInterval(state.studyTimer.intervalId);
        state.studyTimer.intervalId = setInterval(tickStudyTimer, 250);
        state.optionDelay.studyTimerWasPaused = false;
        tickStudyTimer();
        return;
    }

    state.optionDelay.studyTimerWasPaused = false;
    syncStudyTimerForCurrentQuestion();
}

function revealOptionDelayOptions(token = state.optionDelay.releaseToken) {
    if (token !== state.optionDelay.releaseToken) return;
    clearOptionDelay({ hideNotice: true });
    if (!state.questionAnswered && !isQuizFinished()) {
        setOptionButtonsEnabled(true);
    }
    resumeStudyTimerAfterOptionDelay();
    updateNavigationButtons();
    queueOptionsScrollIndicatorUpdate();
}

function startOptionDelayForCurrentQuestion(question = state.questionQueue[state.currentIndex]) {
    clearOptionDelay({ hideNotice: true });
    if (!isOptionDelayEnabledForQuestion(question) || state.questionAnswered || isQuizFinished()) {
        resumeStudyTimerAfterOptionDelay();
        return;
    }

    const durationSeconds = getOptionDelayDurationSeconds();
    if (!durationSeconds) {
        resumeStudyTimerAfterOptionDelay();
        return;
    }

    pauseStudyTimerForOptionDelay();
    state.optionDelay.active = true;
    state.optionDelay.releaseToken += 1;
    const token = state.optionDelay.releaseToken;
    state.optionDelay.endsAt = Date.now() + durationSeconds * 1000;
    elements.optionsContainer.classList.add('option-delay-active');
    const notice = ensureOptionDelayNotice();
    notice.classList.remove('hidden');
    setOptionDelayNoticeText();
    setOptionButtonsEnabled(false);

    state.optionDelay.intervalId = setInterval(() => {
        if (token !== state.optionDelay.releaseToken) return;
        setOptionDelayNoticeText();
    }, 250);
    state.optionDelay.timeoutId = setTimeout(() => revealOptionDelayOptions(token), durationSeconds * 1000);
}

function serializeOptionDelaySettings() {
    return {
        enabled: !!state.optionDelay.enabled,
        preset: ['3', '5', '10', '15', 'custom'].includes(String(state.optionDelay.preset)) ? String(state.optionDelay.preset) : '10',
        customSeconds: sanitizeOptionDelaySeconds(state.optionDelay.customSeconds, 10)
    };
}

function saveOptionDelaySettings() {
    try {
        localStorage.setItem(CONFIG.optionDelayStorageKey, JSON.stringify(serializeOptionDelaySettings()));
    } catch (err) {
        console.warn('Could not save Option Delay settings:', err);
    }
}

function loadOptionDelaySettings() {
    let saved = null;
    try {
        saved = JSON.parse(localStorage.getItem(CONFIG.optionDelayStorageKey) || 'null');
    } catch (err) {
        saved = null;
    }

    if (saved && typeof saved === 'object') {
        state.optionDelay.enabled = !!saved.enabled;
        state.optionDelay.preset = ['3', '5', '10', '15', 'custom'].includes(String(saved.preset)) ? String(saved.preset) : '10';
        state.optionDelay.customSeconds = sanitizeOptionDelaySeconds(saved.customSeconds, 10);
    }

    syncOptionDelaySettingsUI();
}

function syncOptionDelaySettingsUI() {
    if (elements.optionDelayMode) elements.optionDelayMode.checked = !!state.optionDelay.enabled;
    if (elements.optionDelayPresetSelect) elements.optionDelayPresetSelect.value = state.optionDelay.preset;
    if (elements.optionDelayCustomSeconds) elements.optionDelayCustomSeconds.value = String(state.optionDelay.customSeconds || 10);

    const showDetails = !!state.optionDelay.enabled;
    const showCustom = state.optionDelay.preset === 'custom';
    if (elements.optionDelayDetails) elements.optionDelayDetails.classList.toggle('hidden', !showDetails);
    if (elements.optionDelayCustomRow) elements.optionDelayCustomRow.classList.toggle('hidden', !showDetails || !showCustom);
}

function readOptionDelaySettingsFromUI() {
    state.optionDelay.enabled = !!elements.optionDelayMode?.checked;
    state.optionDelay.preset = ['3', '5', '10', '15', 'custom'].includes(String(elements.optionDelayPresetSelect?.value)) ? String(elements.optionDelayPresetSelect.value) : '10';
    state.optionDelay.customSeconds = sanitizeOptionDelaySeconds(elements.optionDelayCustomSeconds?.value, state.optionDelay.customSeconds || 10);
    syncOptionDelaySettingsUI();
    saveOptionDelaySettings();
}

function restartOptionDelayAfterSettingsChange() {
    clearOptionDelay({ hideNotice: true });
    const currentQuestion = state.questionQueue[state.currentIndex];
    if (!state.questionAnswered && isOptionDelayEnabledForQuestion(currentQuestion)) {
        startOptionDelayForCurrentQuestion(currentQuestion);
    }
}

// ================= STUDY TIMER HELPERS =================
function sanitizeStudyTimerSeconds(value, fallback = 60) {
    const parsed = Math.floor(Number(value));
    if (!Number.isFinite(parsed) || parsed <= 0) return fallback;
    return Math.min(parsed, 24 * 60 * 60);
}

function getStudyTimerDurationSeconds() {
    if (!state.studyTimer.enabled) return 0;
    if (state.studyTimer.preset === 'custom') {
        return sanitizeStudyTimerSeconds(state.studyTimer.customSeconds, 60);
    }
    return sanitizeStudyTimerSeconds(state.studyTimer.preset, 60);
}

function formatStudyTimerDuration(ms) {
    const safeMs = Math.max(0, Number(ms) || 0);
    const totalSeconds = Math.ceil(safeMs / 1000);
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;
    if (hours > 0) {
        return `${hours}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
    }
    return `${minutes}:${String(seconds).padStart(2, '0')}`;
}

function getStudyTimerDisplayText() {
    if (!state.studyTimer.enabled || !state.studyTimer.activeKey || isQuizFinished()) return '';
    return `⏱ ${formatStudyTimerDuration(state.studyTimer.remainingMs)}`;
}

function getStudyTimerSessionBaseKey() {
    const descriptor = state.activeQuizDescriptor || {};
    const descriptorKey = normalizeSheetText(descriptor.id || descriptor.sheetName || descriptor.name || descriptor.folder || 'active');
    return `${state.studyTimer.scope}:${descriptorKey}:${state.studyTimer.sessionToken}`;
}

function getCurrentQuestionTimerKey(question) {
    const q = question || state.questionQueue[state.currentIndex] || {};
    const qKey = normalizeSheetText(q.id || q.sourceQuestionId || `index_${state.currentIndex}`);
    return `${getStudyTimerSessionBaseKey()}:question:${qKey}:${state.currentIndex}`;
}

function stopStudyTimer({ clearDisplay = true } = {}) {
    if (state.studyTimer.intervalId) {
        clearInterval(state.studyTimer.intervalId);
        state.studyTimer.intervalId = null;
    }
    state.studyTimer.activeKey = '';
    state.studyTimer.deadlineMs = 0;
    state.studyTimer.remainingMs = 0;
    state.studyTimer.expired = false;
    if (clearDisplay) updateProgress();
}

function tickStudyTimer() {
    if (!state.studyTimer.enabled || !state.studyTimer.activeKey) return;
    state.studyTimer.remainingMs = Math.max(0, state.studyTimer.deadlineMs - Date.now());
    updateProgress();
    if (state.studyTimer.remainingMs <= 0 && !state.studyTimer.expired) {
        state.studyTimer.expired = true;
        handleStudyTimerExpired();
    }
}

function startStudyTimer(key, durationSeconds) {
    const safeDuration = sanitizeStudyTimerSeconds(durationSeconds, 60);
    if (!key || safeDuration <= 0) return;

    if (state.studyTimer.activeKey === key && state.studyTimer.intervalId) {
        tickStudyTimer();
        return;
    }

    if (state.studyTimer.intervalId) {
        clearInterval(state.studyTimer.intervalId);
    }

    state.studyTimer.activeKey = key;
    state.studyTimer.deadlineMs = Date.now() + safeDuration * 1000;
    state.studyTimer.remainingMs = safeDuration * 1000;
    state.studyTimer.expired = false;
    state.studyTimer.intervalId = setInterval(tickStudyTimer, 250);
    tickStudyTimer();
}

function syncStudyTimerForCurrentQuestion() {
    if (!state.studyTimer.enabled || !state.questions.length || isQuizFinished()) {
        stopStudyTimer({ clearDisplay: false });
        return;
    }

    const durationSeconds = getStudyTimerDurationSeconds();
    if (!durationSeconds) {
        stopStudyTimer({ clearDisplay: false });
        return;
    }

    const currentQuestion = state.questionQueue[state.currentIndex];
    if (!currentQuestion) {
        stopStudyTimer({ clearDisplay: false });
        return;
    }

    const scope = state.studyTimer.scope === 'folder' || state.studyTimer.scope === 'quiz' ? state.studyTimer.scope : 'question';
    const key = scope === 'question' ? getCurrentQuestionTimerKey(currentQuestion) : getStudyTimerSessionBaseKey();
    if (scope !== 'question' && state.studyTimer.activeKey === key && !state.studyTimer.intervalId && state.studyTimer.remainingMs > 0) {
        state.studyTimer.deadlineMs = Date.now() + state.studyTimer.remainingMs;
        state.studyTimer.expired = false;
        state.studyTimer.intervalId = setInterval(tickStudyTimer, 250);
        tickStudyTimer();
        return;
    }
    startStudyTimer(key, durationSeconds);
}

function disableCurrentQuestionInteractionsForTimer() {
    setOptionButtonsEnabled(false);
    setHierarchyInteractionEnabled(false);
    setClassifyInteractionEnabled(false);
    setFlashcardInteractionEnabled(false);
}

function markCurrentTimerQuestionWrong() {
    const q = state.questionQueue[state.currentIndex];
    if (!q || state.questionAnswered || isQuizFinished()) return;

    state.questionAnswered = true;
    disableCurrentQuestionInteractionsForTimer();
    applyQuestionOutcome(q, false, { useSideFeedback: false });
    setFeedback('Time expired!', false);

    if (isSpeedMode()) {
        setTimeout(nextQuestion, CONFIG.speedDelay);
    }
}

function markRemainingProgressQuestionsMissed() {
    if (!isProgressMode()) return;
    for (let index = state.currentIndex; index < state.questionQueue.length; index += 1) {
        const question = state.questionQueue[index];
        if (question) recordProgressModeOutcome(question, false);
    }
}

function finishStudyTimerSession() {
    if (isQuizFinished()) return;
    markRemainingProgressQuestionsMissed();

    if (isRetentionMode()) {
        state.retentionFinished = true;
    } else if (isRetryMode()) {
        state.questionQueue = [];
        state.currentIndex = 0;
    } else if (isMasteryCheckMode()) {
        state.masteryCheckFinished = true;
    } else {
        state.normalFinished = true;
    }

    setFeedback('Time expired!', false);
    showQuestion();
}

function handleStudyTimerExpired() {
    if (!state.studyTimer.enabled || isQuizFinished()) return;
    if (state.studyTimer.scope === 'question') {
        markCurrentTimerQuestionWrong();
    } else {
        finishStudyTimerSession();
    }
}

function serializeStudyTimerSettings() {
    return {
        enabled: !!state.studyTimer.enabled,
        scope: ['folder', 'quiz', 'question'].includes(state.studyTimer.scope) ? state.studyTimer.scope : 'question',
        preset: ['30', '60', '1800', '3600', 'custom'].includes(String(state.studyTimer.preset)) ? String(state.studyTimer.preset) : '60',
        customSeconds: sanitizeStudyTimerSeconds(state.studyTimer.customSeconds, 60)
    };
}

function saveStudyTimerSettings() {
    try {
        localStorage.setItem(CONFIG.studyTimerStorageKey, JSON.stringify(serializeStudyTimerSettings()));
    } catch (err) {
        console.warn('Could not save timer settings:', err);
    }
}

function loadStudyTimerSettings() {
    let saved = null;
    try {
        saved = JSON.parse(localStorage.getItem(CONFIG.studyTimerStorageKey) || 'null');
    } catch (err) {
        saved = null;
    }

    if (saved && typeof saved === 'object') {
        state.studyTimer.enabled = !!saved.enabled;
        state.studyTimer.scope = ['folder', 'quiz', 'question'].includes(saved.scope) ? saved.scope : 'question';
        state.studyTimer.preset = ['30', '60', '1800', '3600', 'custom'].includes(String(saved.preset)) ? String(saved.preset) : '60';
        state.studyTimer.customSeconds = sanitizeStudyTimerSeconds(saved.customSeconds, 60);
    }

    syncStudyTimerSettingsUI();
}

function syncStudyTimerSettingsUI() {
    if (elements.timerMode) elements.timerMode.checked = !!state.studyTimer.enabled;
    if (elements.timerScopeSelect) elements.timerScopeSelect.value = state.studyTimer.scope;
    if (elements.timerPresetSelect) elements.timerPresetSelect.value = state.studyTimer.preset;
    if (elements.timerCustomSeconds) elements.timerCustomSeconds.value = String(state.studyTimer.customSeconds || 60);

    const showDetails = !!state.studyTimer.enabled;
    const showCustom = state.studyTimer.preset === 'custom';
    if (elements.timerDetails) elements.timerDetails.classList.toggle('hidden', !showDetails);
    if (elements.timerCustomRow) elements.timerCustomRow.classList.toggle('hidden', !showDetails || !showCustom);
}

function readStudyTimerSettingsFromUI() {
    state.studyTimer.enabled = !!elements.timerMode?.checked;
    state.studyTimer.scope = ['folder', 'quiz', 'question'].includes(elements.timerScopeSelect?.value) ? elements.timerScopeSelect.value : 'question';
    state.studyTimer.preset = ['30', '60', '1800', '3600', 'custom'].includes(String(elements.timerPresetSelect?.value)) ? String(elements.timerPresetSelect.value) : '60';
    state.studyTimer.customSeconds = sanitizeStudyTimerSeconds(elements.timerCustomSeconds?.value, state.studyTimer.customSeconds || 60);
    syncStudyTimerSettingsUI();
    saveStudyTimerSettings();
}

function restartStudyTimerAfterSettingsChange() {
    state.studyTimer.sessionToken += 1;
    stopStudyTimer({ clearDisplay: false });
    if (!state.optionDelay.active) {
        syncStudyTimerForCurrentQuestion();
    } else {
        pauseStudyTimerForOptionDelay();
    }
    updateProgress();
}

// ================= AUTO-STAR HELPERS =================
function sanitizeAutoStarSeconds(value, fallback = 5) {
    const parsed = Math.floor(Number(value));
    if (!Number.isFinite(parsed) || parsed <= 0) return fallback;
    return Math.min(parsed, 24 * 60 * 60);
}

function getAutoStarThresholdSeconds() {
    if (!state.autoStar.enabled) return 0;
    if (state.autoStar.preset === 'custom') {
        return sanitizeAutoStarSeconds(state.autoStar.customSeconds, 5);
    }
    return sanitizeAutoStarSeconds(state.autoStar.preset, 5);
}

function serializeAutoStarSettings() {
    return {
        enabled: !!state.autoStar.enabled,
        preset: ['5', '10', '30', '60', 'custom'].includes(String(state.autoStar.preset)) ? String(state.autoStar.preset) : '5',
        customSeconds: sanitizeAutoStarSeconds(state.autoStar.customSeconds, 5)
    };
}

function saveAutoStarSettings() {
    try {
        localStorage.setItem(CONFIG.autoStarStorageKey, JSON.stringify(serializeAutoStarSettings()));
    } catch (err) {
        console.warn('Could not save Auto-Star settings:', err);
    }
}

function loadAutoStarSettings() {
    let saved = null;
    try {
        saved = JSON.parse(localStorage.getItem(CONFIG.autoStarStorageKey) || 'null');
    } catch (err) {
        saved = null;
    }

    if (saved && typeof saved === 'object') {
        state.autoStar.enabled = !!saved.enabled;
        state.autoStar.preset = ['5', '10', '30', '60', 'custom'].includes(String(saved.preset)) ? String(saved.preset) : '5';
        state.autoStar.customSeconds = sanitizeAutoStarSeconds(saved.customSeconds, 5);
    }

    syncAutoStarSettingsUI();
}

function syncAutoStarSettingsUI() {
    if (elements.autoStarMode) elements.autoStarMode.checked = !!state.autoStar.enabled;
    if (elements.autoStarPresetSelect) elements.autoStarPresetSelect.value = state.autoStar.preset;
    if (elements.autoStarCustomSeconds) elements.autoStarCustomSeconds.value = String(state.autoStar.customSeconds || 5);

    const showDetails = !!state.autoStar.enabled;
    const showCustom = state.autoStar.preset === 'custom';
    if (elements.autoStarDetails) elements.autoStarDetails.classList.toggle('hidden', !showDetails);
    if (elements.autoStarCustomRow) elements.autoStarCustomRow.classList.toggle('hidden', !showDetails || !showCustom);
}

function readAutoStarSettingsFromUI() {
    state.autoStar.enabled = !!elements.autoStarMode?.checked;
    state.autoStar.preset = ['5', '10', '30', '60', 'custom'].includes(String(elements.autoStarPresetSelect?.value)) ? String(elements.autoStarPresetSelect.value) : '5';
    state.autoStar.customSeconds = sanitizeAutoStarSeconds(elements.autoStarCustomSeconds?.value, state.autoStar.customSeconds || 5);
    syncAutoStarSettingsUI();
    saveAutoStarSettings();
}

function getAutoStarQuestionKey(question) {
    return normalizeSheetText(question?.sourceQuestionId || question?.id || '');
}

function startAutoStarQuestionWindow(question) {
    const key = getAutoStarQuestionKey(question);
    state.autoStar.currentQuestionKey = key;
    state.autoStar.currentAttemptKey = key ? `${key}:${state.currentIndex}:${Date.now()}` : '';
    state.autoStar.questionStartedAt = key ? Date.now() : 0;
}

function markAutoStarredQuestionExcludedInSession(question) {
    if (!isExcludeStarredEnabled()) return;

    const key = getAutoStarQuestionKey(question);
    if (key) state.autoStar.excludedQuestionKeys.add(key);
}

function unmarkAutoStarredQuestionExcludedInSession(question) {
    const key = getAutoStarQuestionKey(question);
    if (key) state.autoStar.excludedQuestionKeys.delete(key);
}

function removeAutoStarredQuestionFromFutureQueue(question) {
    if (!isExcludeStarredEnabled()) return;

    const key = getAutoStarQuestionKey(question);
    if (!key) return;

    state.questionQueue = state.questionQueue.filter((item, index) => {
        if (index === state.currentIndex) return true;
        return getAutoStarQuestionKey(item) !== key;
    });
}

function advancePastAutoStarredExcludedCurrentQuestion() {
    if (!state.questionAnswered || !isExcludeStarredEnabled()) return false;

    const currentQuestion = state.questionQueue[state.currentIndex];
    const key = getAutoStarQuestionKey(currentQuestion);
    if (!key || !state.autoStar.excludedQuestionKeys.has(key)) return false;

    const previousIndex = state.currentIndex;
    state.questionQueue = state.questionQueue.filter(question => getAutoStarQuestionKey(question) !== key);
    state.questions = state.questions.filter(question => getAutoStarQuestionKey(question) !== key);
    state.masteryCheckSegmentQuestions = state.masteryCheckSegmentQuestions.filter(question => getAutoStarQuestionKey(question) !== key);
    state.masteryCheckResumeQueue = state.masteryCheckResumeQueue.filter(question => getAutoStarQuestionKey(question) !== key);
    if (currentQuestion?.id) {
        state.masteryCheckSegmentIds.delete(currentQuestion.id);
        state.masteryCheckCheckpointSolvedIds.delete(currentQuestion.id);
    }
    state.autoStar.excludedQuestionKeys.delete(key);
    resetPendingStudyAdvanceFlags();

    if (!state.questionQueue.length) {
        state.currentIndex = 0;
        state.emptyQuizMessage = 'All questions in this deck are currently starred and excluded.';
        if (isRetentionMode()) {
            state.retentionFinished = true;
        } else if (isMasteryCheckMode()) {
            state.masteryCheckFinished = true;
        } else {
            state.normalFinished = true;
        }
    } else {
        state.emptyQuizMessage = '';
        state.currentIndex = Math.min(previousIndex, state.questionQueue.length - 1);
    }

    showQuestion();
    showPendingLearningResourceIfAny();
    return true;
}

async function persistAutoStarForQuestion(question, elapsedMs) {
    const key = getAutoStarQuestionKey(question);
    if (!key || state.autoStar.pendingQuestionKeys.has(key)) return;
    if (!canPersistQuestionStarState(question) || question.isStarred) return;

    state.autoStar.pendingQuestionKeys.add(key);
    markAutoStarredQuestionExcludedInSession(question);
    syncQuestionStarButton();

    try {
        await persistQuestionStarState(question, true);
        applyQuestionStarStateAcrossDeck(question.sourceQuestionId, true);
        removeAutoStarredQuestionFromFutureQueue(question);

        const currentQuestion = state.questionQueue[state.currentIndex];
        if (getAutoStarQuestionKey(currentQuestion) === key && state.questionAnswered) {
            setFeedback('Auto-starred ★', true);
        }
    } catch (error) {
        unmarkAutoStarredQuestionExcludedInSession(question);
        console.error('Could not Auto-Star question:', error);
    } finally {
        state.autoStar.pendingQuestionKeys.delete(key);
        syncQuestionStarButton();
        updateProgress();
    }
}

function maybeAutoStarQuestionFromOutcome(question, isCorrect) {
    const key = getAutoStarQuestionKey(question);
    if (!key) return;

    if (!isCorrect) {
        return;
    }

    const thresholdSeconds = getAutoStarThresholdSeconds();
    if (!state.autoStar.enabled || !thresholdSeconds) return;
    if (!canPersistQuestionStarState(question) || question.isStarred) return;
    if (state.autoStar.currentQuestionKey !== key || !state.autoStar.questionStartedAt) return;

    const elapsedMs = Math.max(0, Date.now() - state.autoStar.questionStartedAt);
    if (elapsedMs <= thresholdSeconds * 1000) {
        persistAutoStarForQuestion(question, elapsedMs);
    }
}


function serializeUnstarOnWrongSettings() {
    return {
        enabled: !!state.unstarOnWrong.enabled
    };
}

function saveUnstarOnWrongSettings() {
    try {
        localStorage.setItem(CONFIG.unstarOnWrongStorageKey, JSON.stringify(serializeUnstarOnWrongSettings()));
    } catch (err) {
        console.warn('Could not save Unstar on Wrong settings:', err);
    }
}

function loadUnstarOnWrongSettings() {
    let saved = null;
    try {
        saved = JSON.parse(localStorage.getItem(CONFIG.unstarOnWrongStorageKey) || 'null');
    } catch (err) {
        saved = null;
    }

    if (saved && typeof saved === 'object') {
        state.unstarOnWrong.enabled = !!saved.enabled;
    }

    syncUnstarOnWrongSettingsUI();
}

function syncUnstarOnWrongSettingsUI() {
    if (elements.unstarOnWrongMode) elements.unstarOnWrongMode.checked = !!state.unstarOnWrong.enabled;
}

function readUnstarOnWrongSettingsFromUI() {
    state.unstarOnWrong.enabled = !!elements.unstarOnWrongMode?.checked;
    syncUnstarOnWrongSettingsUI();
    saveUnstarOnWrongSettings();
}

async function persistUnstarOnWrongForQuestion(question) {
    const key = getAutoStarQuestionKey(question);
    if (!key || state.unstarOnWrong.pendingQuestionKeys.has(key)) return;
    if (!state.unstarOnWrong.enabled || isExcludeStarredEnabled()) return;
    if (!canPersistQuestionStarState(question) || !question.isStarred) return;

    state.unstarOnWrong.pendingQuestionKeys.add(key);

    try {
        await persistQuestionStarState(question, false);
        applyQuestionStarStateAcrossDeck(question.sourceQuestionId, false);

        const currentQuestion = state.questionQueue[state.currentIndex];
        if (getAutoStarQuestionKey(currentQuestion) === key && state.questionAnswered) {
            setFeedback('Incorrect — unstarred ★', false);
        }
    } catch (error) {
        console.error('Could not unstar question after wrong answer:', error);
    } finally {
        state.unstarOnWrong.pendingQuestionKeys.delete(key);
        syncQuestionStarButton();
        updateProgress();
    }
}

function maybeUnstarQuestionFromOutcome(question, isCorrect) {
    if (isCorrect) return;
    persistUnstarOnWrongForQuestion(question);
}

