function canPersistQuestionStarState(question = state.questionQueue[state.currentIndex]) {
    return !!(state.auth.client && state.auth.user?.id && question?.sourceQuestionId);
}

function isNormalMode() {
    return !isRetentionMode() && !isRetryMode() && !isMasteryCheckMode();
}

function isStructuredMode() {
    return isRetentionMode() || isRetryMode() || isMasteryCheckMode();
}

function getProgressQuestionKey(question, fallbackIndex = state.currentIndex) {
    return normalizeSheetText(question?.id || question?.sourceQuestionId || ('progress-question-' + fallbackIndex));
}

function recordProgressModeOutcome(question, isCorrect) {
    if (!isProgressMode() || !question) return;
    const key = getProgressQuestionKey(question);
    if (!key) return;

    state.progressRoundOutcomeMap.set(key, {
        question,
        isCorrect: !!isCorrect
    });

    if (isCorrect) {
        state.progressWrongQuestionMap.delete(key);
    } else {
        state.progressWrongQuestionMap.set(key, question);
    }
}

function getProgressRoundQuestionsByOutcome(isCorrect) {
    return Array.from(state.progressRoundOutcomeMap.values())
        .filter(result => !!result && result.isCorrect === !!isCorrect && result.question)
        .map(result => result.question);
}

function getUniqueStarEligibleQuestions(questionGroups = []) {
    const uniqueQuestions = new Map();
    questionGroups.flat().forEach(question => {
        const sourceQuestionId = normalizeSheetText(question?.sourceQuestionId);
        if (!sourceQuestionId || uniqueQuestions.has(sourceQuestionId)) return;
        uniqueQuestions.set(sourceQuestionId, question);
    });
    return Array.from(uniqueQuestions.values());
}

function getActiveProgressQuizQuestionsForStarReset() {
    return getUniqueStarEligibleQuestions([
        Array.isArray(state.sourceQuestions) ? state.sourceQuestions : [],
        Array.isArray(state.questions) ? state.questions : [],
        Array.isArray(state.questionQueue) ? state.questionQueue : []
    ]);
}

async function persistProgressResultStarState(questions = [], isStarred = true) {
    const targets = getUniqueStarEligibleQuestions([questions]);
    if (!state.auth.client || !state.auth.user?.id) {
        throw new Error('Sign in to change starred questions.');
    }
    if (!targets.length) return 0;

    const rows = targets.map(question => ({
        user_id: state.auth.user.id,
        question_id: normalizeSheetText(question.sourceQuestionId),
        is_starred: !!isStarred
    }));

    const { error } = await state.auth.client
        .from('user_question_state')
        .upsert(rows, { onConflict: 'user_id,question_id' });
    if (error) throw error;

    targets.forEach(question => {
        applyQuestionStarStateAcrossDeck(question.sourceQuestionId, isStarred);
    });
    syncQuestionStarButton();
    updateProgress();
    return targets.length;
}

function renderProgressResultStarActions(summary) {
    if (!summary) return;

    const correctQuestions = getProgressRoundQuestionsByOutcome(true);
    const incorrectQuestions = getProgressRoundQuestionsByOutcome(false);
    const resetQuestions = getActiveProgressQuizQuestionsForStarReset();
    const canPersistStars = !!(state.auth.client && state.auth.user?.id);

    const actions = document.createElement('div');
    actions.className = 'progress-result-star-actions';

    const heading = document.createElement('div');
    heading.className = 'progress-result-star-heading';
    heading.innerText = 'Questions from this attempt';
    actions.appendChild(heading);

    const buttonRow = document.createElement('div');
    buttonRow.className = 'progress-result-star-button-row';

    const createActionButton = (label, count, className, handler) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = `auth-action-btn progress-result-star-btn ${className}`;
        button.innerText = `${label} (${count})`;
        button.disabled = !canPersistStars || count === 0 || state.progressStarActionInFlight;
        button.addEventListener('click', handler);
        buttonRow.appendChild(button);
        return button;
    };

    const status = document.createElement('div');
    status.className = 'progress-result-star-status';
    status.setAttribute('role', 'status');
    status.setAttribute('aria-live', 'polite');
    status.innerText = canPersistStars ? '' : 'Sign in to change starred questions.';

    const runAction = async (button, action) => {
        if (state.progressStarActionInFlight) return;
        state.progressStarActionInFlight = true;
        buttonRow.querySelectorAll('button').forEach(item => { item.disabled = true; });
        const retryButton = summary.querySelector('.progress-mode-retry-btn');
        if (retryButton) retryButton.disabled = true;
        status.classList.remove('error');
        status.innerText = 'Saving starred questions...';
        try {
            const result = await action();
            status.innerText = result.message;
            button.innerText = result.buttonLabel || button.innerText;
        } catch (error) {
            console.error('Could not update Progress result stars:', error);
            status.classList.add('error');
            status.innerText = error?.message || 'Could not update starred questions.';
        } finally {
            state.progressStarActionInFlight = false;
            correctButton.disabled = !canPersistStars || correctQuestions.length === 0;
            incorrectButton.disabled = !canPersistStars || incorrectQuestions.length === 0;
            resetButton.disabled = !canPersistStars || !resetQuestions.some(question => !!question.isStarred);
            if (retryButton) retryButton.disabled = false;
        }
    };

    const correctButton = createActionButton('★ Star all correct', correctQuestions.length, 'star-correct', event => {
        runAction(event.currentTarget, async () => {
            const count = await persistProgressResultStarState(correctQuestions, true);
            return {
                message: `${count} correct ${count === 1 ? 'question' : 'questions'} starred.`,
                buttonLabel: `✓ Starred correct (${correctQuestions.length})`
            };
        });
    });

    const incorrectButton = createActionButton('★ Star all incorrect', incorrectQuestions.length, 'star-incorrect', event => {
        runAction(event.currentTarget, async () => {
            const count = await persistProgressResultStarState(incorrectQuestions, true);
            return {
                message: `${count} incorrect ${count === 1 ? 'question' : 'questions'} starred.`,
                buttonLabel: `✓ Starred incorrect (${incorrectQuestions.length})`
            };
        });
    });

    const resetButton = createActionButton('☆ Reset all starred', 0, 'reset-starred', event => {
        event.currentTarget.innerText = '☆ Reset all starred';
        runAction(event.currentTarget, async () => {
            const count = await persistProgressResultStarState(resetQuestions, false);
            correctButton.innerText = `★ Star all correct (${correctQuestions.length})`;
            incorrectButton.innerText = `★ Star all incorrect (${incorrectQuestions.length})`;
            return {
                message: `Starred questions reset for this quiz.`,
                buttonLabel: '✓ Starred reset'
            };
        });
    });
    resetButton.innerText = '☆ Reset all starred';
    resetButton.disabled = !canPersistStars || !resetQuestions.some(question => !!question.isStarred);

    actions.appendChild(buttonRow);
    actions.appendChild(status);
    summary.appendChild(actions);
}

function getProgressMissedQuestions() {
    return Array.from(state.progressWrongQuestionMap.values()).filter(Boolean);
}

function getProgressScorePercent() {
    const total = state.questions.length;
    if (!total) return 0;
    const missedCount = getProgressMissedQuestions().length;
    const correctCount = Math.max(0, total - missedCount);
    return Math.round((correctCount / total) * 100);
}

function startProgressModeRetry() {
    const missedQuestions = getProgressMissedQuestions();
    if (!missedQuestions.length) return;

    const retryQuestions = isTetherBuildUpEnabled()
        ? expandQuestionsWithTetherBuildUp(missedQuestions, state.questions)
        : missedQuestions;

    state.progressRetryActive = true;
    state.progressRoundOutcomeMap = new Map();
    state.progressStarActionInFlight = false;
    state.questionQueue = buildStudyQuestionQueue(retryQuestions, { shuffle: false });
    state.currentIndex = 0;
    state.normalFinished = false;
    state.questionAnswered = false;
    state.displayedQuestion = null;
    state.multipleAnswerSelection = new Set();
    state.flashcardFlipped = false;
    clearProgressModeFinishUI();
    clearFeedback();
    clearExplanations();
    clearPendingLearningResource();
    showQuestion();
}

function canUseLearningResources() {
    if (isAnswerFeedbackHidden()) return false;
    if (!isLearningResourcesMode()) return false;
    if (isMasteryCheckMode()) return true;
    return !isSpeedMode() && (isRetentionMode() || isRetryMode() || isProgressMode());
}

function deckContainsStudyQuestionType(targetType = '') {
    const normalizedTarget = normalizeSheetText(targetType).toLowerCase();
    if (!normalizedTarget) return false;

    const questionLists = [
        state.questions,
        state.sourceQuestions,
        state.questionQueue
    ];

    return questionLists.some(list => Array.isArray(list) && list.some(q => {
        const normalizedType = normalizeSheetText(q?.type || q?.question_type).toLowerCase();
        return normalizedType === normalizedTarget;
    }));
}

function hasFlashcardsInDeck() {
    return deckContainsStudyQuestionType('flashcard') || state.currentQuestionType === 'flashcard';
}

function hasClassifyInDeck() {
    const activeQuizType = normalizeSheetText(state.activeQuizDescriptor?.quizType || '').toLowerCase();
    return deckContainsStudyQuestionType('classify') || state.currentQuestionType === 'classify' || activeQuizType === 'classify';
}

function updateLearningResourcesAvailability() {
    const learningResourcesCheckbox = document.getElementById('learningResourcesMode');
    const learningResourcesSetting = document.getElementById('learningResourcesModeSetting');
    const learningResourcesHelp = document.getElementById('learningResourcesModeHelp');
    const feedbackHidden = isAnswerFeedbackHidden();
    const learningResourcesAllowed = isRetentionMode() || isRetryMode() || isMasteryCheckMode() || isProgressMode();
    const learningResourcesDisabledForCompatibility = feedbackHidden || !learningResourcesAllowed || (isSpeedMode() && !isMasteryCheckMode());

    if (learningResourcesCheckbox) {
        learningResourcesCheckbox.disabled = learningResourcesDisabledForCompatibility;
    }

    if (learningResourcesSetting) {
        learningResourcesSetting.classList.toggle('disabled-setting', learningResourcesDisabledForCompatibility);
    }

    if (learningResourcesHelp) {
        learningResourcesHelp.innerText = feedbackHidden
            ? 'Paused while Hide Feedback is on because wrong-answer resources would reveal missed questions.'
            : 'Shows study support after a wrong answer when available.';
    }

    if (feedbackHidden || !learningResourcesAllowed) {
        if (learningResourcesCheckbox) learningResourcesCheckbox.checked = false;
        clearPendingLearningResource();
    }

    if (isSpeedMode() && !isMasteryCheckMode() && learningResourcesCheckbox?.checked) {
        learningResourcesCheckbox.checked = false;
        clearPendingLearningResource();
    }
}

function updateStarredQuestionAvailability() {
    const excludeSettingCard = document.getElementById('excludeStarredQuestionsSetting');
    const excludeSettingHelp = document.getElementById('excludeStarredQuestionsHelp');
    const onlySettingCard = document.getElementById('onlyStarredQuestionsSetting');
    const onlySettingHelp = document.getElementById('onlyStarredQuestionsHelp');
    const canUseStarred = !!(state.auth.client && state.auth.user?.id);
    const buildUpActive = isAllowBuildUpEnabled() || isTetherBuildUpEnabled();
    const starredDisabled = !canUseStarred || buildUpActive;

    if (elements.excludeStarredQuestions) {
        elements.excludeStarredQuestions.disabled = starredDisabled;
        if (starredDisabled) {
            elements.excludeStarredQuestions.checked = false;
        }
    }

    if (elements.onlyStarredQuestions) {
        elements.onlyStarredQuestions.disabled = starredDisabled;
        if (starredDisabled) {
            elements.onlyStarredQuestions.checked = false;
        }
    }

    if (excludeSettingCard) {
        excludeSettingCard.classList.toggle('disabled-setting', starredDisabled);
    }

    if (onlySettingCard) {
        onlySettingCard.classList.toggle('disabled-setting', starredDisabled);
    }

    if (excludeSettingHelp && buildUpActive) {
        excludeSettingHelp.innerText = 'Unavailable while Build Up is on because starred filters can split a Build Up string.';
    } else if (excludeSettingHelp && !canUseStarred) {
        excludeSettingHelp.innerText = 'Sign in to use starred-question memory.';
    } else if (excludeSettingHelp) {
        excludeSettingHelp.innerText = 'Hides starred questions from the active study deck without removing the saved stars.';
    }

    if (onlySettingHelp && buildUpActive) {
        onlySettingHelp.innerText = 'Unavailable while Build Up is on because starred filters can split a Build Up string.';
    } else if (onlySettingHelp && !canUseStarred) {
        onlySettingHelp.innerText = 'Sign in to use starred-question memory.';
    } else if (onlySettingHelp) {
        onlySettingHelp.innerText = 'Shows only starred questions in the active study deck without removing saved stars.';
    }
}

function updateAutoStarAvailability() {
    const card = document.getElementById('autoStarModeSetting');
    const help = document.getElementById('autoStarModeHelp');
    const canUseAutoStar = !!(state.auth.client && state.auth.user?.id);

    if (elements.autoStarMode) {
        elements.autoStarMode.disabled = !canUseAutoStar;
        if (!canUseAutoStar && elements.autoStarMode.checked) {
            elements.autoStarMode.checked = false;
            state.autoStar.enabled = false;
            saveAutoStarSettings();
        }
    }

    if (card) {
        card.classList.toggle('disabled-setting', !canUseAutoStar);
    }

    if (help && !canUseAutoStar) {
        help.innerText = 'Sign in to use Auto-Star. It saves stars to your Supabase question memory.';
    } else if (help) {
        help.innerText = 'Automatically stars signed-in Supabase questions answered correctly within the selected time. Runs in the background and can be used with Timer Mode.';
    }

    syncAutoStarSettingsUI();
}


function updateUnstarOnWrongAvailability() {
    const card = document.getElementById('unstarOnWrongSetting');
    const help = document.getElementById('unstarOnWrongHelp');
    const canUseUnstar = !!(state.auth.client && state.auth.user?.id);
    const pausedByExclude = isExcludeStarredEnabled();

    if (elements.unstarOnWrongMode) {
        elements.unstarOnWrongMode.disabled = !canUseUnstar || pausedByExclude;
        if (!canUseUnstar && elements.unstarOnWrongMode.checked) {
            elements.unstarOnWrongMode.checked = false;
            state.unstarOnWrong.enabled = false;
            saveUnstarOnWrongSettings();
        }
    }

    if (card) {
        card.classList.toggle('disabled-setting', !canUseUnstar || pausedByExclude);
    }

    if (help && !canUseUnstar) {
        help.innerText = 'Sign in to use Unstar on Wrong. It saves changes to your Supabase question memory.';
    } else if (help && pausedByExclude) {
        help.innerText = 'Turn off Exclude Starred to review starred questions and let wrong answers unstar them.';
    } else if (help) {
        help.innerText = 'When enabled, a starred question is unstarred if you answer it wrong. This can be used with or without Auto-Star.';
    }

    syncUnstarOnWrongSettingsUI();
}

function updateShuffleQuestionsAvailability() {
    const shuffleQuestionsCheckbox = document.getElementById('shuffleQuestions');
    const shuffleQuestionsSetting = document.getElementById('shuffleQuestionsSetting');
    const challengeLocked = !!getQuizChallengeDefinition(state.activeQuizChallenge?.challengeKey || '')?.requiresBuildUp;

    if (challengeLocked && shuffleQuestionsCheckbox) {
        shuffleQuestionsCheckbox.checked = true;
    }

    if (shuffleQuestionsCheckbox) {
        shuffleQuestionsCheckbox.disabled = challengeLocked;
    }

    if (shuffleQuestionsSetting) {
        shuffleQuestionsSetting.classList.toggle('disabled-setting', challengeLocked);
        shuffleQuestionsSetting.classList.toggle('challenge-locked-setting', challengeLocked);
    }
}

document.addEventListener('change', event => {
    if (event.target?.id === 'shuffleAnswers' && !event.target.checked && state.quizSpacedAttempt) {
        state.quizSpacedAttempt.shuffleDisqualified = true;
    }
});

function updateShuffleAnswersAvailability() {
    const shuffleAnswersCheckbox = document.getElementById('shuffleAnswers');
    const shuffleAnswersSetting = document.getElementById('shuffleAnswersSetting');
    const supportsAnswerShuffle = state.questions.some(q =>
        q.type === 'multiple choice' || q.type === 'diagrams' || q.type === 'hierarchy' || q.type === 'classify'
    );
    const challengeLocked = isActiveQuizChallenge();

    if (challengeLocked) {
        shuffleAnswersCheckbox.checked = true;
    }

    shuffleAnswersCheckbox.disabled = challengeLocked || !supportsAnswerShuffle;

    if (shuffleAnswersSetting) {
        shuffleAnswersSetting.classList.toggle('disabled-setting', challengeLocked || !supportsAnswerShuffle);
        shuffleAnswersSetting.classList.toggle('challenge-locked-setting', challengeLocked);
    }

    if (!supportsAnswerShuffle && !challengeLocked) {
        shuffleAnswersCheckbox.checked = false;
    }
}

function updateGlobalShuffleAnswersAvailability() {
    const globalShuffleAnswersCheckbox = elements.globalShuffleAnswers;
    const globalShuffleAnswersSetting = document.getElementById('globalShuffleAnswersSetting');
    const supportsGlobalAnswerShuffle = state.questions.some(isGlobalShuffleAnswersSupportedQuestion);

    if (globalShuffleAnswersCheckbox) {
        globalShuffleAnswersCheckbox.disabled = !supportsGlobalAnswerShuffle;
    }

    if (globalShuffleAnswersSetting) {
        globalShuffleAnswersSetting.classList.toggle('disabled-setting', !supportsGlobalAnswerShuffle);
    }

    if (!supportsGlobalAnswerShuffle && globalShuffleAnswersCheckbox) {
        globalShuffleAnswersCheckbox.checked = false;
    }
}

function updateAllowBuildUpAvailability() {
    const allowBuildUpCheckbox = elements.allowBuildUp;
    const allowBuildUpSetting = document.getElementById('allowBuildUpSetting');
    const allowBuildUpHelp = document.getElementById('allowBuildUpHelp');
    const hasBuildUpStrings = state.questions.some(isBuildUpSupportedQuestion);
    const activeChallenge = getQuizChallengeDefinition(state.activeQuizChallenge?.challengeKey || '');
    const challengeLocked = !!activeChallenge?.requiresBuildUp;

    if (allowBuildUpCheckbox) {
        if (challengeLocked) {
            allowBuildUpCheckbox.checked = true;
        }
        allowBuildUpCheckbox.disabled = challengeLocked || !hasBuildUpStrings;
        if (!hasBuildUpStrings && !challengeLocked) {
            allowBuildUpCheckbox.checked = false;
        }
    }

    if (allowBuildUpSetting) {
        allowBuildUpSetting.classList.toggle('disabled-setting', challengeLocked || !hasBuildUpStrings);
        allowBuildUpSetting.classList.toggle('challenge-locked-setting', challengeLocked);
    }

    if (allowBuildUpHelp) {
        allowBuildUpHelp.innerText = challengeLocked
            ? 'Locked on for this Build Up challenge.'
            : (hasBuildUpStrings
                ? 'Keeps multiple-choice, diagram, or flashcard items with the same Build Up string together in study order, even when Shuffle Questions is on.'
                : 'Available when multiple-choice, diagram, or flashcard items include Build Up string values from import or editor tools.');
    }
}

function updateTetherBuildUpAvailability() {
    const tetherCheckbox = elements.tetherBuildUp;
    const tetherSetting = document.getElementById('tetherBuildUpSetting');
    const tetherHelp = document.getElementById('tetherBuildUpHelp');
    const allowBuildUpActive = isAllowBuildUpEnabled();
    const supportedModeActive = isTetherBuildUpSupportedModeActive();
    const hasBuildUpStrings = state.questions.some(isBuildUpSupportedQuestion);
    const canUseTether = hasBuildUpStrings && allowBuildUpActive && supportedModeActive;

    if (tetherCheckbox) {
        tetherCheckbox.disabled = !canUseTether;
        if (!canUseTether) {
            tetherCheckbox.checked = false;
        }
    }

    if (tetherSetting) {
        tetherSetting.classList.toggle('disabled-setting', !canUseTether);
    }

    if (tetherHelp) {
        if (!hasBuildUpStrings) {
            tetherHelp.innerText = 'Available when multiple-choice, diagram, or flashcard items include Build Up string values from import or editor tools.';
        } else if (!allowBuildUpActive) {
            tetherHelp.innerText = 'Turn on Allow Build Up first.';
        } else if (!supportedModeActive) {
            tetherHelp.innerText = 'Available with Retention, Progress, Mastery, or Mastery Check mode.';
        } else {
            tetherHelp.innerText = 'Keeps full Build Up strings together when compatible study modes repeat, review, or jump through questions.';
        }
    }
}

function updateFlashcardFrontSettingVisibility() {
    if (!elements.flashcardFrontSetting) return;
    elements.flashcardFrontSetting.classList.toggle('hidden', !hasFlashcardsInDeck());
}

function updateFlashcardFrontButtonsUI() {
    if (!elements.termFrontBtn || !elements.definitionFrontBtn) return;

    elements.termFrontBtn.classList.toggle('active', state.flashcardFrontMode === 'term');
    elements.definitionFrontBtn.classList.toggle('active', state.flashcardFrontMode === 'definition');
}

function updateClassifyDraggableSettingVisibility() {
    if (!elements.classifyDraggableSetting) return;
    elements.classifyDraggableSetting.classList.toggle('hidden', !hasClassifyInDeck());
}

function updateClassifyDraggableButtonsUI() {
    if (!elements.classifyItemsDraggableBtn || !elements.classifyCategoriesDraggableBtn) return;
    const mode = state.classifyDraggableMode === 'categories' ? 'categories' : 'items';
    elements.classifyItemsDraggableBtn.classList.toggle('active', mode === 'items');
    elements.classifyCategoriesDraggableBtn.classList.toggle('active', mode === 'categories');
    elements.classifyItemsDraggableBtn.setAttribute('aria-pressed', mode === 'items' ? 'true' : 'false');
    elements.classifyCategoriesDraggableBtn.setAttribute('aria-pressed', mode === 'categories' ? 'true' : 'false');
}

function setSettingDisabled(settingId, checkboxId, disabled) {
    const card = document.getElementById(settingId);
    const checkbox = document.getElementById(checkboxId);

    if (checkbox) {
        checkbox.disabled = disabled;
    }

    if (card) {
        card.classList.toggle('disabled-setting', disabled);
    }
}

function updateExclusiveModeAvailability() {
    const retentionActive = isRetentionMode();
    const masteryActive = isRetryMode();
    const masteryCheckActive = isMasteryCheckMode();
    const progressActive = isProgressMode();
    const challengeLocked = isActiveQuizChallenge();

    setSettingDisabled('retentionModeSetting', 'retentionMode', challengeLocked || masteryActive || masteryCheckActive || progressActive);
    setSettingDisabled('masteryModeSetting', 'masteryMode', challengeLocked || retentionActive || masteryCheckActive || progressActive);
    setSettingDisabled('masteryCheckModeSetting', 'masteryCheckMode', challengeLocked || retentionActive || masteryActive || progressActive);
    setSettingDisabled('progressModeSetting', 'progressMode', challengeLocked || retentionActive || masteryActive || masteryCheckActive);

    ['retentionModeSetting', 'masteryModeSetting', 'masteryCheckModeSetting', 'progressModeSetting'].forEach(settingId => {
        const card = document.getElementById(settingId);
        if (card) card.classList.toggle('challenge-locked-setting', challengeLocked);
    });

    syncMasteryCheckThresholdControls();
}

function updateRapidLearningResourcesCompatibility() {
    const rapidSetting = document.getElementById('rapidModeSetting');
    const rapidCheckbox = document.getElementById('rapidMode');
    const learningResourcesCheckbox = document.getElementById('learningResourcesMode');

    const allowRapidAndLearningTogether = isMasteryCheckMode();
    const rapidDisabled = !allowRapidAndLearningTogether && !!learningResourcesCheckbox?.checked;

    if (rapidCheckbox) {
        rapidCheckbox.disabled = rapidDisabled;
    }

    if (rapidSetting) {
        rapidSetting.classList.toggle('disabled-setting', rapidDisabled);
    }
}

function setNavButtonEnabled(button, enabled) {
    if (!button) return;
    button.disabled = !enabled;
    button.setAttribute('aria-disabled', enabled ? 'false' : 'true');
}

function updateNavigationButtons() {
    const hasQuestions = state.questions.length > 0;
    const setNextLabel = () => {
        if (!elements.nextBtn) return;
        const shouldSubmit = isCurrentMultipleAnswerSubmitPending();
        const useCompactIcons = isNarrowIPhoneViewport();
        elements.nextBtn.innerText = shouldSubmit ? 'Submit' : (useCompactIcons ? '→' : 'Next');
        elements.nextBtn.setAttribute('aria-label', shouldSubmit ? 'Submit answer' : 'Next');
        elements.nextBtn.setAttribute('title', shouldSubmit ? 'Submit answer' : 'Next');
    };

    setNextLabel();

    if (!hasQuestions || state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen || isQuizFinished()) {
        setNavButtonEnabled(elements.prevBtn, false);
        setNavButtonEnabled(elements.nextBtn, false);
        return;
    }

    if (isCurrentMultipleAnswerSubmitPending()) {
        const lockPreviousForStructuredMode = isStructuredMode() || isProgressMode();
        setNavButtonEnabled(elements.prevBtn, !lockPreviousForStructuredMode);
        setNavButtonEnabled(elements.nextBtn, (state.multipleAnswerSelection?.size || 0) > 0);
        return;
    }

    if (isStructuredMode()) {
        setNavButtonEnabled(elements.prevBtn, false);
        setNavButtonEnabled(elements.nextBtn, state.questionAnswered);
        return;
    }

    if (isProgressMode()) {
        setNavButtonEnabled(elements.prevBtn, false);
        setNavButtonEnabled(elements.nextBtn, state.questionAnswered);
        return;
    }

    setNavButtonEnabled(elements.prevBtn, true);
    setNavButtonEnabled(elements.nextBtn, true);
}

function updateSettingsAvailability() {
    updateExclusiveModeAvailability();
    updateLearningResourcesAvailability();
    updateRapidLearningResourcesCompatibility();
    updateAutoStarAvailability();
    updateUnstarOnWrongAvailability();
    syncHideAnswerFeedbackSettingsUI();
    syncGlobalShuffleAnswersSettingsUI();
    syncOptionDelaySettingsUI();
    updateShuffleQuestionsAvailability();
    updateShuffleAnswersAvailability();
    updateGlobalShuffleAnswersAvailability();
    updateAllowBuildUpAvailability();
    updateTetherBuildUpAvailability();
    updateStarredQuestionAvailability();
    updateFlashcardFrontSettingVisibility();
    updateFlashcardFrontButtonsUI();
    updateClassifyDraggableSettingVisibility();
    updateClassifyDraggableButtonsUI();
    updateNavigationButtons();
    syncQuestionStarButton();
}

function syncBodyScrollLock() {
    document.body.style.overflow = (state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen || state.completionChallengePrompt.open || state.auth?.quizStudioOpen) ? 'hidden' : '';
}

function isNarrowIPhoneViewport() {
    return window.matchMedia('(max-width: 440px), (max-height: 440px) and (orientation: landscape)').matches;
}

function isIPadLikeDevice() {
    const ua = navigator.userAgent || '';
    const platform = navigator.platform || '';
    return /iPad/i.test(ua) || (platform === 'MacIntel' && navigator.maxTouchPoints > 1);
}

function isIPadPortraitFlashcardViewport() {
    return isIPadLikeDevice() && window.matchMedia('(orientation: portrait) and (min-width: 700px)').matches;
}

function isIPadLandscapeFlashcardViewport() {
    return isIPadLikeDevice() && window.matchMedia('(orientation: landscape) and (min-width: 700px)').matches;
}

function isIPadPortraitMultipleChoiceImageTopViewport() {
    return isIPadLikeDevice() && window.matchMedia('(orientation: portrait) and (min-width: 700px)').matches;
}

function isPhoneLandscapeMultipleChoiceImageRightViewport() {
    const landscapePhone = window.matchMedia('(orientation: landscape) and (max-height: 520px)').matches;
    const coarseTouch = window.matchMedia('(hover: none) and (pointer: coarse), (any-pointer: coarse)').matches;
    const phoneSized = isNarrowIPhoneViewport() || Math.min(window.innerWidth || 0, window.innerHeight || 0) <= 520;
    return landscapePhone && coarseTouch && phoneSized && !isIPadLikeDevice();
}

function isMultipleChoiceSplitLayoutViewport() {
    return window.matchMedia('(hover: hover) and (pointer: fine) and (min-width: 700px), (orientation: landscape)').matches;
}

function getMultipleChoiceSplitQuestionColumn() {
    let wrapper = document.getElementById('mcSplitQuestionColumn');
    if (!wrapper) {
        wrapper = document.createElement('div');
        wrapper.id = 'mcSplitQuestionColumn';
        wrapper.className = 'mc-split-question-column';
    }
    return wrapper;
}

function syncMultipleChoiceSplitLayoutMount() {
    const isMultipleChoiceStudyQuestion = state.currentQuestionType === 'multiple choice' || state.currentQuestionType === 'diagrams' || state.currentQuestionType === 'typed answer';
    const isMultipleChoiceOrDiagramStudyQuestion = state.currentQuestionType === 'multiple choice' || state.currentQuestionType === 'diagrams';
    const shouldUseIpadPortraitImageTopMount = isMultipleChoiceOrDiagramStudyQuestion && !!state.currentQuestionHasImage && isIPadPortraitMultipleChoiceImageTopViewport();
    const shouldUsePhoneImageRightMount = isMultipleChoiceStudyQuestion && !!state.currentQuestionHasImage && !shouldUseIpadPortraitImageTopMount && isPhoneLandscapeMultipleChoiceImageRightViewport();
    const shouldUseSplitMount = isMultipleChoiceStudyQuestion && !shouldUseIpadPortraitImageTopMount && !shouldUsePhoneImageRightMount && isMultipleChoiceSplitLayoutViewport();
    const quizArea = elements.quizArea;
    const questionContainer = elements.questionContainer;
    const questionText = elements.questionTextEl;
    const imageContainer = elements.imageContainer;
    const optionsContainer = elements.optionsContainer;

    if (!quizArea || !questionContainer || !questionText || !imageContainer || !optionsContainer) return;

    if (shouldUseIpadPortraitImageTopMount) {
        const wrapper = document.getElementById('mcSplitQuestionColumn');
        if (questionText.parentElement !== questionContainer) {
            questionContainer.insertBefore(questionText, optionsContainer);
        }
        if (imageContainer.parentElement !== questionContainer) {
            questionContainer.insertBefore(imageContainer, optionsContainer);
        } else if (imageContainer.nextElementSibling !== optionsContainer) {
            questionContainer.insertBefore(imageContainer, optionsContainer);
        }
        if (optionsContainer.parentElement !== questionContainer) {
            questionContainer.appendChild(optionsContainer);
        }
        if (wrapper && wrapper.parentElement && !wrapper.contains(questionText) && !wrapper.contains(imageContainer) && !wrapper.contains(optionsContainer)) {
            wrapper.remove();
        }
        return;
    }

    if (shouldUsePhoneImageRightMount) {
        const wrapper = document.getElementById('mcSplitQuestionColumn');
        if (questionText.parentElement !== questionContainer) {
            questionContainer.insertBefore(questionText, optionsContainer);
        }
        if (optionsContainer.parentElement !== questionContainer) {
            questionContainer.appendChild(optionsContainer);
        }
        if (imageContainer.parentElement !== quizArea) {
            quizArea.insertBefore(imageContainer, questionContainer.nextSibling);
        }
        if (wrapper && wrapper.parentElement && !wrapper.contains(questionText) && !wrapper.contains(imageContainer) && !wrapper.contains(optionsContainer)) {
            wrapper.remove();
        }
        return;
    }

    if (shouldUseSplitMount) {
        const wrapper = getMultipleChoiceSplitQuestionColumn();
        if (wrapper.parentElement !== questionContainer) {
            questionContainer.insertBefore(wrapper, optionsContainer);
        }
        if (questionText.parentElement !== wrapper) {
            wrapper.appendChild(questionText);
        }
        if (imageContainer.parentElement !== wrapper) {
            wrapper.appendChild(imageContainer);
        }
        return;
    }

    const wrapper = document.getElementById('mcSplitQuestionColumn');
    if (questionText.parentElement !== questionContainer) {
        questionContainer.insertBefore(questionText, optionsContainer);
    }
    if (optionsContainer.parentElement !== questionContainer) {
        questionContainer.appendChild(optionsContainer);
    }
    if (imageContainer.parentElement !== quizArea) {
        quizArea.insertBefore(imageContainer, questionContainer.nextSibling);
    }
    if (wrapper && wrapper.parentElement && !wrapper.contains(questionText) && !wrapper.contains(imageContainer) && !wrapper.contains(optionsContainer)) {
        wrapper.remove();
    }
}

function updateViewportClasses() {
    const isFlashcardQuestion = state.currentQuestionType === 'flashcard';
    const isMultipleChoiceStudyQuestion = state.currentQuestionType === 'multiple choice' || state.currentQuestionType === 'diagrams' || state.currentQuestionType === 'typed answer';
    const hasStudyQuestionImage = isMultipleChoiceStudyQuestion && !!state.currentQuestionHasImage;
    document.body.classList.toggle('narrow-iphone-layout', isNarrowIPhoneViewport());
    document.body.classList.toggle('ipad-portrait-flashcard-layout', isFlashcardQuestion && isIPadPortraitFlashcardViewport());
    document.body.classList.toggle('ipad-landscape-flashcard-layout', isFlashcardQuestion && isIPadLandscapeFlashcardViewport());
    document.body.classList.toggle('active-question-multiple-choice', isMultipleChoiceStudyQuestion);
    document.body.classList.toggle('active-question-has-image', hasStudyQuestionImage);
    document.body.classList.toggle('ipad-portrait-mc-image-top-layout', hasStudyQuestionImage && (state.currentQuestionType === 'multiple choice' || state.currentQuestionType === 'diagrams') && isIPadPortraitMultipleChoiceImageTopViewport());
    document.body.classList.toggle('phone-landscape-mc-image-right-layout', hasStudyQuestionImage && isPhoneLandscapeMultipleChoiceImageRightViewport());
    document.body.classList.toggle('active-question-flashcard', isFlashcardQuestion);
    document.body.classList.toggle('active-question-classify', state.currentQuestionType === 'classify');
    document.body.classList.toggle('active-question-typed-answer', state.currentQuestionType === 'typed answer');
    syncMultipleChoiceSplitLayoutMount();
    queuePhoneLandscapeMultipleChoiceImageStageSync();
    queueOptionsScrollIndicatorUpdate();
    queueDesktopFullscreenFlashcardHeightSync();
}

function clearPhoneLandscapeMultipleChoiceImageStage() {
    const wrap = elements.diagramStudyImageWrap;
    const image = elements.questionImage;
    const quizArea = elements.quizArea;
    if (wrap) {
        wrap.style.removeProperty('width');
        wrap.style.removeProperty('height');
    }
    if (image) {
        image.style.removeProperty('width');
        image.style.removeProperty('height');
    }
    if (quizArea) {
        quizArea.style.removeProperty('--phone-landscape-mc-layout-height');
    }
}

function updatePhoneLandscapeMultipleChoiceLayoutBounds() {
    const quizArea = elements.quizArea;
    if (!quizArea) return;

    if (!document.body.classList.contains('phone-landscape-mc-image-right-layout')) {
        quizArea.style.removeProperty('--phone-landscape-mc-layout-height');
        return;
    }

    const rect = quizArea.getBoundingClientRect();
    const viewportHeight = window.visualViewport?.height || window.innerHeight || document.documentElement.clientHeight || 0;
    if (!viewportHeight || !Number.isFinite(rect.top)) return;

    const isFullscreen = document.body.classList.contains('fullscreen-mode');
    const bottomReserve = isFullscreen ? 8 : 12;
    const renderedAvailableHeight = Math.floor(viewportHeight - rect.top - bottomReserve);
    const scaleY = getElementRenderedScaleY(quizArea);
    const cssAvailableHeight = Math.floor(renderedAvailableHeight / scaleY);
    if (!Number.isFinite(cssAvailableHeight) || cssAvailableHeight <= 0) return;

    const maxHeight = isFullscreen ? 420 : 360;
    const safeHeight = Math.min(maxHeight, Math.max(1, cssAvailableHeight));
    quizArea.style.setProperty('--phone-landscape-mc-layout-height', `${safeHeight}px`);
}

function updatePhoneLandscapeMultipleChoiceImageStage() {
    const wrap = elements.diagramStudyImageWrap;
    const image = elements.questionImage;
    const container = elements.imageContainer;

    updatePhoneLandscapeMultipleChoiceLayoutBounds();

    if (!wrap || !image || !container || !document.body.classList.contains('phone-landscape-mc-image-right-layout')) {
        clearPhoneLandscapeMultipleChoiceImageStage();
        return;
    }

    if (image.style.display === 'none' || !image.src) {
        clearPhoneLandscapeMultipleChoiceImageStage();
        return;
    }

    const naturalWidth = image.naturalWidth || 0;
    const naturalHeight = image.naturalHeight || 0;
    const availableWidth = container.clientWidth || 0;
    const availableHeight = container.clientHeight || 0;

    if (!naturalWidth || !naturalHeight || !availableWidth || !availableHeight) {
        return;
    }

    const scale = Math.min(availableWidth / naturalWidth, availableHeight / naturalHeight);
    if (!Number.isFinite(scale) || scale <= 0) return;

    const stageWidth = Math.max(1, Math.floor(naturalWidth * scale));
    const stageHeight = Math.max(1, Math.floor(naturalHeight * scale));

    wrap.style.width = `${stageWidth}px`;
    wrap.style.height = `${stageHeight}px`;
    image.style.width = '100%';
    image.style.height = '100%';
}

function queuePhoneLandscapeMultipleChoiceImageStageSync() {
    const queueState = state.phoneLandscapeMcImageStage;
    if (!queueState) {
        updatePhoneLandscapeMultipleChoiceImageStage();
        return;
    }

    if (queueState.rafId) {
        cancelAnimationFrame(queueState.rafId);
        queueState.rafId = 0;
    }

    queueState.timeoutIds.forEach(timeoutId => clearTimeout(timeoutId));
    queueState.timeoutIds = [];

    updatePhoneLandscapeMultipleChoiceImageStage();
    queueState.rafId = requestAnimationFrame(() => {
        queueState.rafId = 0;
        updatePhoneLandscapeMultipleChoiceImageStage();
        requestAnimationFrame(updatePhoneLandscapeMultipleChoiceImageStage);
    });

    [80, 220, 500].forEach(delay => {
        const timeoutId = setTimeout(updatePhoneLandscapeMultipleChoiceImageStage, delay);
        queueState.timeoutIds.push(timeoutId);
    });
}

function restoreQuestionStarButtonLocation() {
    const button = elements.questionStarBtn;
    const quizControls = document.getElementById('quizControls');
    if (!button || !quizControls) return;
    button.classList.remove('flashcard-menu-star-btn');
    if (button.parentElement !== quizControls) {
        quizControls.appendChild(button);
    }
}

function shouldMountQuestionStarButtonBesideStudyMenu(question = null) {
    const type = normalizeSheetText(question?.type || state.currentQuestionType).toLowerCase();
    return type === 'flashcard' || type === 'multiple choice' || type === 'diagrams' || type === 'typed answer';
}

function mountQuestionStarButtonBesideStudyMenu() {
    const button = elements.questionStarBtn;
    const menuButton = elements.studioHomeBtn;
    const utilityControls = menuButton?.parentElement;
    if (!button || !menuButton || !utilityControls) return;
    button.classList.add('flashcard-menu-star-btn');
    if (button.parentElement !== utilityControls || button.nextElementSibling !== menuButton) {
        utilityControls.insertBefore(button, menuButton);
    }
}

function applyResponsiveControlText() {
    const useCompactIcons = isNarrowIPhoneViewport();

    elements.prevBtn.innerText = useCompactIcons ? '←' : 'Previous';
    elements.restartBtn.innerText = useCompactIcons ? '↻' : 'Restart';
    const multipleAnswerSubmit = isCurrentMultipleAnswerSubmitPending();
    elements.nextBtn.innerText = multipleAnswerSubmit ? 'Submit' : (useCompactIcons ? '→' : 'Next');

    elements.prevBtn.setAttribute('aria-label', 'Previous');
    elements.restartBtn.setAttribute('aria-label', 'Restart');
    elements.nextBtn.setAttribute('aria-label', multipleAnswerSubmit ? 'Submit answer' : 'Next');

    elements.prevBtn.setAttribute('title', 'Previous');
    elements.restartBtn.setAttribute('title', 'Restart');
    elements.nextBtn.setAttribute('title', multipleAnswerSubmit ? 'Submit answer' : 'Next');
}

function clearFlashcardSwipeFeedback() {
    const feedback = document.getElementById('flashcardSwipeFeedback');
    if (feedback) {
        feedback.innerText = '';
        feedback.classList.remove('show', 'know', 'dont-know', 'star-know');
    }
    clearFlashcardSwipeBorderState();
}

function clearFlashcardSwipeBorderState() {
    const card = document.getElementById('flashcardCard');
    if (!card) return;
    card.classList.remove('swiping-know', 'swiping-dont-know', 'swiping-star-know');
}

function setFlashcardSwipeBorderState(kind) {
    const card = document.getElementById('flashcardCard');
    if (!card) return;
    clearFlashcardSwipeBorderState();
    if (kind === 'know') {
        card.classList.add('swiping-know');
    } else if (kind === 'dont-know') {
        card.classList.add('swiping-dont-know');
    } else if (kind === 'star-know') {
        card.classList.add('swiping-star-know');
    }
}

function setFlashcardSwipeFeedback(kind) {
    const feedback = document.getElementById('flashcardSwipeFeedback');
    if (!feedback) return;

    feedback.classList.remove('know', 'dont-know', 'star-know');

    if (kind === 'know') {
        feedback.innerText = 'Know';
        feedback.classList.add('show', 'know');
        return;
    }

    if (kind === 'dont-know') {
        feedback.innerText = "Don't know";
        feedback.classList.add('show', 'dont-know');
        return;
    }

    if (kind === 'star-know') {
        feedback.innerText = '★ Starred';
        feedback.classList.add('show', 'star-know');
        return;
    }

    clearFlashcardSwipeFeedback();
}

function handleViewportChange() {
    updateViewportClasses();
    applyResponsiveControlText();
    updateProgress();
    queueDesktopFullscreenFlashcardHeightSync();
    fitFlashcardTextToFixedCard(document);
    queueFlashcardImageOverlaySync(document);
    queueFlashcardZoomOverlayLabelSync();
    queuePhoneLandscapeMultipleChoiceImageStageSync();
}

