// ================= SETTINGS / FULLSCREEN UI =================
function openSettingsPopup() {
    updateSettingsAvailability();
    elements.settingsPopup.classList.remove('hidden');
    elements.settingsBtn.classList.add('active');
}

function closeSettingsPopup() {
    elements.settingsPopup.classList.add('hidden');
    elements.settingsBtn.classList.remove('active');
    closeAllSettingHelpTooltips();
}

function toggleSettingsPopup() {
    if (elements.settingsPopup.classList.contains('hidden')) {
        openSettingsPopup();
    } else {
        closeSettingsPopup();
    }
}

function closeAllSettingHelpTooltips() {
    elements.settingHelpButtons.forEach(btn => {
        const tooltipId = btn.dataset.helpTarget;
        const tooltip = tooltipId ? document.getElementById(tooltipId) : null;
        btn.setAttribute('aria-expanded', 'false');
        if (tooltip) {
            tooltip.classList.add('hidden');
        }
    });
}

function toggleSettingHelpTooltip(button) {
    if (!button) return;

    const tooltipId = button.dataset.helpTarget;
    const tooltip = tooltipId ? document.getElementById(tooltipId) : null;
    if (!tooltip) return;

    const willOpen = tooltip.classList.contains('hidden');
    closeAllSettingHelpTooltips();

    if (willOpen) {
        tooltip.classList.remove('hidden');
        button.setAttribute('aria-expanded', 'true');
    }
}

function enterFullscreenMode() {
    state.isAppFullscreen = true;
    document.body.classList.add('fullscreen-mode');
    elements.fullscreenBtn.classList.add('active');
    elements.fullscreenBtn.setAttribute('title', 'Exit Fullscreen');
    handleViewportChange();
}

function exitFullscreenMode() {
    state.isAppFullscreen = false;
    document.body.classList.remove('fullscreen-mode');
    elements.fullscreenBtn.classList.remove('active');
    elements.fullscreenBtn.setAttribute('title', 'Fullscreen');
    handleViewportChange();
}

function toggleFullscreenMode() {
    if (state.isAppFullscreen) {
        exitFullscreenMode();
    } else {
        enterFullscreenMode();
    }
}

function isEditableKeyboardShortcutTarget(target) {
    if (!target) return false;
    const editable = target.closest?.('input, textarea, select, [contenteditable="true"], [contenteditable="plaintext-only"]');
    return !!editable;
}

function isStudyKeyboardShortcutBlocked(event) {
    if (event.defaultPrevented) return true;
    if (event.ctrlKey || event.metaKey || event.altKey) return true;
    if (isEditableKeyboardShortcutTarget(event.target)) return true;
    if (state.auth.quizStudioOpen || !elements.quizStudioPage?.classList.contains('hidden')) return true;
    if (elements.authPopup && !elements.authPopup.classList.contains('hidden')) return true;
    if (elements.settingsPopup && !elements.settingsPopup.classList.contains('hidden')) return true;
    if (state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen || state.completionChallengePrompt.open) return true;
    if (!state.questions.length || isQuizFinished()) return true;
    return false;
}

function activateVisibleAnswerShortcut(optionNumber) {
    if (!Number.isInteger(optionNumber) || optionNumber < 1 || optionNumber > 9) return false;
    if (state.questionAnswered || state.optionDelay.active) return false;

    const currentQuestion = state.questionQueue[state.currentIndex] || null;
    if (currentQuestion?.type === 'flashcard') {
        if (optionNumber === 1) {
            gradeFlashcard(false);
            return true;
        }
        if (optionNumber === 2) {
            gradeFlashcard(true);
            return true;
        }
        return false;
    }

    const visibleButtons = Array.from(elements.optionsContainer.querySelectorAll('.optionBtn'))
        .filter(button => !button.disabled && button.offsetParent !== null && button.closest('.option-block')?.style.display !== 'none');
    const targetButton = visibleButtons[optionNumber - 1];
    if (!targetButton) return false;

    targetButton.click();
    return true;
}

function submitCurrentStructuredQuestionShortcut() {
    if (state.questionAnswered) return false;

    const hierarchySubmit = document.getElementById('hierarchySubmit');
    if (hierarchySubmit && !hierarchySubmit.disabled) {
        hierarchySubmit.click();
        return true;
    }

    const classifySubmit = document.getElementById('classifySubmit');
    if (classifySubmit && !classifySubmit.disabled) {
        classifySubmit.click();
        return true;
    }

    return false;
}

function isCurrentFlashcardStudyQuestion() {
    const currentQuestion = state.questionQueue[state.currentIndex] || null;
    return normalizeSheetText(currentQuestion?.type || '').toLowerCase() === 'flashcard';
}

function triggerFlashcardGradeWithSwipeFeedback(knewIt, options = {}) {
    const { starOnKnow = false } = options;
    if (state.flashcardGradeFeedbackPending || state.questionAnswered) return true;
    if (state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen) return true;
    if (isRetentionMode() && state.retentionAnswerLocked) return true;

    const kind = starOnKnow && knewIt ? 'star-know' : (knewIt ? 'know' : 'dont-know');
    state.flashcardGradeFeedbackPending = true;
    setFlashcardSwipeBorderState(kind);
    setFlashcardSwipeFeedback(kind);

    setTimeout(() => {
        state.flashcardGradeFeedbackPending = false;
        Promise.resolve(gradeFlashcard(knewIt, { starOnKnow }))
            .then(result => {
                if (result === false) clearFlashcardSwipeFeedback();
            })
            .catch(error => {
                console.error('Flashcard keyboard action failed:', error);
                clearFlashcardSwipeFeedback();
            });
    }, 90);

    return true;
}

function handleFlashcardStudyKeyboardShortcut(event) {
    if (!isCurrentFlashcardStudyQuestion()) return false;

    const key = event.key;
    const isFlipKey = key === ' ' || key === 'Spacebar' || key === 'Space' || event.code === 'Space' || key === 'ArrowDown';
    const isGradeKey = key === 'ArrowLeft' || key === 'ArrowRight' || key === 'ArrowUp';
    if (!isFlipKey && !isGradeKey) return false;
    if (event.repeat) return false;

    event.preventDefault();

    if (isFlipKey) {
        toggleFlashcardFlip();
        return true;
    }

    if (key === 'ArrowUp') {
        return triggerFlashcardGradeWithSwipeFeedback(true, { starOnKnow: true });
    }

    return triggerFlashcardGradeWithSwipeFeedback(key === 'ArrowRight');
}

function handleStudyKeyboardShortcut(event) {
    const key = event.key;

    if (key === 'f' || key === 'F') {
        if (isStudyKeyboardShortcutBlocked(event)) return false;
        event.preventDefault();
        toggleFullscreenMode();
        return true;
    }

    if (key === 's' || key === 'S') {
        if (isStudyKeyboardShortcutBlocked(event)) return false;
        if (!elements.questionStarBtn || elements.questionStarBtn.disabled || elements.questionStarBtn.classList.contains('hidden')) return false;
        event.preventDefault();
        elements.questionStarBtn.click();
        return true;
    }

    if (/^[1-9]$/.test(key)) {
        if (isStudyKeyboardShortcutBlocked(event)) return false;
        if (event.repeat) return false;
        const handled = activateVisibleAnswerShortcut(Number(key));
        if (handled) event.preventDefault();
        return handled;
    }

    if (isStudyKeyboardShortcutBlocked(event)) return false;
    if (handleFlashcardStudyKeyboardShortcut(event)) return true;

    if (key === 'Enter' || key === ' ' || key === 'Spacebar') {
        if (isStudyKeyboardShortcutBlocked(event)) return false;
        if (event.repeat) return false;

        let handled = false;
        if (state.questionAnswered) {
            if (!elements.nextBtn?.disabled) {
                nextQuestion();
                handled = true;
            }
        } else if (isCurrentMultipleAnswerSubmitPending()) {
            if (!elements.nextBtn?.disabled) {
                elements.nextBtn.click();
                handled = true;
            }
        } else {
            handled = submitCurrentStructuredQuestionShortcut();
        }

        if (handled) event.preventDefault();
        return handled;
    }

    if (key === 'ArrowLeft') {
        if (isStudyKeyboardShortcutBlocked(event)) return false;
        if (elements.prevBtn?.disabled) return false;
        event.preventDefault();
        prevQuestion();
        return true;
    }

    if (key === 'ArrowRight') {
        if (isStudyKeyboardShortcutBlocked(event)) return false;
        if (elements.nextBtn?.disabled) return false;
        event.preventDefault();
        if (isCurrentMultipleAnswerSubmitPending()) {
            elements.nextBtn.click();
        } else {
            nextQuestion();
        }
        return true;
    }

    return false;
}

// ================= STUDY SWIPE NAVIGATION =================
const STUDY_SWIPE_NAVIGATION = {
    startX: 0,
    startY: 0,
    startTime: 0,
    tracking: false
};

function isAppleTouchStudyDevice() {
    const userAgent = navigator.userAgent || '';
    const platform = navigator.platform || '';
    const touchPoints = Number(navigator.maxTouchPoints || 0);
    return /iPad|iPhone|iPod/i.test(userAgent) || (platform === 'MacIntel' && touchPoints > 1);
}

function isStudySwipeNavigationSupportedQuestion() {
    const currentQuestion = state.questionQueue[state.currentIndex] || null;
    return (currentQuestion?.type === 'multiple choice' && state.currentQuestionType === 'multiple choice')
        || isMultipleAnswerStudyQuestion(currentQuestion);
}

function isStudySwipeNavigationBlockedTarget(target) {
    if (!target || !target.closest) return false;
    return !!target.closest([
        'input',
        'select',
        'textarea',
        'a',
        'label',
        '[contenteditable="true"]',
        '.utility-controls',
        '.nav-buttons',
        '#settingsPopup',
        '#authPopup',
        '#quizStudioPage',
        '#learningResourcesOverlay',
        '#flashcardImageOverlay'
    ].join(','));
}

function canUseStudySwipeNavigation(event) {
    if (!isAppleTouchStudyDevice()) return false;
    if (!isStudySwipeNavigationSupportedQuestion()) return false;
    if (state.optionDelay?.active) return false;
    if (state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen) return false;
    if (state.auth.quizStudioOpen || !elements.quizStudioPage?.classList.contains('hidden')) return false;
    if (elements.authPopup && !elements.authPopup.classList.contains('hidden')) return false;
    if (elements.settingsPopup && !elements.settingsPopup.classList.contains('hidden')) return false;
    if (!state.questions.length || isQuizFinished()) return false;
    if (event && isStudySwipeNavigationBlockedTarget(event.target)) return false;
    return true;
}

function handleStudySwipeStart(event) {
    if (!canUseStudySwipeNavigation(event)) {
        STUDY_SWIPE_NAVIGATION.tracking = false;
        return;
    }

    const touch = event.touches?.[0];
    if (!touch) return;

    STUDY_SWIPE_NAVIGATION.startX = touch.clientX;
    STUDY_SWIPE_NAVIGATION.startY = touch.clientY;
    STUDY_SWIPE_NAVIGATION.startTime = Date.now();
    STUDY_SWIPE_NAVIGATION.tracking = true;
}

function handleStudySwipeEnd(event) {
    if (!STUDY_SWIPE_NAVIGATION.tracking) return;
    STUDY_SWIPE_NAVIGATION.tracking = false;

    if (!canUseStudySwipeNavigation(event)) return;

    const touch = event.changedTouches?.[0];
    if (!touch) return;

    const dx = touch.clientX - STUDY_SWIPE_NAVIGATION.startX;
    const dy = touch.clientY - STUDY_SWIPE_NAVIGATION.startY;
    const absX = Math.abs(dx);
    const absY = Math.abs(dy);
    const elapsedMs = Date.now() - STUDY_SWIPE_NAVIGATION.startTime;

    const submitPending = isCurrentMultipleAnswerSubmitPending();

    if (dx <= 0) return;
    if (!submitPending && !state.questionAnswered) return;
    if (elapsedMs > 1200) return;
    if (absX < 64) return;
    if (absX < absY * 1.35) return;
    if (absY > 80) return;
    if (!elements.nextBtn || elements.nextBtn.disabled || elements.nextBtn.getAttribute('aria-disabled') === 'true') return;

    event.preventDefault();
    if (submitPending) {
        elements.nextBtn.click();
    } else {
        nextQuestion();
    }
}

function bindStudySwipeNavigation() {
    if (!elements.quizArea) return;
    elements.quizArea.addEventListener('touchstart', handleStudySwipeStart, { passive: true });
    elements.quizArea.addEventListener('touchend', handleStudySwipeEnd, { passive: false });
    elements.quizArea.addEventListener('touchcancel', () => {
        STUDY_SWIPE_NAVIGATION.tracking = false;
    }, { passive: true });
}


// ================= LEARNING RESOURCES UI =================
function clearPendingLearningResource() {
    state.pendingLearningResource = null;
}

function queueLearningResourceIfEligible(question) {
    const text = normalizeSheetText(question?.learningResources);
    const html = sanitizeLearningResourcesHtml(question?.learningResourcesHtml);
    const imageUrl = normalizeSheetText(question?.learningResourcesImage);
    const hasText = !!(htmlToDisplayText(html) || text);

    if (!canUseLearningResources() || (!hasText && !imageUrl)) {
        state.pendingLearningResource = null;
        return;
    }

    state.pendingLearningResource = {
        text,
        html,
        imageUrl
    };
}

function openLearningResourcesOverlay(hintData) {
    if (!hintData) return;

    const text = normalizeSheetText(hintData.text);
    const html = sanitizeLearningResourcesHtml(hintData.html);
    const imageUrl = normalizeSheetText(hintData.imageUrl);
    const renderedHtml = html || buildStoredHtmlFromPlain(text);
    const hasText = !!(htmlToDisplayText(renderedHtml) || text);
    const hasImage = !!imageUrl;

    if (!hasText && !hasImage) return;

    elements.learningResourcesContent.innerHTML = renderedHtml;
    elements.learningResourcesImageEl.src = '';
    elements.learningResourcesImageEl.alt = 'Learning resource image';
    elements.learningResourcesImagePanel.classList.add('hidden');

    elements.learningResourcesBody.classList.remove('text-only', 'image-only', 'text-image');

    if (hasImage) {
        setImageElementSourceWithMediaResolution(elements.learningResourcesImageEl, imageUrl);
        elements.learningResourcesImagePanel.classList.remove('hidden');
    }

    if (hasText && hasImage) {
        elements.learningResourcesBody.classList.add('text-image');
        elements.learningResourcesTextPanel.classList.remove('hidden');
        elements.learningResourcesImagePanel.classList.remove('hidden');
    } else if (hasText) {
        elements.learningResourcesBody.classList.add('text-only');
        elements.learningResourcesTextPanel.classList.remove('hidden');
        elements.learningResourcesImagePanel.classList.add('hidden');
    } else {
        elements.learningResourcesBody.classList.add('image-only');
        elements.learningResourcesTextPanel.classList.add('hidden');
        elements.learningResourcesImagePanel.classList.remove('hidden');
    }

    elements.learningResourcesOverlay.classList.remove('hidden');
    elements.learningResourcesOverlay.setAttribute('aria-hidden', 'false');
    document.body.classList.add('hint-open');
    state.learningResourcesOverlayOpen = true;
    syncBodyScrollLock();
    updateNavigationButtons();
}

function closeLearningResourcesOverlay() {
    elements.learningResourcesOverlay.classList.add('hidden');
    elements.learningResourcesOverlay.setAttribute('aria-hidden', 'true');
    elements.learningResourcesContent.innerHTML = '';
    elements.learningResourcesImageEl.src = '';
    elements.learningResourcesTextPanel.classList.remove('hidden');
    elements.learningResourcesImagePanel.classList.add('hidden');
    elements.learningResourcesBody.classList.remove('text-only', 'image-only', 'text-image');
    document.body.classList.remove('hint-open');
    state.learningResourcesOverlayOpen = false;
    clearPendingLearningResource();
    syncBodyScrollLock();
    updateNavigationButtons();
}

function showPendingLearningResourceIfAny() {
    if (!state.pendingLearningResource) return;
    openLearningResourcesOverlay(state.pendingLearningResource);
}

// ================= FLASHCARD / STUDY IMAGE ZOOM UI =================
function ensureFlashcardZoomLabelLayer() {
    if (elements.flashcardZoomLabelLayer) return elements.flashcardZoomLabelLayer;
    if (!elements.flashcardZoomImageWrap && elements.flashcardZoomImage?.parentElement) {
        elements.flashcardZoomImageWrap = elements.flashcardZoomImage.parentElement;
    }
    if (!elements.flashcardZoomImageWrap) return null;
    const layer = document.createElement('div');
    layer.id = 'flashcardZoomLabelLayer';
    layer.className = 'flashcard-zoom-label-layer hidden';
    layer.setAttribute('aria-hidden', 'true');
    elements.flashcardZoomImageWrap.appendChild(layer);
    elements.flashcardZoomLabelLayer = layer;
    return layer;
}

function renderFlashcardZoomLabels(labels = []) {
    const layer = ensureFlashcardZoomLabelLayer();
    const safeLabels = normalizeDiagramLabels(labels);
    if (elements.flashcardZoomImageWrap) elements.flashcardZoomImageWrap.__flashcardImageLabels = safeLabels;
    if (!layer) return;
    if (!safeLabels.length) {
        layer.innerHTML = '';
        layer.classList.add('hidden');
        layer.setAttribute('aria-hidden', 'true');
        layer.style.removeProperty('left');
        layer.style.removeProperty('top');
        layer.style.removeProperty('width');
        layer.style.removeProperty('height');
        elements.flashcardZoomImageWrap?.classList.remove('has-diagram-labels');
        clearFlashcardZoomConnectorLayer();
        return;
    }

    layer.innerHTML = safeLabels.map((item, index) => `
        <button type="button" class="diagram-study-label flashcard-zoom-label flashcard-study-label-toggle" data-flashcard-label-toggle="${index}" style="left:${item.x}%; top:${item.y}%" aria-pressed="false">${renderMathChemTextToHtml(item.label)}</button>
    `).join('');
    layer.classList.remove('hidden');
    layer.setAttribute('aria-hidden', 'false');
    elements.flashcardZoomImageWrap?.classList.add('has-diagram-labels');
    syncFlashcardZoomStrokeToggleButtons();
    renderFlashcardZoomConnectorLayer();
    queueFlashcardZoomOverlayLabelSync();
}

function getElementContentBoxSize(element) {
    if (!element) return null;

    // Use layout CSS pixels, not getBoundingClientRect() rendered pixels.
    // getBoundingClientRect() includes transforms/scaling on the app container,
    // which made fullscreen flashcard label stages drift away from the image.
    const layoutWidth = element.clientWidth || element.offsetWidth || 0;
    const layoutHeight = element.clientHeight || element.offsetHeight || 0;

    if (!layoutWidth || !layoutHeight) {
        const rect = element.getBoundingClientRect();
        if (!rect.width || !rect.height) return null;
        return {
            width: Math.max(0, rect.width),
            height: Math.max(0, rect.height)
        };
    }

    const style = window.getComputedStyle(element);
    const paddingX = (parseFloat(style.paddingLeft) || 0) + (parseFloat(style.paddingRight) || 0);
    const paddingY = (parseFloat(style.paddingTop) || 0) + (parseFloat(style.paddingBottom) || 0);
    return {
        width: Math.max(0, layoutWidth - paddingX),
        height: Math.max(0, layoutHeight - paddingY)
    };
}

function getContainedImageStageSize(container, img) {
    if (!container || !img || !img.complete || !img.naturalWidth || !img.naturalHeight) return null;
    const box = getElementContentBoxSize(container);
    if (!box || !box.width || !box.height) return null;

    const imageRatio = img.naturalWidth / img.naturalHeight;
    const boxRatio = box.width / box.height;
    let width = box.width;
    let height = box.height;

    if (boxRatio > imageRatio) {
        height = box.height;
        width = height * imageRatio;
    } else {
        width = box.width;
        height = width / imageRatio;
    }

    return {
        width: Math.max(1, Math.min(box.width, width)),
        height: Math.max(1, Math.min(box.height, height))
    };
}

// Phase 24A.5s — shared Saved Image inset geometry for handwritten flashcards.
// Margin is inside the allocated Half/Full region; padding is only around the
// rectangular image. Neither is tied to the editor-only center dashed guide.
// Do not modify canonical image coordinates, overlay percentages or media files.
function fitHandwrittenSavedImageInset(naturalWidth, naturalHeight, regionWidth, regionHeight) {
    const margin = 12, insetPadding = 8, insetBorder = 1;
    const roomWidth = Math.max(1, Number(regionWidth) - 2 * (margin + insetPadding + insetBorder));
    const roomHeight = Math.max(1, Number(regionHeight) - 2 * (margin + insetPadding + insetBorder));
    const sourceWidth = Math.max(1, Number(naturalWidth) || 1);
    const sourceHeight = Math.max(1, Number(naturalHeight) || 1);
    const scale = Math.min(roomWidth / sourceWidth, roomHeight / sourceHeight);
    const width = Math.max(1, sourceWidth * scale);
    const height = Math.max(1, sourceHeight * scale);
    return {width, height, outerWidth: width + 2 * (insetPadding + insetBorder),
        outerHeight: height + 2 * (insetPadding + insetBorder)};
}

function clearStageLabelLayerOffsets(layer) {
    if (!layer) return;
    layer.style.removeProperty('left');
    layer.style.removeProperty('top');
    layer.style.removeProperty('width');
    layer.style.removeProperty('height');
}

function applyImageStageSize(stage, img, container) {
    const size = getContainedImageStageSize(container, img);
    if (!stage || !size) return false;
    stage.style.width = `${size.width}px`;
    stage.style.height = `${size.height}px`;
    stage.classList.add('is-image-stage-sized');
    return true;
}

function clearImageStageSize(stage) {
    if (!stage) return;
    stage.style.removeProperty('width');
    stage.style.removeProperty('height');
    stage.classList.remove('is-image-stage-sized');
}

function syncFlashcardZoomOverlayLabelBounds() {
    if (!state.flashcardImageZoomOpen) return;
    const wrap = elements.flashcardZoomImageWrap;
    const img = elements.flashcardZoomImage;
    const viewport = elements.flashcardImageViewport;
    const layer = ensureFlashcardZoomLabelLayer();
    if (!wrap || !img || !viewport || !layer) return;
    if (!img.complete || !img.naturalWidth || !img.naturalHeight) return;

    applyImageStageSize(wrap, img, viewport);
    clearStageLabelLayerOffsets(layer);
    renderFlashcardZoomConnectorLayer();
}

function queueFlashcardZoomOverlayLabelSync() {
    requestAnimationFrame(() => {
        syncFlashcardZoomOverlayLabelBounds();
        setTimeout(syncFlashcardZoomOverlayLabelBounds, 80);
        setTimeout(syncFlashcardZoomOverlayLabelBounds, 240);
    });
}

function openFlashcardImageOverlay(src, alt = 'Flashcard image', options = {}) {
    if (!src || !elements.flashcardImageOverlay || !elements.flashcardZoomImage || state.learningResourcesOverlayOpen) return;

    resetFlashcardImageGestureZoom();
    bindFlashcardImagePinchZoom();
    if (!elements.flashcardZoomImageWrap && elements.flashcardZoomImage.parentElement) {
        elements.flashcardZoomImageWrap = elements.flashcardZoomImage.parentElement;
    }

    clearImageStageSize(elements.flashcardZoomImageWrap);
    if (elements.flashcardZoomImageWrap) {
        elements.flashcardZoomImageWrap.__flashcardImageDrawStrokes = cloneImageEditorDrawStrokes(options.imageDrawStrokes || []);
        elements.flashcardZoomImageWrap.__flashcardImageLabels = normalizeDiagramLabels(options.diagramLabels || []);
        elements.flashcardZoomImageWrap.dataset.visibleStrokeLabels = '';
    }
    elements.flashcardZoomImage.src = src;
    elements.flashcardZoomImage.alt = alt;
    renderFlashcardZoomLabels(options.diagramLabels || []);
    renderFlashcardZoomStrokeLayer();
    renderFlashcardZoomConnectorLayer();

    if (elements.flashcardImageViewport) {
        elements.flashcardImageViewport.scrollTop = 0;
        elements.flashcardImageViewport.scrollLeft = 0;
    }

    elements.flashcardImageOverlay.classList.remove('hidden');
    elements.flashcardImageOverlay.setAttribute('aria-hidden', 'false');
    state.flashcardImageZoomOpen = true;

    if (elements.flashcardZoomImage.complete && elements.flashcardZoomImage.naturalWidth) {
        renderFlashcardZoomStrokeLayer();
        renderFlashcardZoomConnectorLayer();
        queueFlashcardZoomOverlayLabelSync();
    } else {
        elements.flashcardZoomImage.addEventListener('load', () => {
            renderFlashcardZoomStrokeLayer();
            renderFlashcardZoomConnectorLayer();
            queueFlashcardZoomOverlayLabelSync();
        }, { once: true });
    }

    syncBodyScrollLock();
    updateNavigationButtons();
}

function closeFlashcardImageOverlay() {
    if (!elements.flashcardImageOverlay || !elements.flashcardZoomImage) return;

    resetFlashcardImageGestureZoom();
    elements.flashcardImageOverlay.classList.add('hidden');
    elements.flashcardImageOverlay.setAttribute('aria-hidden', 'true');
    elements.flashcardZoomImage.src = '';
    elements.flashcardZoomImage.alt = 'Flashcard image';
    clearImageStageSize(elements.flashcardZoomImageWrap);
    clearFlashcardZoomStrokeLayer();
    clearFlashcardZoomConnectorLayer();
    renderFlashcardZoomLabels([]);
    state.flashcardImageZoomOpen = false;
    syncBodyScrollLock();
    updateNavigationButtons();
}

const flashcardImageGesturePointers = new Map();
let flashcardImagePinchGesture = null;
let flashcardImagePanGesture = null;
let flashcardImageZoomScale = 1;
let flashcardImageZoomX = 0;
let flashcardImageZoomY = 0;
const FLASHCARD_IMAGE_MAX_ZOOM = 5;

function applyFlashcardImageGestureTransform() {
    const wrap = elements.flashcardZoomImageWrap;
    if (!wrap) return;
    const scale = Math.max(1, Math.min(FLASHCARD_IMAGE_MAX_ZOOM, Number(flashcardImageZoomScale) || 1));
    flashcardImageZoomScale = scale;
    if (scale <= 1.001) {
        flashcardImageZoomX = 0;
        flashcardImageZoomY = 0;
    }
    wrap.style.transformOrigin = 'center center';
    wrap.style.transform = `translate3d(${flashcardImageZoomX}px, ${flashcardImageZoomY}px, 0) scale(${scale})`;
    elements.flashcardImageViewport?.classList.toggle('is-pinch-zoomed', scale > 1.001);
}

function resetFlashcardImageGestureZoom() {
    flashcardImageGesturePointers.clear();
    flashcardImagePinchGesture = null;
    flashcardImagePanGesture = null;
    flashcardImageZoomScale = 1;
    flashcardImageZoomX = 0;
    flashcardImageZoomY = 0;
    if (elements.flashcardZoomImageWrap) {
        elements.flashcardZoomImageWrap.style.removeProperty('transform');
        elements.flashcardZoomImageWrap.style.removeProperty('transform-origin');
    }
    elements.flashcardImageViewport?.classList.remove('is-pinch-zoomed','is-pinch-panning');
}

function getFlashcardImageTouchPointers() {
    return Array.from(flashcardImageGesturePointers.values()).filter(pointer => pointer.pointerType === 'touch');
}

function beginFlashcardImagePinch() {
    const touches = getFlashcardImageTouchPointers();
    if (touches.length < 2) return false;
    const [a,b] = touches;
    flashcardImagePinchGesture = {
        ids:[a.pointerId,b.pointerId],
        startDistance:Math.max(1,Math.hypot(b.x-a.x,b.y-a.y)),
        startScale:flashcardImageZoomScale,
        startMid:{x:(a.x+b.x)/2,y:(a.y+b.y)/2},
        startX:flashcardImageZoomX,
        startY:flashcardImageZoomY
    };
    flashcardImagePanGesture = null;
    return true;
}

function bindFlashcardImagePinchZoom() {
    const viewport = elements.flashcardImageViewport;
    if (!viewport || viewport.dataset.pinchZoomBound === 'true') return;
    viewport.dataset.pinchZoomBound = 'true';
    viewport.addEventListener('pointerdown', event => {
        if (!state.flashcardImageZoomOpen || event.pointerType !== 'touch' || event.target?.closest?.('[data-flashcard-label-toggle]')) return;
        flashcardImageGesturePointers.set(event.pointerId,{pointerId:event.pointerId,pointerType:event.pointerType,x:event.clientX,y:event.clientY});
        try { viewport.setPointerCapture?.(event.pointerId); } catch (_) {}
        if (getFlashcardImageTouchPointers().length >= 2) beginFlashcardImagePinch();
        else if (flashcardImageZoomScale > 1.001) {
            flashcardImagePanGesture={pointerId:event.pointerId,startX:event.clientX,startY:event.clientY,baseX:flashcardImageZoomX,baseY:flashcardImageZoomY};
        }
    }, {passive:false});
    viewport.addEventListener('pointermove', event => {
        const pointer=flashcardImageGesturePointers.get(event.pointerId); if(!pointer)return;
        pointer.x=event.clientX; pointer.y=event.clientY;
        if (flashcardImagePinchGesture) {
            const touches=getFlashcardImageTouchPointers();
            const a=touches.find(item=>item.pointerId===flashcardImagePinchGesture.ids[0]);
            const b=touches.find(item=>item.pointerId===flashcardImagePinchGesture.ids[1]);
            if(!a||!b)return;
            event.preventDefault();
            const distance=Math.max(1,Math.hypot(b.x-a.x,b.y-a.y));
            const mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2};
            flashcardImageZoomScale=Math.max(1,Math.min(FLASHCARD_IMAGE_MAX_ZOOM,flashcardImagePinchGesture.startScale*(distance/flashcardImagePinchGesture.startDistance)));
            flashcardImageZoomX=flashcardImagePinchGesture.startX+(mid.x-flashcardImagePinchGesture.startMid.x);
            flashcardImageZoomY=flashcardImagePinchGesture.startY+(mid.y-flashcardImagePinchGesture.startMid.y);
            applyFlashcardImageGestureTransform();
        } else if (flashcardImagePanGesture?.pointerId===event.pointerId && flashcardImageZoomScale>1.001) {
            event.preventDefault();
            flashcardImageZoomX=flashcardImagePanGesture.baseX+(event.clientX-flashcardImagePanGesture.startX);
            flashcardImageZoomY=flashcardImagePanGesture.baseY+(event.clientY-flashcardImagePanGesture.startY);
            viewport.classList.add('is-pinch-panning');
            applyFlashcardImageGestureTransform();
        }
    }, {passive:false});
    const end = event => {
        flashcardImageGesturePointers.delete(event.pointerId);
        if (flashcardImagePinchGesture?.ids.includes(event.pointerId)) flashcardImagePinchGesture=null;
        if (flashcardImagePanGesture?.pointerId===event.pointerId) flashcardImagePanGesture=null;
        viewport.classList.remove('is-pinch-panning');
        const touches=getFlashcardImageTouchPointers();
        if(touches.length>=2) beginFlashcardImagePinch();
        else if(touches.length===1 && flashcardImageZoomScale>1.001){const p=touches[0];flashcardImagePanGesture={pointerId:p.pointerId,startX:p.x,startY:p.y,baseX:flashcardImageZoomX,baseY:flashcardImageZoomY};}
        if(flashcardImageZoomScale<=1.001) resetFlashcardImageGestureZoom();
    };
    viewport.addEventListener('pointerup',end);
    viewport.addEventListener('pointercancel',end);
}

function createOptionImageZoomButton(src, alt = 'Option image') {
    const zoomBtn = document.createElement('button');
    zoomBtn.type = 'button';
    zoomBtn.className = 'option-image-zoom-btn';
    zoomBtn.setAttribute('aria-label', 'Zoom option image');
    zoomBtn.setAttribute('title', 'Zoom image');
    zoomBtn.innerText = '⤢';

    const stopZoomTrigger = e => {
        e.preventDefault();
        e.stopPropagation();
    };

    zoomBtn.addEventListener('pointerdown', stopZoomTrigger);
    zoomBtn.addEventListener('pointerup', stopZoomTrigger);
    zoomBtn.addEventListener('click', e => {
        stopZoomTrigger(e);
        openFlashcardImageOverlay(src, alt);
    });

    return zoomBtn;
}

// ================= QUESTION LOADING HELPERS =================
function isQuizDescriptor(value) {
    return !!value && typeof value === "object" && typeof value.source === "string" && typeof value.id === "string";
}

function encodeQuizSelectorValue(quizDescriptor) {
    return isQuizDescriptor(quizDescriptor) ? quizDescriptor.id : "";
}

function getQuizBySelectorValue(selectorValue) {
    const rawValue = normalizeSheetText(selectorValue);
    if (!rawValue) return null;

    const directMatch = state.quizListCache.find(q => q.id === rawValue);
    if (directMatch) return directMatch;

    const sourceQuizId = rawValue.startsWith('sb:') ? rawValue.slice(3) : rawValue;
    return state.quizListCache.find(q =>
        q.source === DATA_SOURCES.SUPABASE
        && normalizeSheetText(q.sourceQuizId) === sourceQuizId
    ) || null;
}

function buildFolderDeckDescriptors(quizDescriptors) {
    const byFolder = new Map();

    quizDescriptors.forEach(quiz => {
        if (!isQuizDescriptor(quiz) || quiz.source === DATA_SOURCES.FOLDER_DECK) return;
        const folderName = normalizeFolderName(quiz.folder);
        if (!byFolder.has(folderName)) {
            byFolder.set(folderName, []);
        }
        byFolder.get(folderName).push(quiz);
    });

    return Array.from(byFolder.entries()).map(([folderName, quizzes]) => ({
        id: `fd:${encodeURIComponent(folderName)}`,
        source: DATA_SOURCES.FOLDER_DECK,
        folder: folderName,
        folderId: '',
        folderSortOrder: quizzes.reduce((minValue, quiz) => Math.min(minValue, Number(quiz.folderSortOrder ?? 0)), Number(quizzes[0]?.folderSortOrder ?? 0)),
        name: 'Study Entire Folder',
        rangeNumber: '',
        sortOrder: -1
    }));
}

async function loadQuestionsForQuizDescriptor(quizDescriptor) {
    if (!isQuizDescriptor(quizDescriptor)) {
        throw new Error('Invalid quiz descriptor');
    }

    if (quizDescriptor.source === DATA_SOURCES.FOLDER_DECK) {
        const memberQuizzes = state.quizListCache.filter(item =>
            isQuizDescriptor(item)
            && item.source !== DATA_SOURCES.FOLDER_DECK
            && normalizeFolderName(item.folder) === normalizeFolderName(quizDescriptor.folder)
        );

        const results = await Promise.all(memberQuizzes.map(async item => {
            const questions = await loadQuestions(item);
            return questions.map(question => ({
                ...question,
                sourceQuizId: normalizeSheetText(question.sourceQuizId || item.sourceQuizId),
                sourceQuizName: normalizeSheetText(item.name)
            }));
        }));
        return results.flat();
    }

    return loadQuestions(quizDescriptor);
}

async function hydrateStarredQuestionState(questions) {
    const questionRows = Array.isArray(questions) ? questions : [];

    questionRows.forEach(question => {
        question.isStarred = false;
    });

    const sourceQuestionIds = questionRows
        .map(question => normalizeSheetText(question?.sourceQuestionId))
        .filter(Boolean);

    if (!state.auth.client || !state.auth.user?.id || !sourceQuestionIds.length) {
        return questionRows;
    }

    try {
        const { data, error } = await state.auth.client
            .from('user_question_state')
            .select('question_id, is_starred')
            .eq('user_id', state.auth.user.id)
            .in('question_id', sourceQuestionIds);

        if (error) throw error;

        const starredMap = new Map((data || []).map(row => [normalizeSheetText(row.question_id), !!row.is_starred]));
        questionRows.forEach(question => {
            question.isStarred = !!starredMap.get(normalizeSheetText(question?.sourceQuestionId));
        });
    } catch (error) {
        console.error('Failed to hydrate starred question state:', error);
    }

    return questionRows;
}

function getFilteredSourceQuestions() {
    const sourceQuestions = Array.isArray(state.sourceQuestions) ? state.sourceQuestions : [];
    if (isOnlyStarredEnabled()) {
        return sourceQuestions.filter(question => !!question.isStarred);
    }
    if (isExcludeStarredEnabled()) {
        return sourceQuestions.filter(question => !question.isStarred);
    }
    return [...sourceQuestions];
}

// Phase 22ND1: Mastery mutates the queue before the answered screen advances.
// Keep star actions anchored to the question that is still visibly rendered.
function getDisplayedStudyQuestion() {
    return state.displayedQuestion || state.questionQueue[state.currentIndex] || null;
}

function syncQuestionStarButton() {
    const button = elements.questionStarBtn;
    if (!button) return;

    const currentQuestion = getDisplayedStudyQuestion();
    const canStar = canPersistQuestionStarState(currentQuestion) && !state.auth.starringInFlight && !isQuizFinished();

    if (!currentQuestion || !canPersistQuestionStarState(currentQuestion) || isQuizFinished()) {
        button.classList.add('hidden');
        button.disabled = true;
        button.innerText = '☆';
        button.classList.remove('starred');
        button.setAttribute('aria-label', 'Star question');
        button.setAttribute('title', 'Star question');
        return;
    }

    button.classList.remove('hidden');
    button.disabled = !canStar;
    button.innerText = currentQuestion.isStarred ? '★' : '☆';
    button.classList.toggle('starred', !!currentQuestion.isStarred);
    button.setAttribute('aria-label', currentQuestion.isStarred ? 'Unstar question' : 'Star question');
    button.setAttribute('title', currentQuestion.isStarred ? 'Unstar question' : 'Star question');
}

function resetPendingStudyAdvanceFlags() {
    state.pendingRetentionJump = false;
    state.pendingRetentionCorrect = false;
    state.retentionAnswerLocked = false;
    state.pendingMasteryAdvance = false;
    state.masteryCheckPendingJump = false;
    state.masteryCheckPendingAdvance = false;
    state.masteryCheckPendingCheckpointStart = false;
    state.masteryCheckPendingCheckpointComplete = false;
}

function isBuildUpCapableQuestionType(value = '') {
    const normalizedType = normalizeSheetText(value).toLowerCase().replace(/_/g, ' ');
    return normalizedType === 'multiple choice' || normalizedType === 'diagrams' || normalizedType === 'flashcard';
}

function isBuildUpSupportedQuestion(question = {}) {
    return isBuildUpCapableQuestionType(question?.type) && !!normalizeBuildUpValue(question?.buildUp);
}

function isAllowBuildUpEnabled() {
    return !!elements.allowBuildUp?.checked;
}

function isTetherBuildUpEnabled() {
    return !!elements.tetherBuildUp?.checked && isAllowBuildUpEnabled() && isTetherBuildUpSupportedModeActive();
}

function getBuildUpGroupKey(question = {}) {
    const buildUp = normalizeBuildUpValue(question?.buildUp);
    if (!buildUp || !isBuildUpCapableQuestionType(question?.type)) return '';
    const scope = normalizeSheetText(question?.sourceQuizId || state.activeQuizDescriptor?.sourceQuizId || state.activeQuizDescriptor?.id || 'active-quiz');
    return `${scope}::${buildUp.toLocaleLowerCase()}`;
}

function getCurrentBuildUpProgressLabel() {
    if (!isAllowBuildUpEnabled()) return '';
    const queue = Array.isArray(state.questionQueue) ? state.questionQueue : [];
    const currentIndex = Number.isFinite(state.currentIndex) ? state.currentIndex : 0;
    const currentQuestion = queue[currentIndex];
    const activeKey = getBuildUpGroupKey(currentQuestion);
    if (!activeKey) return '';

    let startIndex = currentIndex;
    while (startIndex > 0 && getBuildUpGroupKey(queue[startIndex - 1]) === activeKey) {
        startIndex -= 1;
    }

    let endIndex = currentIndex;
    while (endIndex < queue.length - 1 && getBuildUpGroupKey(queue[endIndex + 1]) === activeKey) {
        endIndex += 1;
    }

    const totalInString = endIndex - startIndex + 1;
    if (totalInString <= 1) return '';

    const positionInString = currentIndex - startIndex + 1;
    return `Build Up ${positionInString} of ${totalInString}`;
}

function getBuildUpRunBoundsInQueue(queue = state.questionQueue, index = state.currentIndex) {
    const source = Array.isArray(queue) ? queue : [];
    const safeIndex = Number.isFinite(index) ? Math.max(0, Math.min(index, source.length - 1)) : 0;
    const activeKey = getBuildUpGroupKey(source[safeIndex]);
    if (!activeKey) return { start: safeIndex, end: safeIndex, key: '' };

    let start = safeIndex;
    while (start > 0 && getBuildUpGroupKey(source[start - 1]) === activeKey) {
        start -= 1;
    }

    let end = safeIndex;
    while (end < source.length - 1 && getBuildUpGroupKey(source[end + 1]) === activeKey) {
        end += 1;
    }

    return { start, end, key: activeKey };
}

function getBuildUpRunQuestionsInQueue(queue = state.questionQueue, index = state.currentIndex) {
    const source = Array.isArray(queue) ? queue : [];
    if (!source.length) return [];
    const { start, end, key } = getBuildUpRunBoundsInQueue(source, index);
    if (!key) return source[index] ? [source[index]] : [];
    return source.slice(start, end + 1);
}

function getTetherQuestionIdentity(question = {}) {
    return normalizeSheetText(question?.id || question?.sourceQuestionId || '');
}

function getTetherRunBoundsInQueue(queue = state.questionQueue, index = state.currentIndex) {
    const source = Array.isArray(queue) ? queue : [];
    if (!isTetherBuildUpEnabled() || !source.length) {
        const safeIndex = Number.isFinite(index) ? Math.max(0, Math.min(index, Math.max(0, source.length - 1))) : 0;
        return { start: safeIndex, end: safeIndex, key: '' };
    }
    return getBuildUpRunBoundsInQueue(source, index);
}

function snapIndexToTetherBuildUpRunStart(queue = state.questionQueue, index = state.currentIndex) {
    const source = Array.isArray(queue) ? queue : [];
    if (!source.length) return 0;
    const safeIndex = Number.isFinite(index) ? Math.max(0, Math.min(index, source.length - 1)) : 0;
    if (!isTetherBuildUpEnabled()) return safeIndex;
    const { start, key } = getBuildUpRunBoundsInQueue(source, safeIndex);
    return key ? start : safeIndex;
}

function isAtEndOfTetherBuildUpRun(queue = state.questionQueue, index = state.currentIndex) {
    if (!isTetherBuildUpEnabled()) return true;
    const source = Array.isArray(queue) ? queue : [];
    if (!source.length) return true;
    const safeIndex = Number.isFinite(index) ? Math.max(0, Math.min(index, source.length - 1)) : 0;
    const { end, key } = getBuildUpRunBoundsInQueue(source, safeIndex);
    return !key || safeIndex >= end;
}

function expandQuestionsWithTetherBuildUp(selectedQuestions = [], sourceQuestions = state.questions) {
    const selected = (Array.isArray(selectedQuestions) ? selectedQuestions : []).filter(Boolean);
    if (!selected.length) return [];
    if (!isTetherBuildUpEnabled()) return [...selected];

    const source = (Array.isArray(sourceQuestions) && sourceQuestions.length ? sourceQuestions : selected).filter(Boolean);
    const selectedIds = new Set(selected.map(getTetherQuestionIdentity).filter(Boolean));
    const selectedBuildUpKeys = new Set(selected.map(getBuildUpGroupKey).filter(Boolean));

    const expanded = [];
    const seen = new Set();

    const addQuestion = question => {
        const id = getTetherQuestionIdentity(question);
        const fallbackKey = id || `${expanded.length}:${normalizeSheetText(question?.question || '')}`;
        if (seen.has(fallbackKey)) return;
        seen.add(fallbackKey);
        expanded.push(question);
    };

    source.forEach(question => {
        const id = getTetherQuestionIdentity(question);
        const buildUpKey = getBuildUpGroupKey(question);
        if ((id && selectedIds.has(id)) || (buildUpKey && selectedBuildUpKeys.has(buildUpKey))) {
            addQuestion(question);
        }
    });

    selected.forEach(addQuestion);
    return expanded;
}

function addMasteryCheckSegmentQuestionsWithTether(question) {
    if (!question?.id) return;
    if (state.masteryCheckSegmentIds.has(question.id)) return;
    if (state.masteryCheckMasteredIds.has(question.id)) return;
    state.masteryCheckSegmentIds.add(question.id);
    state.masteryCheckSegmentQuestions.push(question);
}

function updateBuildUpProgressIndicator() {
    const indicator = elements.progressBuildUpTextEl;
    if (!indicator) return;
    const label = getCurrentBuildUpProgressLabel();
    indicator.textContent = label;
    indicator.classList.toggle('hidden', !label);
}

function buildQuestionBlocksPreservingBuildUp(questions = []) {
    const source = Array.isArray(questions) ? questions : [];
    if (!isAllowBuildUpEnabled()) {
        return source.map(question => [question]);
    }

    const grouped = new Map();
    source.forEach(question => {
        const key = getBuildUpGroupKey(question);
        if (!key) return;
        if (!grouped.has(key)) grouped.set(key, []);
        grouped.get(key).push(question);
    });

    const emittedGroups = new Set();
    const blocks = [];
    source.forEach(question => {
        const key = getBuildUpGroupKey(question);
        if (!key) {
            blocks.push([question]);
            return;
        }
        if (emittedGroups.has(key)) return;
        emittedGroups.add(key);
        blocks.push(grouped.get(key) || [question]);
    });
    return blocks;
}

function buildStudyQuestionQueue(questions = [], { shuffle = false } = {}) {
    const blocks = buildQuestionBlocksPreservingBuildUp(questions);
    if (shuffle) {
        shuffleArray(blocks);
    }
    return blocks.flat();
}

function applyFilteredQuestionsToSession({ resetSession = true, preserveQuestionId = '' } = {}) {
    const visibleQuestions = getFilteredSourceQuestions();
    state.emptyQuizMessage = '';

    if (resetSession) {
        resetModeState();
    } else {
        resetPendingStudyAdvanceFlags();
    }

    state.questions = [...visibleQuestions];
    if (resetSession) beginQuizSpacedAttempt(visibleQuestions);
    state.questionQueue = buildStudyQuestionQueue(visibleQuestions, {
        shuffle: !!document.getElementById('shuffleQuestions')?.checked && resetSession
    });

    if (preserveQuestionId) {
        const preservedIndex = state.questionQueue.findIndex(question => question.id === preserveQuestionId);
        state.currentIndex = preservedIndex >= 0 ? preservedIndex : 0;
    } else if (!resetSession) {
        if (state.currentIndex >= state.questionQueue.length) {
            state.currentIndex = Math.max(0, state.questionQueue.length - 1);
        }
    } else {
        state.currentIndex = 0;
    }

    if (!state.questions.length) {
        state.normalFinished = false;
        state.retentionFinished = false;
        state.masteryCheckFinished = false;
        state.emptyQuizMessage = isOnlyStarredEnabled() && state.sourceQuestions.length
            ? 'No starred questions are available in this deck.'
            : (isExcludeStarredEnabled() && state.sourceQuestions.length
                ? 'All questions in this deck are currently starred and excluded.'
                : 'This quiz has no questions.');
    }

    updateSettingsAvailability();
    showQuestion();
}

async function applyLoadedQuestions(newQuestions) {
    const hydratedQuestions = await hydrateStarredQuestionState(newQuestions);
    state.sourceQuestions = [...hydratedQuestions];
    applyFilteredQuestionsToSession({ resetSession: true });
}

function normalizeFolderName(value) {
    return normalizeSheetText(value) || 'Uncategorized';
}

function htmlToDisplayText(value) {
    const raw = String(value ?? '').trim();
    if (!raw) return '';

    const temp = document.createElement('div');
    temp.innerHTML = raw;
    return normalizeSheetText(temp.textContent || temp.innerText || '');
}

function getStoredTextForDisplay(plainValue, htmlValue) {
    const plain = normalizeSheetText(plainValue);
    if (plain) return displayMathChemTextForEditor(plain);
    return displayMathChemTextForEditor(htmlToDisplayText(htmlValue));
}

function resetQuizSelector() {
    elements.quizSelector.innerHTML = '<option value="">Choose quiz</option>';
    elements.quizSelector.value = '';
    elements.quizSelector.disabled = true;
}

function renderSelectionPrompt(message = 'Choose a folder and a quiz.') {
    clearQuestionUI();
    state.displayedQuestion = null;
    state.currentQuestionType = '';
    updateViewportClasses();

    if (elements.questionStarBtn) {
        elements.questionStarBtn.classList.add('hidden');
        elements.questionStarBtn.disabled = true;
    }

    elements.questionTextEl.style.display = 'block';
    elements.questionTextEl.innerText = message;
    elements.optionsContainer.style.display = 'none';
    elements.imageContainer.style.display = '';
    elements.questionImage.style.display = 'none';
    elements.questionImage.src = '';

    clearFeedback();
    updateProgress();
    updateNavigationButtons();
    syncQuestionStarButton();
}

function clearActiveQuizSelection(message = 'Choose a folder and a quiz.') {
    state.questions = [];
    state.questionQueue = [];
    state.sourceQuestions = [];
    state.activeQuizDescriptor = null;
    state.activeQuizChallenge = null;
    state.emptyQuizMessage = '';
    resetModeState();
    updateSettingsAvailability();
    renderSelectionPrompt(message);
}

function getFolderNames() {
    const seen = new Set();
    const folders = [];

    state.quizListCache.forEach(q => {
        if (!seen.has(q.folder)) {
            seen.add(q.folder);
            folders.push(q.folder);
        }
    });

    return folders;
}

// ================= LOAD QUIZ LIST =================
function createGoogleSheetsQuizDescriptor(row) {
    const sheet = getCellValue(row.c?.[0]);
    const name = getCellValue(row.c?.[1]);

    if (!sheet || !name) {
        return null;
    }

    return {
        id: `gs:${sheet}`,
        source: DATA_SOURCES.GOOGLE_SHEETS,
        sourceQuizId: sheet,
        sheet,
        name,
        rangeNumber: getCellValue(row.c?.[2]),
        folder: normalizeFolderName(getCellValue(row.c?.[3]))
    };
}

async function loadQuizListFromGoogleSheets() {
    const res = await fetch(`https://docs.google.com/spreadsheets/d/${CONFIG.sheetId}/gviz/tq?sheet=Config`);
    const text = await res.text();
    const json = parseGoogleSheetResponse(text);

    return json.table.rows
        .map(createGoogleSheetsQuizDescriptor)
        .filter(Boolean);
}

async function loadGoogleSheetsImportCatalog() {
    if (!state.auth.user?.id) {
        state.googleSheetsImportQuizzes = [];
        renderGoogleSheetsImportControls();
        return [];
    }

    try {
        state.googleSheetsImportQuizzes = await loadQuizListFromGoogleSheets();
    } catch (error) {
        console.error('Failed to load Google Sheets import catalog:', error);
        state.googleSheetsImportQuizzes = [];
    }

    renderGoogleSheetsImportControls();
    return state.googleSheetsImportQuizzes;
}

async function loadQuizListFromSupabase(options = {}) {
    if (!state.auth.client || !state.auth.user?.id) {
        invalidateSupabaseManagementCache(['quizList']);
        return [];
    }

    try {
        if (!options.force && isSupabaseManagementCacheFresh('quizList')) {
            return clonePlainArrayRows(getSupabaseManagementCacheEntry('quizList')?.quizList || []);
        }

        if (!options.force && isSupabaseManagementCacheFresh('managedQuizzes') && state.auth.managedQuizzes.length) {
            const descriptors = buildSupabaseQuizDescriptorsFromManagedQuizzes();
            setSupabaseManagementCacheEntry('quizList', { quizList: descriptors });
            return clonePlainArrayRows(descriptors);
        }

        const entry = await runCachedSupabaseManagementRequest('quizList', options, async () => {
            const [{ data: folders, error: foldersError }, { data: quizzes, error: quizzesError }, questionRows, multipleChoiceRows] = await Promise.all([
                state.auth.client
                    .from('folders')
                    .select('id, name, sort_order')
                    .order('sort_order', { ascending: true })
                    .order('name', { ascending: true }),
                state.auth.client
                    .from('quizzes')
                    .select('id, folder_id, name, description, sort_order, is_archived')
                    .eq('is_archived', false)
                    .order('sort_order', { ascending: true })
                    .order('name', { ascending: true }),
                fetchAllSupabaseRows(
                    () => state.auth.client
                        .from('questions')
                        .select('id, quiz_id, question_type')
                        .order('quiz_id', { ascending: true }),
                    { label: 'quiz catalog question rows' }
                ),
                loadQuizCatalogMultipleChoiceMetadataRows('quiz catalog typed-answer metadata rows')
            ]);

            if (foldersError) throw foldersError;
            if (quizzesError) throw quizzesError;

            const folderMap = new Map((folders || []).map(folder => [folder.id, folder]));
            const quizTypeMap = new Map();
            const multipleChoiceMetadataByQuestionId = new Map();
            (multipleChoiceRows || []).forEach(row => {
                multipleChoiceMetadataByQuestionId.set(row.question_id, row);
            });

            (questionRows || []).forEach(row => {
                if (!quizTypeMap.has(row.quiz_id)) {
                    quizTypeMap.set(row.quiz_id, []);
                }
                quizTypeMap.get(row.quiz_id).push(getEffectiveQuestionTypeFromDetail(row.question_type, multipleChoiceMetadataByQuestionId.get(row.id)));
            });

            const quizList = (quizzes || [])
                .filter(quiz => (quizTypeMap.get(quiz.id) || []).length > 0)
                .map(quiz => {
                    const types = (quizTypeMap.get(quiz.id) || [])
                        .map(type => normalizeSheetText(type || 'multiple_choice') || 'multiple_choice');
                    const uniqueTypes = Array.from(new Set(types));
                    const storedQuizMode = getQuizModeFromDescription(quiz.description || '');
                    const quizType = storedQuizMode === 'exam' ? 'exam' : (uniqueTypes.length === 1 ? uniqueTypes[0] : 'mixed');
                    const folder = folderMap.get(quiz.folder_id) || null;
                    return {
                        id: `sb:${quiz.id}`,
                        source: DATA_SOURCES.SUPABASE,
                        sourceQuizId: quiz.id,
                        quizType,
                        folderId: quiz.folder_id || '',
                        folder: normalizeFolderName(folder?.name),
                        folderSortOrder: Number(folder?.sort_order ?? 0),
                        name: normalizeSheetText(quiz.name),
                        rangeNumber: '',
                        sortOrder: Number(quiz.sort_order ?? 0)
                    };
                })
                .sort((a, b) => {
                    if (a.folderSortOrder !== b.folderSortOrder) return a.folderSortOrder - b.folderSortOrder;
                    if (a.folder !== b.folder) return a.folder.localeCompare(b.folder);
                    if (a.sortOrder !== b.sortOrder) return a.sortOrder - b.sortOrder;
                    return a.name.localeCompare(b.name);
                });
            return { quizList };
        });
        return clonePlainArrayRows(entry?.quizList || []);
    } catch (error) {
        console.error('Failed to load Supabase quiz list:', error);
        return [];
    }
}


async function buildExamQuestionsFromSupabaseRows(rows, quizDescriptor, quizName, markLoad) {
    const unresolvedIssueRows = (rows || []).filter(row => getStoredQuestionImportIssues(row).length);
    if (unresolvedIssueRows.length) {
        const preview = unresolvedIssueRows.slice(0, 5).map((row, index) => {
            const rowIndex = rows.findIndex(item => item.id === row.id);
            return `Q${rowIndex + 1}: ${getStoredQuestionImportIssues(row).join('; ')}`;
        }).join(' | ');
        const remainder = unresolvedIssueRows.length > 5 ? ` (+${unresolvedIssueRows.length - 5} more)` : '';
        throw createStudyLoadDiagnosticError(`"${quizName}" has ${unresolvedIssueRows.length} imported ${unresolvedIssueRows.length === 1 ? 'question' : 'questions'} that need attention before study mode can begin. ${preview}${remainder}`);
    }

    const mcRows = [];
    const hierarchyRows = [];
    const classifyRows = [];
    (rows || []).forEach(row => {
        const storedType = normalizeSheetText(row?.question_type || 'multiple_choice') || 'multiple_choice';
        if (storedType === 'hierarchy') hierarchyRows.push(row);
        else if (storedType === 'classify') classifyRows.push(row);
        else mcRows.push(row);
    });

    const [mcDetails, hierarchyDetails, classifyDetails] = await Promise.all([
        mcRows.length ? loadMultipleChoiceDetailsByQuestionIds(mcRows.map(row => row.id)) : Promise.resolve([]),
        hierarchyRows.length ? loadHierarchyDetailsByQuestionIds(hierarchyRows.map(row => row.id)) : Promise.resolve([]),
        classifyRows.length ? loadClassifyDetailsByQuestionIds(classifyRows.map(row => row.id)) : Promise.resolve([])
    ]);
    markLoad('Exam question details');

    const mcMap = new Map((mcDetails || []).map(row => [row.question_id, row]));
    const hierarchyMap = new Map((hierarchyDetails || []).map(row => [row.question_id, row]));
    const classifyMap = new Map((classifyDetails || []).map(row => [row.question_id, row]));
    const sourceQuizId = normalizeSheetText(quizDescriptor.sourceQuizId);

    const questions = (rows || []).map(row => {
        const storedType = normalizeSheetText(row?.question_type || 'multiple_choice') || 'multiple_choice';
        if (storedType === 'hierarchy') {
            const detail = hierarchyMap.get(row.id);
            if (!detail) throw createStudyLoadDiagnosticError(`Exam question is missing its hierarchy details in "${quizName}".`);
            const itemDrafts = getHierarchyDraftsFromDetailRow(detail);
            const options = itemDrafts.map(item => normalizeSheetText(item.text));
            const correctOrder = itemDrafts
                .map((draft, index) => ({ position: Number(draft.position || index + 1), originalIndex: index + 1 }))
                .sort((a, b) => a.position - b.position)
                .map(item => item.originalIndex);
            return {
                id: `q_${state.questionIdCounter++}`,
                sourceQuestionId: row.id,
                sourceQuizId,
                type: 'hierarchy',
                examMode: true,
                question: getStoredTextForDisplay(row.prompt_plain, parseStoredQuestionImportIssues(row.prompt_html).html),
                options,
                correctOrder,
                image: normalizeSheetText(row.image_url),
                learningResources: getStoredTextForDisplay('', row.learning_resources_html),
                learningResourcesHtml: normalizeSheetText(row.learning_resources_html),
                learningResourcesImage: normalizeSheetText(row.learning_resources_image_url)
            };
        }
        if (storedType === 'classify') {
            const detail = classifyMap.get(row.id);
            if (!detail) throw createStudyLoadDiagnosticError(`Exam question is missing its classify details in "${quizName}".`);
            const items = Array.isArray(detail.items_json) ? detail.items_json.map(item => ({
                kind: normalizeSheetText(item?.kind || (item?.imageUrl ? 'image' : 'text')) || 'text',
                raw: normalizeSheetText(item?.raw || item?.text),
                imageUrl: normalizeSheetText(item?.imageUrl),
                text: normalizeSheetText(item?.text || item?.raw),
                dragLabel: normalizeSheetText(item?.dragLabel || item?.text || item?.raw || 'Image item'),
                ariaLabel: normalizeSheetText(item?.ariaLabel || `Classify item ${item?.text || item?.raw || 'image'}`),
                correctClassificationId: normalizeSheetText(item?.correctClassificationId)
            })) : [];
            const classifications = Array.isArray(detail.classifications_json) ? detail.classifications_json.map(classification => ({
                label: normalizeSheetText(classification?.label),
                imageUrl: normalizeSheetText(classification?.imageUrl),
                id: normalizeSheetText(classification?.id)
            })).filter(classification => classification.id && (classification.label || classification.imageUrl)) : [];
            return {
                id: `q_${state.questionIdCounter++}`,
                sourceQuestionId: row.id,
                sourceQuizId,
                type: 'classify',
                examMode: true,
                question: getStoredTextForDisplay(row.prompt_plain, parseStoredQuestionImportIssues(row.prompt_html).html),
                items,
                classifications,
                image: normalizeSheetText(row.image_url),
                learningResources: getStoredTextForDisplay('', row.learning_resources_html),
                learningResourcesHtml: normalizeSheetText(row.learning_resources_html),
                learningResourcesImage: normalizeSheetText(row.learning_resources_image_url)
            };
        }

        const detail = mcMap.get(row.id);
        if (!detail) throw createStudyLoadDiagnosticError(`Exam question is missing its multiple-choice/typed-answer details in "${quizName}".`);
        const effectiveType = getEffectiveQuestionTypeFromDetail(storedType, detail);
        if (effectiveType === 'typed_answer') {
            const acceptedAnswers = getTypedAnswerVariantsFromDetailRow(detail);
            return {
                id: `q_${state.questionIdCounter++}`,
                sourceQuestionId: row.id,
                sourceQuizId,
                type: 'typed answer',
                examMode: true,
                question: getStoredTextForDisplay(row.prompt_plain, parseStoredQuestionImportIssues(row.prompt_html).html),
                acceptedAnswers,
                correct: normalizeSheetText(detail.correct_answer) || acceptedAnswers[0] || '',
                correctExplanation: getStoredTextForDisplay('', detail.correct_explanation_html),
                image: normalizeSheetText(row.image_url),
                diagramLabels: getDiagramLabelsFromDetailRow(detail),
                learningResources: getStoredTextForDisplay('', row.learning_resources_html),
                learningResourcesHtml: normalizeSheetText(row.learning_resources_html),
                learningResourcesImage: normalizeSheetText(row.learning_resources_image_url)
            };
        }

        const optionDrafts = getMultipleChoiceDraftsFromDetailRow(detail);
        const options = optionDrafts.map(draft => draft.text);
        const optionImages = optionDrafts.map(draft => normalizeSheetText(draft.imageUrl));
        const answerValues = optionDrafts.map(getOptionAnswerValue);
        const explanations = optionDrafts.map(draft => draft.explanation);
        const correctAnswer = normalizeSheetText(detail.correct_answer);
        const correctAnswers = getMultipleChoiceCorrectAnswersFromDetailRow(detail);
        const correctIndex = answerValues.findIndex(value => value === correctAnswer);
        if (correctIndex >= 0 && !explanations[correctIndex]) explanations[correctIndex] = getStoredTextForDisplay('', detail.correct_explanation_html);
        correctAnswers.forEach(answer => {
            const answerIndex = answerValues.findIndex(value => value === answer);
            if (answerIndex >= 0 && !explanations[answerIndex]) explanations[answerIndex] = getStoredTextForDisplay('', detail.correct_explanation_html);
        });
        return {
            id: `q_${state.questionIdCounter++}`,
            sourceQuestionId: row.id,
            sourceQuizId,
            type: 'multiple choice',
            examMode: true,
            question: getStoredTextForDisplay(row.prompt_plain, parseStoredQuestionImportIssues(row.prompt_html).html),
            options,
            optionImages,
            correct: correctAnswer,
            correctAnswers: correctAnswers.length ? correctAnswers : (correctAnswer ? [correctAnswer] : []),
            allowMultipleAnswers: getAllowMultipleAnswersFromDetailRow(detail),
            explanations,
            buildUp: '',
            image: normalizeSheetText(row.image_url),
            diagramLabels: getQuestionImageLabelsFromDetailRow(detail),
            learningResources: getStoredTextForDisplay('', row.learning_resources_html),
            learningResourcesHtml: normalizeSheetText(row.learning_resources_html),
            learningResourcesImage: normalizeSheetText(row.learning_resources_image_url)
        };
    });

    if (!questions.length) throw createStudyLoadDiagnosticError(`No usable Exam questions were built for "${quizName}".`);
    return resolveSupabaseMediaReferencesForStudyLoad(questions, `Exam "${quizName}"`);
}

async function loadQuestionsFromSupabase(quizDescriptor) {
    if (!state.auth.client || !quizDescriptor?.sourceQuizId) {
        return [];
    }

    const quizName = normalizeSheetText(quizDescriptor?.name || 'this quiz');
    const markLoad = createStudyBunnyLoadTimer(`study quiz ${quizName}`);

    try {
        const [{ data: questionRows, error: questionsError }, { data: quizRow, error: quizError }] = await Promise.all([
            state.auth.client
                .from('questions')
                .select('id, prompt_html, prompt_plain, image_url, learning_resources_html, learning_resources_image_url, sort_order, question_type')
                .eq('quiz_id', quizDescriptor.sourceQuizId)
                .order('sort_order', { ascending: true }),
            state.auth.client
                .from('quizzes')
                .select('description')
                .eq('id', quizDescriptor.sourceQuizId)
                .maybeSingle()
        ]);
        if (questionsError) {
            throw createStudyLoadDiagnosticError(`Could not read question rows for "${quizName}": ${questionsError.message || questionsError.details || questionsError}`);
        }
        if (quizError) {
            throw createStudyLoadDiagnosticError(`Could not read quiz metadata for "${quizName}": ${quizError.message || quizError.details || quizError}`);
        }
        markLoad('question rows');

        const diagramSharing = getDiagramSharingFromDescription(quizRow?.description || '');
        const handwrittenFlashcardConfig = getHandwrittenFlashcardConfigFromDescription(quizRow?.description || '');
        const rows = questionRows || [];
        const questionIds = rows.map(row => row.id).filter(Boolean);
        if (!questionIds.length) {
            throw createStudyLoadDiagnosticError(`"${quizName}" has no saved question rows.`);
        }

        const rowTypes = Array.from(new Set(rows.map(row => normalizeSheetText(row?.question_type || 'multiple_choice') || 'multiple_choice')));
        const storedQuizMode = getQuizModeFromDescription(quizRow?.description || '');
        let quizType = storedQuizMode === 'exam'
            ? 'exam'
            : normalizeSheetText(quizDescriptor.quizType || rowTypes[0] || 'multiple_choice');
        if (rowTypes.length > 1 && quizType !== 'exam') {
            throw createStudyLoadDiagnosticError(`"${quizName}" has mixed question types (${rowTypes.join(', ')}), but it is not marked as an Exam.`);
        }

        const supportedTypes = new Set(['multiple_choice', 'flashcard', 'hierarchy', 'classify', 'diagrams', 'typed_answer', 'exam']);
        if (!supportedTypes.has(quizType)) {
            throw createStudyLoadDiagnosticError(`"${quizName}" uses unsupported question type "${quizType}".`);
        }

        if (quizType === 'exam') {
            return buildExamQuestionsFromSupabaseRows(rows, quizDescriptor, quizName, markLoad);
        }

        const sharedDiagramSourceQuestionId = getDiagramSharingSourceQuestionId(diagramSharing);
        const sharedDiagramSourceRow = sharedDiagramSourceQuestionId
            ? rows.find(row => normalizeSheetText(row?.id) === sharedDiagramSourceQuestionId)
            : null;
        const sharedDiagramSourceImageUrl = normalizeSheetText(sharedDiagramSourceRow?.image_url);
        const effectiveSharedDiagramImageUrl = diagramSharing.useSharedImage
            ? await getFirstLoadableMediaValue([sharedDiagramSourceImageUrl, diagramSharing.sharedImageUrl])
            : '';
        if (diagramSharing.useSharedImage && sharedDiagramSourceRow && !sharedDiagramSourceImageUrl && effectiveSharedDiagramImageUrl) {
            sharedDiagramSourceRow.image_url = effectiveSharedDiagramImageUrl;
        }

        if (quizType === 'flashcard') {
            const detailRows = await loadFlashcardDetailsByQuestionIds(questionIds, { includeImages: true });
            markLoad('flashcard details');
            assertExpectedDetailRowsForStudyLoad(questionIds, detailRows, 'flashcard', quizName);
            const detailMap = new Map((detailRows || []).map(row => [row.question_id, row]));
            const questions = rows.map(row => {
                const detail = detailMap.get(row.id);
                if (!detail) return null;
                const parsedTermSide = parseStoredFlashcardSideContent(detail.term_html || '');
                const parsedDefinitionSide = parseStoredFlashcardSideContent(detail.definition_html || '');
                return {
                    id: `q_${state.questionIdCounter++}`,
                    sourceQuestionId: row.id,
                    sourceQuizId: normalizeSheetText(quizDescriptor.sourceQuizId),
                    type: 'flashcard',
                    buildUp: normalizeBuildUpValue(detail.build_up),
                    termText: getStoredTextForDisplay(detail.term_plain, parsedTermSide.html),
                    termHtml: parsedTermSide.html,
                    definitionText: getStoredTextForDisplay(detail.definition_plain, parsedDefinitionSide.html),
                    definitionHtml: parsedDefinitionSide.html,
                    termImage: parsedTermSide.imagePresent === false ? '' : normalizeSheetText(detail.term_image_url),
                    definitionImage: parsedDefinitionSide.imagePresent === false ? '' : normalizeSheetText(detail.definition_image_url),
                    flashcardImagesDeferred: false,
                    termImageKnownAbsent: parsedTermSide.imagePresent === false,
                    definitionImageKnownAbsent: parsedDefinitionSide.imagePresent === false,
                    termImageLabels: parsedTermSide.labels,
                    definitionImageLabels: parsedDefinitionSide.labels,
                    termImageDrawStrokes: parsedTermSide.drawStrokes,
                    definitionImageDrawStrokes: parsedDefinitionSide.drawStrokes,
                    termImageSavedSignature: parsedTermSide.savedImageSignature,
                    definitionImageSavedSignature: parsedDefinitionSide.savedImageSignature,
                    termContentMode: parsedTermSide.contentMode,
                    definitionContentMode: parsedDefinitionSide.contentMode,
                    termImagePlacement: parsedTermSide.imagePlacement,
                    definitionImagePlacement: parsedDefinitionSide.imagePlacement,
                    termImageLayout: normalizeFlashcardImageLayout(parsedTermSide.imageLayout, !!normalizeSheetText(detail.term_image_url)),
                    definitionImageLayout: normalizeFlashcardImageLayout(parsedDefinitionSide.imageLayout, !!normalizeSheetText(detail.definition_image_url)),
                    termHandwriting: [],
                    definitionHandwriting: [],
                    flashcardHandwritingDeferred: handwrittenFlashcardConfig.enabled && (parsedTermSide.contentMode === 'handwritten' || parsedDefinitionSide.contentMode === 'handwritten'),
                    handwrittenQuizEnabled: handwrittenFlashcardConfig.enabled,
                    handwrittenFlashcardStyle: handwrittenFlashcardConfig.style,
                    learningResources: getStoredTextForDisplay('', row.learning_resources_html),
                    learningResourcesHtml: normalizeSheetText(row.learning_resources_html),
                    learningResourcesImage: normalizeSheetText(row.learning_resources_image_url)
                };
            }).filter(Boolean);
            if (!questions.length) throw createStudyLoadDiagnosticError(`No usable flashcards were built for "${quizName}".`);
            if (handwrittenFlashcardConfig.enabled) {
                const handwrittenQuestionIds = questions
                    .filter(question => question.flashcardHandwritingDeferred)
                    .map(question => normalizeSheetText(question.sourceQuestionId))
                    .filter(Boolean);
                if (handwrittenQuestionIds.length) {
                    await refreshFlashcardHandwritingRevisionManifest(handwrittenQuestionIds);
                    markLoad('handwriting revisions');
                }
            }
            markLoad('flashcards built');
            return questions;
        }

        if (quizType === 'hierarchy') {
            const detailRows = await loadHierarchyDetailsByQuestionIds(questionIds);
            assertExpectedDetailRowsForStudyLoad(questionIds, detailRows, 'hierarchy', quizName);
            const detailMap = new Map((detailRows || []).map(row => [row.question_id, row]));
            const questions = rows.map(row => {
                const detail = detailMap.get(row.id);
                if (!detail) return null;
                const itemDrafts = getHierarchyDraftsFromDetailRow(detail);
                const sortedByOriginalIndex = itemDrafts
                    .map((draft, index) => ({ ...draft, originalIndex: index + 1 }))
                    .sort((a, b) => a.originalIndex - b.originalIndex);
                const correctOrder = itemDrafts
                    .map((draft, index) => ({ position: Number(draft.position || index + 1), originalIndex: index + 1 }))
                    .sort((a, b) => a.position - b.position)
                    .map(item => item.originalIndex);
                return {
                    id: `q_${state.questionIdCounter++}`,
                    sourceQuestionId: row.id,
                    question: getStoredTextForDisplay(row.prompt_plain, row.prompt_html),
                    type: 'hierarchy',
                    options: sortedByOriginalIndex.map(item => item.text),
                    correctOrder,
                    image: normalizeSheetText(row.image_url),
                    learningResources: getStoredTextForDisplay('', row.learning_resources_html),
                    learningResourcesHtml: normalizeSheetText(row.learning_resources_html),
                    learningResourcesImage: normalizeSheetText(row.learning_resources_image_url)
                };
            }).filter(Boolean);
            if (!questions.length) throw createStudyLoadDiagnosticError(`No usable hierarchy questions were built for "${quizName}".`);
            return resolveSupabaseMediaReferencesForStudyLoad(questions, `Hierarchy quiz "${quizName}"`);
        }

        if (quizType === 'classify') {
            const detailRows = await loadClassifyDetailsByQuestionIds(questionIds);
            assertExpectedDetailRowsForStudyLoad(questionIds, detailRows, 'classify', quizName);
            const detailMap = new Map((detailRows || []).map(row => [row.question_id, row]));
            const questions = rows.map(row => {
                const detail = detailMap.get(row.id);
                if (!detail) return null;
                const items = Array.isArray(detail.items_json) ? detail.items_json.map(item => ({
                    kind: normalizeSheetText(item?.kind || (item?.imageUrl ? 'image' : 'text')) || 'text',
                    raw: normalizeSheetText(item?.raw || item?.text),
                    imageUrl: normalizeSheetText(item?.imageUrl),
                    text: normalizeSheetText(item?.text || item?.raw),
                    dragLabel: normalizeSheetText(item?.dragLabel || item?.text || item?.raw || 'Image item'),
                    ariaLabel: normalizeSheetText(item?.ariaLabel || `Classify item ${item?.text || item?.raw || 'image'}`),
                    correctClassificationId: normalizeSheetText(item?.correctClassificationId)
                })) : [];
                const classifications = Array.isArray(detail.classifications_json) ? detail.classifications_json.map(classification => ({
                    label: normalizeSheetText(classification?.label),
                    imageUrl: normalizeSheetText(classification?.imageUrl),
                    id: normalizeSheetText(classification?.id)
                })).filter(classification => classification.id && (classification.label || classification.imageUrl)) : [];
                return {
                    id: `q_${state.questionIdCounter++}`,
                    sourceQuestionId: row.id,
                    question: getStoredTextForDisplay(row.prompt_plain, row.prompt_html),
                    type: 'classify',
                    items,
                    classifications,
                    image: normalizeSheetText(row.image_url),
                    learningResources: getStoredTextForDisplay('', row.learning_resources_html),
                    learningResourcesHtml: normalizeSheetText(row.learning_resources_html),
                    learningResourcesImage: normalizeSheetText(row.learning_resources_image_url)
                };
            }).filter(Boolean);
            if (!questions.length) throw createStudyLoadDiagnosticError(`No usable classify questions were built for "${quizName}".`);
            return resolveSupabaseMediaReferencesForStudyLoad(questions, `Classify quiz "${quizName}"`);
        }

        const detailRows = await loadMultipleChoiceDetailsByQuestionIds(questionIds);
        const detailMap = new Map((detailRows || []).map(row => [row.question_id, row]));
        if (quizType === 'diagrams' && rows.length && rows.every(row => isTypedAnswerDetailRow(detailMap.get(row.id)))) {
            quizType = 'typed_answer';
        }
        assertExpectedDetailRowsForStudyLoad(questionIds, detailRows, quizType === 'typed_answer' ? 'typed-answer' : (quizType === 'diagrams' ? 'diagram/multiple-choice' : 'multiple-choice'), quizName);
        const questions = rows.map(row => {
            const detail = detailMap.get(row.id);
            if (!detail) return null;
            const optionDrafts = getMultipleChoiceDraftsFromDetailRow(detail);
            const questionImageLabels = quizType === 'multiple_choice' ? getQuestionImageLabelsFromDetailRow(detail) : [];
            const questionDiagramLabels = (quizType === 'diagrams' || quizType === 'typed_answer') ? getDiagramLabelsFromDetailRow(detail) : questionImageLabels;
            const useSharedDiagramImage = (quizType === 'diagrams' || quizType === 'typed_answer') && diagramSharing.useSharedImage ;
            const diagramLabels = useSharedDiagramImage && diagramSharing.useSharedLabels
                ? normalizeDiagramLabels(diagramSharing.sharedLabels)
                : questionDiagramLabels;
            const diagramImage = useSharedDiagramImage
                ? normalizeSheetText(effectiveSharedDiagramImageUrl)
                : normalizeSheetText(row.image_url);
            const options = optionDrafts.map(draft => draft.text);
            const optionImages = optionDrafts.map(draft => normalizeSheetText(draft.imageUrl));
            const optionAnswerValues = optionDrafts.map(getOptionAnswerValue);
            const explanations = optionDrafts.map(draft => draft.explanation);
            const correctAnswer = normalizeSheetText(detail.correct_answer);
            const correctAnswers = getMultipleChoiceCorrectAnswersFromDetailRow(detail);
            const allowMultipleAnswers = getAllowMultipleAnswersFromDetailRow(detail);
            const buildUp = (quizType === 'multiple_choice' || quizType === 'diagrams') ? getBuildUpValueFromOptionsJson(detail.options_json) : '';
            const correctIndex = optionAnswerValues.findIndex(optionValue => optionValue === correctAnswer);
            if (correctIndex >= 0 && !explanations[correctIndex]) {
                explanations[correctIndex] = getStoredTextForDisplay('', detail.correct_explanation_html);
            }
            correctAnswers.forEach(answer => {
                const answerIndex = optionAnswerValues.findIndex(optionValue => optionValue === answer);
                if (answerIndex >= 0 && !explanations[answerIndex]) {
                    explanations[answerIndex] = getStoredTextForDisplay('', detail.correct_explanation_html);
                }
            });
            if (quizType === 'typed_answer') {
                return {
                    id: `q_${state.questionIdCounter++}`,
                    sourceQuestionId: row.id,
                    sourceQuizId: normalizeSheetText(quizDescriptor.sourceQuizId),
                    question: getStoredTextForDisplay(row.prompt_plain, row.prompt_html),
                    type: 'typed answer',
                    acceptedAnswers: getTypedAnswerVariantsFromDetailRow(detail),
                    correct: correctAnswer || getTypedAnswerVariantsFromDetailRow(detail)[0] || '',
                    correctExplanation: getStoredTextForDisplay('', detail.correct_explanation_html),
                    image: diagramImage,
                    diagramLabels,
                    learningResources: getStoredTextForDisplay('', row.learning_resources_html),
                    learningResourcesHtml: normalizeSheetText(row.learning_resources_html),
                    learningResourcesImage: normalizeSheetText(row.learning_resources_image_url)
                };
            }
            return {
                id: `q_${state.questionIdCounter++}`,
                sourceQuestionId: row.id,
                sourceQuizId: normalizeSheetText(quizDescriptor.sourceQuizId),
                question: getStoredTextForDisplay(row.prompt_plain, row.prompt_html),
                type: quizType === 'diagrams' ? 'diagrams' : 'multiple choice',
                options,
                optionImages,
                correct: correctAnswer,
                correctAnswers: correctAnswers.length ? correctAnswers : (correctAnswer ? [correctAnswer] : []),
                allowMultipleAnswers,
                explanations,
                buildUp,
                image: quizType === 'diagrams' ? diagramImage : normalizeSheetText(row.image_url),
                diagramLabels,
                learningResources: getStoredTextForDisplay('', row.learning_resources_html),
                learningResourcesHtml: normalizeSheetText(row.learning_resources_html),
                learningResourcesImage: normalizeSheetText(row.learning_resources_image_url)
            };
        }).filter(Boolean);
        if (!questions.length) throw createStudyLoadDiagnosticError(`No usable ${quizType === 'typed_answer' ? 'typed-answer' : (quizType === 'diagrams' ? 'diagram' : 'multiple-choice')} questions were built for "${quizName}".`);
        return resolveSupabaseMediaReferencesForStudyLoad(questions, `${quizType === 'typed_answer' ? 'Typed-answer' : (quizType === 'diagrams' ? 'Diagram' : 'Multiple-choice')} quiz "${quizName}"`);
    } catch (error) {
        console.error('Failed to load Supabase quiz questions:', error);
        if (error?.studyLoadDiagnostic) throw error;
        throw createStudyLoadDiagnosticError(`Unexpected Supabase load failure for "${quizName}": ${error?.message || error}`);
    }
}

async function loadQuizList(options = {}) {
    if (!state.auth.user?.id) {
        return [];
    }

    const supabaseQuizzes = await loadQuizListFromSupabase(options);
    const folderDeckDescriptors = buildFolderDeckDescriptors(supabaseQuizzes);

    return [...supabaseQuizzes, ...folderDeckDescriptors];
}

async function loadQuestions(quizReference) {
    if (isQuizDescriptor(quizReference)) {
        if (quizReference.source === DATA_SOURCES.SUPABASE) {
            return loadQuestionsFromSupabase(quizReference);
        }

        return loadQuestionsFromGoogleSheets(quizReference.sheet);
    }

    if (state.activeDataSource === DATA_SOURCES.SUPABASE) {
        return loadQuestionsFromSupabase(quizReference);
    }

    return loadQuestionsFromGoogleSheets(quizReference);
}

// ================= DROPDOWNS =================
async function populateFolderDropdown(options = {}) {
    state.quizListCache = await loadQuizList(options);
    elements.folderSelector.innerHTML = '<option value="">Choose folder</option>';

    if (!state.auth.user?.id) {
        elements.folderSelector.innerHTML = '<option value="">Sign in required</option>';
        elements.folderSelector.value = '';
        elements.folderSelector.disabled = true;
        resetQuizSelector();
        renderGoogleSheetsImportControls();
        return state.quizListCache;
    }

    elements.folderSelector.disabled = false;
    getFolderNames().forEach(folderName => {
        const opt = document.createElement('option');
        opt.value = folderName;
        opt.innerText = folderName;
        elements.folderSelector.appendChild(opt);
    });

    elements.folderSelector.value = '';
    resetQuizSelector();
    renderGoogleSheetsImportControls();

    return state.quizListCache;
}

function populateQuizDropdown(folderName) {
    resetQuizSelector();

    if (!folderName) {
        return [];
    }

    const quizzesForFolder = state.quizListCache
        .filter(q => q.folder === folderName)
        .sort((a, b) => {
            if (a.source === DATA_SOURCES.FOLDER_DECK && b.source !== DATA_SOURCES.FOLDER_DECK) return -1;
            if (a.source !== DATA_SOURCES.FOLDER_DECK && b.source === DATA_SOURCES.FOLDER_DECK) return 1;
            if (Number(a.sortOrder ?? 0) !== Number(b.sortOrder ?? 0)) {
                return Number(a.sortOrder ?? 0) - Number(b.sortOrder ?? 0);
            }
            return String(a.name || '').localeCompare(String(b.name || ''));
        });

    quizzesForFolder.forEach(q => {
        const opt = document.createElement('option');
        opt.value = encodeQuizSelectorValue(q);
        opt.innerText = q.source === DATA_SOURCES.FOLDER_DECK ? 'Study Entire Folder' : q.name;
        elements.quizSelector.appendChild(opt);
    });

    elements.quizSelector.disabled = quizzesForFolder.length === 0;
    return quizzesForFolder;
}

async function loadSelectedQuiz(selectorValue, options = {}) {
    if (!state.auth.user?.id) {
        throw new Error('Sign in required');
    }

    const selectedQuiz = getQuizBySelectorValue(selectorValue);

    if (!selectedQuiz) {
        throw new Error('Quiz not found');
    }

    if (!options.preserveChallenge) {
        state.activeQuizChallenge = null;
    }
    state.activeQuizDescriptor = selectedQuiz;

    if (selectedQuiz.source !== DATA_SOURCES.SUPABASE && selectedQuiz.source !== DATA_SOURCES.FOLDER_DECK) {
        throw new Error('Only signed-in Supabase quizzes can be studied from the app. Import Google Sheets quizzes into Supabase first.');
    }

    const loadedQuestions = await loadQuestionsForQuizDescriptor(selectedQuiz);

    if (!loadedQuestions.length) {
        throw createStudyLoadDiagnosticError(`No usable questions were loaded for "${selectedQuiz.name || 'this quiz'}". This usually means the saved question rows do not match the quiz detail table, or every row was filtered out during study-load parsing.`);
    }

    await applyLoadedQuestions(loadedQuestions);
}

// ================= LOAD QUESTIONS =================

function normalizeSheetHeaderKey(value) {
    return normalizeSheetText(value).toLowerCase().replace(/[^a-z0-9]+/g, '');
}

function getSheetHeaderValues(rows) {
    return (rows[0]?.c || []).map(getCellValue);
}

function findSheetColumnByHeader(headers, candidateKeys) {
    const keys = new Set(candidateKeys.map(normalizeSheetHeaderKey));
    return headers.findIndex(header => keys.has(normalizeSheetHeaderKey(header)));
}

function parseMultipleChoiceOptionHeader(header) {
    const key = normalizeSheetHeaderKey(header);
    const match = key.match(/^option(\d+)$/) || key.match(/^answeroption(\d+)$/);
    return match ? Number(match[1]) : null;
}

function parseMultipleChoiceExplanationHeader(header) {
    const key = normalizeSheetHeaderKey(header);
    const match = key.match(/^option(\d+)explanation(?:html)?$/) || key.match(/^answeroption(\d+)explanation(?:html)?$/);
    return match ? Number(match[1]) : null;
}

function getMultipleChoiceSheetLayout(rows) {
    const headers = getSheetHeaderValues(rows);
    const optionColumns = headers
        .map((header, columnIndex) => ({ optionNumber: parseMultipleChoiceOptionHeader(header), columnIndex }))
        .filter(item => Number.isInteger(item.optionNumber) && item.optionNumber > 0)
        .sort((a, b) => a.optionNumber - b.optionNumber);

    const explanationColumns = new Map(headers
        .map((header, columnIndex) => ({ optionNumber: parseMultipleChoiceExplanationHeader(header), columnIndex }))
        .filter(item => Number.isInteger(item.optionNumber) && item.optionNumber > 0)
        .map(item => [item.optionNumber, item.columnIndex]));

    const correctColumn = findSheetColumnByHeader(headers, [
        'correct_option',
        'correct option',
        'correct option number',
        'correct option index',
        'correct_answer',
        'correct answer',
        'correct'
    ]);
    const correctHeaderKey = correctColumn >= 0 ? normalizeSheetHeaderKey(headers[correctColumn]) : '';
    const correctUsesOptionNumber = /correctoption|correctoptionnumber|correctoptionindex/.test(correctHeaderKey);

    const sectionColumn = findSheetColumnByHeader(headers, ['Section', 'Section number', 'Textbook section', 'Subsection']);
    const buildUpColumn = findSheetColumnByHeader(headers, ['build_up', 'Build Up', 'Build Up Group', 'String', 'Question String', 'Case String']);
    const imageColumn = findSheetColumnByHeader(headers, ['Question image URL', 'Question image', 'Image URL', 'Image']);
    const allowMultipleAnswersColumn = findSheetColumnByHeader(headers, ['allow_multiple_answers', 'Allow multiple answers', 'Multiple answers', 'Multi answer']);
    const learningResourcesColumn = findSheetColumnByHeader(headers, ['Learning resources', 'Learning resource', 'Resources']);
    const learningResourcesImageColumn = findSheetColumnByHeader(headers, ['Learning resources image URL', 'Learning resource image URL', 'Resources image URL']);

    if (optionColumns.length) {
        return {
            usesHeaders: true,
            optionColumns,
            explanationColumns,
            correctColumn,
            correctUsesOptionNumber,
            sectionColumn,
            buildUpColumn,
            allowMultipleAnswersColumn,
            imageColumn,
            learningResourcesColumn,
            learningResourcesImageColumn
        };
    }

    return {
        usesHeaders: false,
        optionColumns: [2, 3, 4, 5].map((columnIndex, index) => ({ optionNumber: index + 1, columnIndex })),
        explanationColumns: new Map([[1, 7], [2, 8], [3, 9], [4, 10]]),
        correctColumn: 6,
        correctUsesOptionNumber: false,
        sectionColumn: -1,
        buildUpColumn: -1,
        allowMultipleAnswersColumn: -1,
        imageColumn: 11,
        learningResourcesColumn: 12,
        learningResourcesImageColumn: 13
    };
}

function getFlashcardSheetLayout(rows) {
    const headers = getSheetHeaderValues(rows);
    const termColumn = findSheetColumnByHeader(headers, ['Term', 'Front', 'Flashcard term']);
    const definitionColumn = findSheetColumnByHeader(headers, ['Definition', 'Back', 'Flashcard definition']);
    const buildUpColumn = findSheetColumnByHeader(headers, ['build_up', 'Build Up', 'Build Up Group', 'String', 'Question String', 'Case String']);
    const termImageColumn = findSheetColumnByHeader(headers, ['Term image URL', 'Term image', 'Front image URL', 'Front image']);
    const definitionImageColumn = findSheetColumnByHeader(headers, ['Definition image URL', 'Definition image', 'Back image URL', 'Back image']);
    const learningResourcesColumn = findSheetColumnByHeader(headers, ['Learning resources', 'Learning resource', 'Resources']);
    const learningResourcesImageColumn = findSheetColumnByHeader(headers, ['Learning resources image URL', 'Learning resource image URL', 'Resources image URL']);
    const usesHeaders = termColumn >= 0 && definitionColumn >= 0;
    if (usesHeaders) {
        return { termColumn, definitionColumn, buildUpColumn, termImageColumn, definitionImageColumn, learningResourcesColumn, learningResourcesImageColumn };
    }
    return {
        termColumn: 0,
        definitionColumn: 2,
        buildUpColumn: -1,
        termImageColumn: 3,
        definitionImageColumn: 4,
        learningResourcesColumn: 5,
        learningResourcesImageColumn: 6
    };
}

function resolveMultipleChoiceCorrectAnswers(rawCorrect, optionDrafts, correctUsesOptionNumber = false) {
    const normalizedCorrect = normalizeSheetText(rawCorrect);
    if (!normalizedCorrect) return [];
    const parts = splitCorrectAnswerList(normalizedCorrect);
    const answerParts = parts.length ? parts : [normalizedCorrect];

    if (correctUsesOptionNumber) {
        return answerParts.map(part => {
            const optionNumberMatch = part.match(/^(?:option\s*)?(\d+)$/i);
            const optionNumber = optionNumberMatch ? Number(optionNumberMatch[1]) : NaN;
            if (Number.isInteger(optionNumber)) {
                return optionDrafts.find(option => option.optionNumber === optionNumber)?.text || '';
            }
            return '';
        }).filter(Boolean);
    }

    return answerParts;
}

function resolveMultipleChoiceCorrectAnswer(rawCorrect, optionDrafts, correctUsesOptionNumber = false) {
    return resolveMultipleChoiceCorrectAnswers(rawCorrect, optionDrafts, correctUsesOptionNumber)[0] || '';
}

function parseMultipleChoiceQuestionsFromGoogleSheetRows(rows) {
    const layout = getMultipleChoiceSheetLayout(rows);
    const dataRows = layout.usesHeaders ? rows.slice(1) : rows;

    return dataRows.map(r => {
        const c = r.c || [];
        const optionDrafts = layout.optionColumns.map(({ optionNumber, columnIndex }) => {
            const text = getCellValue(c[columnIndex]);
            const explanationColumn = layout.explanationColumns.get(optionNumber);
            return {
                optionNumber,
                text,
                explanation: Number.isInteger(explanationColumn) ? getCellValue(c[explanationColumn]) : ''
            };
        }).filter(option => normalizeSheetText(option.text));

        const rawCorrect = layout.correctColumn >= 0 ? getCellValue(c[layout.correctColumn]) : '';
        const correctAnswers = resolveMultipleChoiceCorrectAnswers(rawCorrect, optionDrafts, layout.correctUsesOptionNumber);
        const allowMultipleAnswers = parseAllowMultipleAnswersValue(layout.allowMultipleAnswersColumn >= 0 ? getCellValue(c[layout.allowMultipleAnswersColumn]) : '') || correctAnswers.length > 1;

        return {
            id: `q_${state.questionIdCounter++}`,
            question: getCellValue(c[0]),
            type: 'multiple choice',
            options: optionDrafts.map(option => option.text),
            optionImages: optionDrafts.map(() => ''),
            correct: correctAnswers[0] || '',
            correctAnswers,
            allowMultipleAnswers,
            explanations: optionDrafts.map(option => option.explanation),
            section: layout.sectionColumn >= 0 ? getSectionCellValue(c[layout.sectionColumn]) : '',
            buildUp: layout.buildUpColumn >= 0 ? normalizeBuildUpValue(getCellValue(c[layout.buildUpColumn])) : '',
            image: layout.imageColumn >= 0 ? getCellValue(c[layout.imageColumn]) : '',
            learningResources: layout.learningResourcesColumn >= 0 ? getCellValue(c[layout.learningResourcesColumn]) : '',
            learningResourcesImage: layout.learningResourcesImageColumn >= 0 ? getCellValue(c[layout.learningResourcesImageColumn]) : ''
        };
    }).filter(q => q.question && q.question.toLowerCase() !== 'question');
}

function parseQuestionsFromGoogleSheetRows(rows) {
    const type = getCellValue(rows[0]?.c?.[1]).toLowerCase();

    if (type === 'hierarchy') {
        return rows.map(r => {
            const c = r.c || [];
            return {
                id: `q_${state.questionIdCounter++}`,
                question: getCellValue(c[0]),
                type: 'hierarchy',
                options: [
                    getCellValue(c[2]),
                    getCellValue(c[3]),
                    getCellValue(c[4]),
                    getCellValue(c[5]),
                    getCellValue(c[6]),
                    getCellValue(c[7]),
                    getCellValue(c[8]),
                    getCellValue(c[9]),
                    getCellValue(c[10]),
                    getCellValue(c[11])
                ].filter(Boolean),
                correctOrder: [
                    getCellValue(c[12]),
                    getCellValue(c[13]),
                    getCellValue(c[14]),
                    getCellValue(c[15]),
                    getCellValue(c[16]),
                    getCellValue(c[17]),
                    getCellValue(c[18]),
                    getCellValue(c[19]),
                    getCellValue(c[20]),
                    getCellValue(c[21])
                ]
                    .map(n => n ? Number(n) : null)
                    .filter(n => n !== null),
                image: getCellValue(c[22]),
                learningResources: getCellValue(c[23]),
                learningResourcesImage: getCellValue(c[24])
            };
        }).filter(q => q.question && q.question.toLowerCase() !== 'question');
    }

    if (type === 'flashcard') {
        const layout = getFlashcardSheetLayout(rows);
        return rows.slice(1).map(r => {
            const c = r.c || [];
            return {
                id: `q_${state.questionIdCounter++}`,
                type: 'flashcard',
                termText: getCellValue(c[layout.termColumn]),
                definitionText: getCellValue(c[layout.definitionColumn]),
                buildUp: layout.buildUpColumn >= 0 ? normalizeBuildUpValue(getCellValue(c[layout.buildUpColumn])) : '',
                termImage: layout.termImageColumn >= 0 ? getCellValue(c[layout.termImageColumn]) : '',
                definitionImage: layout.definitionImageColumn >= 0 ? getCellValue(c[layout.definitionImageColumn]) : '',
                learningResources: layout.learningResourcesColumn >= 0 ? getCellValue(c[layout.learningResourcesColumn]) : '',
                learningResourcesImage: layout.learningResourcesImageColumn >= 0 ? getCellValue(c[layout.learningResourcesImageColumn]) : ''
            };
        }).filter(q => q.termText || q.definitionText || q.termImage || q.definitionImage);
    }

    if (type === 'classify') {
        return rows.map(r => {
            const c = r.c || [];
            const classLabelsStartCol = 2 + (CONFIG.classifyItemCount * 2);
            const classIdsStartCol = classLabelsStartCol + CONFIG.classifyClassCount;
            const imageCol = classIdsStartCol + CONFIG.classifyClassCount;
            const learningResourceCol = imageCol + 1;
            const learningResourceImageCol = imageCol + 2;

            const items = Array.from({ length: CONFIG.classifyItemCount }, (_, i) => {
                const itemCol = 2 + (i * 2);
                const itemClassIdCol = itemCol + 1;
                const parsedItem = parseClassifyItemValue(getCellValue(c[itemCol]));
                if (!parsedItem) return null;

                return {
                    ...parsedItem,
                    correctClassificationId: normalizeClassificationId(getCellValue(c[itemClassIdCol]))
                };
            }).filter(Boolean);

            const classifications = Array.from({ length: CONFIG.classifyClassCount }, (_, i) => ({
                label: getCellValue(c[classLabelsStartCol + i]),
                id: normalizeClassificationId(getCellValue(c[classIdsStartCol + i]))
            })).filter(classification => classification.label && classification.id);

            return {
                id: `q_${state.questionIdCounter++}`,
                question: getCellValue(c[0]),
                type: 'classify',
                items,
                classifications,
                image: getCellValue(c[imageCol]),
                learningResources: getCellValue(c[learningResourceCol]),
                learningResourcesImage: getCellValue(c[learningResourceImageCol])
            };
        }).filter(q =>
            q.question &&
            q.question.toLowerCase() !== 'question' &&
            q.items.length > 0 &&
            q.classifications.length > 0
        );
    }

    return parseMultipleChoiceQuestionsFromGoogleSheetRows(rows);
}

async function loadQuestionsFromGoogleSheetDocument(sheetId, sheetName) {
    const rows = await fetchGoogleSheetRows(sheetId, sheetName);
    return parseQuestionsFromGoogleSheetRows(rows);
}

async function loadQuestionsFromGoogleSheets(sheetName) {
    return loadQuestionsFromGoogleSheetDocument(CONFIG.sheetId, sheetName);
}

// ================= SHUFFLE =================
function shuffleArray(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
    }
}

