if (elements.reviewModeVisualAidLabelLayer) {
    elements.reviewModeVisualAidLabelLayer.addEventListener('click', event => {
        const button = event.target.closest('[data-review-flow-label-id]');
        if (!button) return;
        const review = getReviewModeState();
        event.preventDefault();
        event.stopPropagation();
        if (review.miniQuiz.active) {
            if (!review.miniQuiz.complete && !review.miniQuiz.answerRevealed) {
                if (review.typedMiniQuiz) focusReviewModeTypedAnswerInput();
                else revealReviewModeMiniQuizAnswer();
            }
            return;
        }
        const aid=getReviewModeActiveVisualAid();
        if (!aid || aid.flowFillType !== 'flow-fill') return;
        const kind=button.dataset.reviewFlowLabelKind;
        const id=button.dataset.reviewFlowLabelId;
        const selected=getDiagramVisualAidSelectableItems(aid).find(item=>item.type===kind && item.id===id);
        if (!selected) return;
        stopReviewModeVisualAidAnimation();
        review.visualAidSelectedKind=kind;
        review.visualAidSelectedId=id;
        review.visualAidProgress=normalizeDiagramVisualAidPosition(selected.position);
        review.visualAidStartedAt=0;
        renderReviewModeVisualAids();
    });
}

if (elements.reviewModeLabelLayer) {
    elements.reviewModeLabelLayer.addEventListener('pointerdown', event => {
        const visualPrompt = event.target.closest('.review-mode-mini-visual-prompt-wrap');
        if (visualPrompt) {
            beginReviewModeMiniVisualPromptDrag(event, visualPrompt);
            if (reviewModeMiniVisualPromptDrag) return;
        }
        const marker = event.target.closest('[data-review-label-index]');
        if (marker?.classList.contains('review-mode-mini-typed-card') && event.target.closest('input, button')) return;
        if (marker) beginReviewModeLabelDrag(event, marker);
    });
    elements.reviewModeLabelLayer.addEventListener('pointermove', event => {
        if (reviewModeMiniVisualPromptDrag) return moveReviewModeMiniVisualPromptDrag(event);
        moveReviewModeLabelDrag(event);
    });
    elements.reviewModeLabelLayer.addEventListener('pointerup', event => {
        if (reviewModeMiniVisualPromptDrag) return endReviewModeMiniVisualPromptDrag(event);
        endReviewModeLabelDrag(event);
    });
    elements.reviewModeLabelLayer.addEventListener('pointercancel', event => {
        if (reviewModeMiniVisualPromptDrag) return endReviewModeMiniVisualPromptDrag(event);
        endReviewModeLabelDrag(event);
    });
    elements.reviewModeLabelLayer.addEventListener('lostpointercapture', event => {
        if (reviewModeMiniVisualPromptDrag) return endReviewModeMiniVisualPromptDrag(event);
        endReviewModeLabelDrag(event);
    });
    elements.reviewModeLabelLayer.addEventListener('input', event => {
        const input = event.target.closest('[data-review-mini-typed-input]');
        if (!input) return;
        const review = getReviewModeState();
        if (!review.typedMiniQuiz || !review.miniQuiz.active || review.miniQuiz.complete) return;
        review.miniQuiz.typedValue = input.value;
        if (review.miniQuiz.typedResult === 'empty' || review.miniQuiz.typedResult === 'retry') review.miniQuiz.typedResult = '';
    });
    elements.reviewModeLabelLayer.addEventListener('keydown', event => {
        if (!event.target.closest('[data-review-mini-typed-input]') || event.key !== 'Enter') return;
        event.preventDefault();
        event.stopPropagation();
        submitReviewModeMiniQuizTypedAnswer();
    });
    elements.reviewModeLabelLayer.addEventListener('click', event => {
        const review = getReviewModeState();
        const typedCheck = event.target.closest('[data-review-mini-typed-check]');
        if (typedCheck && review.miniQuiz.active && !review.miniQuiz.complete) {
            event.preventDefault();
            event.stopPropagation();
            submitReviewModeMiniQuizTypedAnswer();
            return;
        }
        const typedNext = event.target.closest('[data-review-mini-typed-next]');
        if (typedNext && review.miniQuiz.active && !review.miniQuiz.complete) {
            event.preventDefault();
            event.stopPropagation();
            advanceReviewModeMiniQuizTypedAnswer();
            return;
        }
        const miniAnswer = event.target.closest('[data-review-mini-answer]');
        if (miniAnswer && review.miniQuiz.active && !review.miniQuiz.complete) {
            event.preventDefault();
            event.stopPropagation();
            advanceReviewModeMiniQuiz(miniAnswer.dataset.reviewMiniAnswer === 'know');
            return;
        }
        const visualReveal = event.target.closest('[data-review-mini-visual-reveal]');
        if (visualReveal && review.miniQuiz.active && !review.miniQuiz.complete) {
            event.preventDefault();
            event.stopPropagation();
            if (Date.now() < review.suppressMiniVisualPromptClickUntil) {
                review.suppressMiniVisualPromptClickUntil = 0;
                return;
            }
            if (!review.typedMiniQuiz && !review.miniQuiz.answerRevealed) revealReviewModeMiniQuizAnswer();
            return;
        }
        const marker = event.target.closest('[data-review-label-index]');
        if (!marker) return;
        if (Date.now() < review.suppressLabelClickUntil) {
            review.suppressLabelClickUntil = 0;
            event.preventDefault();
            return;
        }
        if (review.miniQuiz.active) {
            event.preventDefault();
            if (review.typedMiniQuiz) return;
            if (!review.miniQuiz.complete && !review.miniQuiz.answerRevealed) revealReviewModeMiniQuizAnswer();
            return;
        }
        const index = Number(marker.dataset.reviewLabelIndex);
        if (!Number.isInteger(index) || index < 0) return;
        review.focusLabelIndex = index;
        review.pinSelectedLabelIndex = index;
        const wasShowingAllNames = review.showAllNames;
        const previouslyRevealed = review.soloLabels ? Array.from(review.revealedLabels) : [];
        if (review.showAllNames) {
            review.showAllNames = false;
            if (review.soloLabels) {
                // A tap exits explicit Show All and focuses only that label.
                review.revealedLabels = new Set([index]);
            } else {
                review.revealedLabels = new Set(normalizeDiagramLabels(getActiveReviewModeAngle(getActiveReviewModeEntry())?.labels || []).map((_, labelIndex) => labelIndex));
                review.revealedLabels.delete(index);
            }
        } else if (review.revealedLabels.has(index)) {
            review.revealedLabels.delete(index);
        } else if (review.soloLabels) {
            review.revealedLabels = new Set([index]);
        } else {
            review.revealedLabels.add(index);
        }
        // Update the old marker before the new one, using the warmed snapshot;
        // both mutations share the existing coalesced post-paint layout pass.
        let updatedInPlace = !wasShowingAllNames;
        if (!wasShowingAllNames) {
            for (const oldIndex of previouslyRevealed) {
                if (oldIndex !== index && !review.revealedLabels.has(oldIndex)) {
                    const updated = updateReviewModeLabelToggleInPlace(oldIndex);
                    updatedInPlace = updatedInPlace && updated;
                }
            }
            const updated = updateReviewModeLabelToggleInPlace(index);
            updatedInPlace = updatedInPlace && updated;
        }
        if (!updatedInPlace) {
            renderReviewModeLabels();
            syncReviewModeControls();
        }
        syncReviewModePinButton();
    });
}

window.addEventListener('resize', () => {
    if (getReviewModeState().overlayOpen) requestAnimationFrame(() => { syncReviewModeImageStage(); applyReviewModeShortcutDockPosition(); });
});
window.addEventListener('orientationchange', () => {
    if (getReviewModeState().overlayOpen) setTimeout(() => { syncReviewModeImageStage(); applyReviewModeShortcutDockPosition(); }, 120);
});

document.addEventListener('keydown', event => {
    const review = getReviewModeState();
    if (event.key === 'Escape' && review.overlayOpen) {
        event.preventDefault();
        if (review.miniQuiz.active && review.miniQuiz.roundCheckpoint) endReviewModeMiniQuiz();
        else closeReviewModeImage();
        return;
    }
    if (!review.overlayOpen || event.ctrlKey || event.metaKey || event.altKey) return;
    const key = String(event.key || '');
    if (review.miniQuiz.active && review.miniQuiz.roundCheckpoint) {
        // Prevent keyboard shortcuts from answering the previous round behind the checkpoint.
        if (key === 'ArrowRight' || key === ' ' || key === 'Spacebar') { event.preventDefault(); return; }
    }
    if (review.miniQuiz.active && !review.miniQuiz.complete && key === 'ArrowRight') {
        event.preventDefault();
        event.stopPropagation();
        answerReviewModeMiniQuizCorrectFromShortcut();
        return;
    }
    if (event.target?.matches?.('input, textarea, select, [contenteditable="true"]')) return;
    const lowerKey = key.toLowerCase();
    if (key === ' ' || key === 'Spacebar') {
        event.preventDefault();
        if (event.repeat) return;
        cycleReviewModeFocusMode();
    } else if (key === '+' || key === '=' || key === 'Add') {
        event.preventDefault();
        nudgeReviewModeLabelSize(1);
    } else if (key === '-' || key === '_' || key === 'Subtract') {
        event.preventDefault();
        nudgeReviewModeLabelSize(-1);
    } else if (lowerKey === 'd') {
        event.preventDefault();
        toggleReviewModeColor();
    } else if (lowerKey === 'c') {
        event.preventDefault();
        toggleReviewModeLines();
    } else if (lowerKey === 'a') {
        event.preventDefault();
        toggleReviewModeAllInformation();
    } else if (lowerKey === 'h') {
        event.preventDefault();
        setReviewModeShortcutDockVisible(!review.shortcutDockVisible);
    } else if (!review.miniQuiz.active && key === 'ArrowLeft') {
        event.preventDefault();
        changeReviewModeAngle(-1);
    } else if (!review.miniQuiz.active && key === 'ArrowRight') {
        event.preventDefault();
        changeReviewModeAngle(1);
    }
});

