if (elements.studioQuizList) {
    elements.studioQuizList.addEventListener('click', e => {
        const pagingButton = e.target.closest('[data-action="quiz-previous-page"], [data-action="quiz-next-page"]');
        if (pagingButton && !pagingButton.disabled) {
            state.auth.studioQuizPage += pagingButton.dataset.action === 'quiz-next-page' ? 1 : -1;
            renderQuizManagementList();
            elements.studioQuizList.closest('.quiz-studio-panel')?.scrollIntoView({ block: 'start', behavior: 'auto' });
            return;
        }
        const classGroup = e.target.closest('[data-class-group-id]');
        const classActionButton = e.target.closest('[data-action]');
        if (classGroup && classActionButton && classGroup.contains(classActionButton)) {
            const classId = normalizeSheetText(classGroup.dataset.classGroupId);
            const classAction = classActionButton.dataset.action || '';
            if (classAction === 'toggle-class-folder-add') {
                state.auth.studioClassQuickAddOpenId = state.auth.studioClassQuickAddOpenId === classId ? '' : classId;
                renderQuizManagementList();
                return;
            }
            if (classAction === 'close-class-folder-add') {
                state.auth.studioClassQuickAddOpenId = '';
                renderQuizManagementList();
                return;
            }
            if (classAction === 'quick-add-folder-to-class') {
                const folderRow = e.target.closest('[data-class-add-folder-id]');
                handleQuickAddFolderToClass(classId, folderRow?.dataset.classAddFolderId || '').catch(err => {
                    console.error(err);
                    setCreatorStatus('Could not add that folder to the class.', 'error');
                });
                return;
            }
        }

        const quizProgressButton = e.target.closest('[data-study-progress^="quiz:"]');
        if (quizProgressButton && elements.studioQuizList.contains(quizProgressButton)) {
            e.preventDefault();
            e.stopPropagation();
            toggleSavedImageStudyProgress(quizProgressButton.dataset.studyProgress, elements.studioQuizList);
            return;
        }
        const item = e.target.closest('[data-quiz-id]');
        if (!item) return;

        const actionButton = e.target.closest('[data-action]');
        if (!actionButton || !item.contains(actionButton)) return;

        const quizId = item.dataset.quizId;
        const action = actionButton.dataset.action || '';
        if (action === 'toggle-challenges') {
            if (state.auth.expandedQuizChallengeIds.has(quizId)) {
                state.auth.expandedQuizChallengeIds.delete(quizId);
            } else {
                state.auth.expandedQuizChallengeIds.add(quizId);
            }
            state.auth.openQuizActionMenuId = '';
            state.auth.openQuizActionSubmenu = '';
            renderQuizManagementList();
            return;
        }

        if (action === 'toggle-quiz-actions') {
            const opening = state.auth.openQuizActionMenuId !== quizId;
            state.auth.openQuizActionMenuId = opening ? quizId : '';
            state.auth.openQuizActionSubmenu = '';
            renderQuizManagementList();
            return;
        }

        if (action === 'toggle-duplicate-options' || action === 'toggle-create-flashcards-options' || action === 'toggle-star-options') {
            const submenuType = action === 'toggle-duplicate-options'
                ? 'duplicate'
                : action === 'toggle-create-flashcards-options'
                    ? 'flashcards'
                    : 'star';
            const submenuKey = `${quizId}:${submenuType}`;
            state.auth.openQuizActionMenuId = quizId;
            state.auth.openQuizActionSubmenu = state.auth.openQuizActionSubmenu === submenuKey ? '' : submenuKey;
            renderQuizManagementList();
            return;
        }

        if (action === 'reset-starred') {
            state.auth.openQuizActionMenuId = '';
            state.auth.openQuizActionSubmenu = '';
            renderQuizManagementList();
            resetStarredQuestionsForQuiz(quizId).catch(err => {
                console.error(err);
                setCreatorStatus('Could not reset starred questions.', 'error');
            });
            return;
        }

        if (action === 'switch-starred') {
            state.auth.openQuizActionMenuId = '';
            state.auth.openQuizActionSubmenu = '';
            renderQuizManagementList();
            switchStarredQuestionsForQuiz(quizId).catch(err => {
                console.error(err);
                setCreatorStatus('Could not switch starred questions.', 'error');
            });
            return;
        }

        if (action === 'delete-starred') {
            state.auth.openQuizActionMenuId = '';
            state.auth.openQuizActionSubmenu = '';
            renderQuizManagementList();
            deleteStarredQuestionsForQuiz(quizId).catch(err => {
                console.error(err);
                setCreatorStatus('Could not delete starred questions.', 'error');
            });
            return;
        }

        if (action === 'save-quiz') {
            const nameInput = item.querySelector('[data-quiz-rename-input]');
            const folderSelect = item.querySelector('[data-quiz-folder-select]');
            state.auth.openQuizActionMenuId = '';
            handleSaveQuizMeta(quizId, nameInput?.value || '', folderSelect?.value || '').catch(err => {
                console.error(err);
                setCreatorStatus('Could not update the quiz.', 'error');
            });
        }

        if (action === 'edit-quiz') {
            state.auth.openQuizActionMenuId = '';
            recordStudioQuizActivity(quizId, 'edited').catch(err => console.warn(err));
            loadQuizIntoEditor(quizId).catch(err => {
                console.error(err);
                setCreatorStatus('Could not load the quiz editor.', 'error');
            });
        }

        if (action === 'duplicate-quiz-all' || action === 'duplicate-quiz-starred' || action === 'duplicate-quiz-unstarred') {
            const duplicateMode = action === 'duplicate-quiz-starred'
                ? 'starred'
                : action === 'duplicate-quiz-unstarred'
                    ? 'unstarred'
                    : 'all';
            state.auth.openQuizActionMenuId = '';
            state.auth.openQuizActionSubmenu = '';
            renderQuizManagementList();
            handleDuplicateQuiz(quizId, duplicateMode).catch(err => {
                console.error(err);
                setCreatorStatus('Could not duplicate the quiz.', 'error');
            });
            return;
        }

        if (action === 'create-flashcards-all' || action === 'create-flashcards-starred') {
            const conversionMode = action === 'create-flashcards-starred' ? 'starred' : 'all';
            state.auth.openQuizActionMenuId = '';
            state.auth.openQuizActionSubmenu = '';
            renderQuizManagementList();
            handleCreateFlashcardsFromQuiz(quizId, conversionMode).catch(err => {
                console.error(err);
                setCreatorStatus('Could not create the flashcard quiz.', 'error');
            });
            return;
        }

        if (action === 'delete-quiz') {
            state.auth.openQuizActionMenuId = '';
            renderQuizManagementList();
            handleDeleteQuiz(quizId).catch(err => {
                console.error(err);
                setCreatorStatus('Could not delete the quiz.', 'error');
            });
        }

        if (action === 'load-quiz') {
            state.auth.openQuizActionMenuId = '';
            recordStudioQuizActivity(quizId, 'studied').catch(err => console.warn(err));
            studySupabaseQuizFromStudio(quizId).catch(err => {
                console.error(err);
                setCreatorStatus(getStudyLoadErrorMessage(err), 'error');
            });
        }

        if (action === 'begin-challenge') {
            const challengeKey = actionButton.dataset.challengeKey || '';
            state.auth.openQuizActionMenuId = '';
            recordStudioQuizActivity(quizId, 'challenge_started').catch(err => console.warn(err));
            beginQuizChallenge(quizId, challengeKey).catch(err => {
                console.error(err);
                setCreatorStatus(err?.studyLoadDiagnostic ? getStudyLoadErrorMessage(err) : 'Could not start that challenge.', 'error');
            });
        }
    });
}


